/* gb-fonts.css: Noto Sans JP 同梱 (default-font 計画) */
/* 日本語サブセット 3 ウェイト (Regular/Medium/Bold) を app/fonts/ から配信 */
/* Noto Sans JP, Copyright 2014-2024 Adobe (http://www.adobe.com/), with Reserved Font Name 'Source'. SIL OFL 1.1. */

@font-face {
  font-family: 'Noto Sans JP';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("fonts/NotoSansJP-Regular.woff2") format('woff2');
}

@font-face {
  font-family: 'Noto Sans JP';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("fonts/NotoSansJP-Medium.woff2") format('woff2');
}

@font-face {
  font-family: 'Noto Sans JP';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("fonts/NotoSansJP-Bold.woff2") format('woff2');
}

/* gb-icon-assets.css - shared Lucide / Noto Emoji picker */

@font-face {
  font-family: 'Meldex Noto Emoji';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("fonts/NotoColorEmoji_WindowsCompatible.ttf") format('truetype');
}

.gb-icon-render {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--gb-icon-size, 20px);
  height: var(--gb-icon-size, 20px);
  line-height: 1;
  vertical-align: -0.2em;
  flex-shrink: 0;
}

.gb-noto-emoji {
  font-family: 'Meldex Noto Emoji', 'Noto Color Emoji', 'Apple Color Emoji', 'Segoe UI Emoji', sans-serif;
  font-size: var(--gb-icon-size, 20px);
  color: initial;
}

.gb-icon-text {
  font-size: calc(var(--gb-icon-size, 20px) * 0.72);
  color: currentColor;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gb-icon-picker,
.gb-context-menu.gb-icon-picker {
  width: min(420px, calc(100vw - 16px));
  max-height: min(680px, 72vh);
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
  /* gb-context-menu の padding (4px 0) を確実に上書きするため 2 クラスセレクタで指定 */
  padding: 10px;
  background: var(--ui-popup-bg, var(--bg2));
  color: var(--fg);
  border: 1px solid var(--ui-popup-border, var(--ui-border-strong, var(--border)));
  border-radius: 8px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
}
/* gb-context-menu のグローバルルール (.gb-context-menu > div / :hover) が
   ヘッダ・タブ・検索欄・グリッド等の段落全体に padding や hover 背景を被せてしまうのを無効化。
   picker 本体の段落は menu-item ではないため、hover 背景は各セル (.gb-icon-picker-cell
   / .gb-icon-picker-preset / .gb-icon-picker-close) 側の定義だけに任せる。 */
.gb-context-menu.gb-icon-picker > div { padding: 0; cursor: default; font-size: inherit; }
.gb-context-menu.gb-icon-picker > div:hover { background: transparent; }

.gb-icon-picker-header,
.gb-icon-picker-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-shrink: 0;
}

.gb-icon-picker-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--fg);
}

.gb-icon-picker-close {
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  background: transparent;
  color: var(--fg2);
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
}

.gb-icon-picker-close:hover {
  background: var(--bg3);
  color: var(--fg);
  border-color: var(--border);
}

.gb-icon-picker-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  flex-shrink: 0;
}

.gb-icon-picker-tab {
  flex: 0 1 auto;
  min-width: 0;
  padding: 5px 8px;
  background: var(--bg3);
  color: var(--fg2);
  border: 1px solid var(--border);
  border-radius: 5px;
  cursor: pointer;
  font-size: 11px;
}

.gb-icon-picker-tab.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.gb-icon-picker-search {
  width: 100%;
  box-sizing: border-box;
  flex-shrink: 0;
}

.gb-icon-picker-grid {
  flex: 1 1 auto;
  min-height: min(160px, 28vh);
  overflow: auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(34px, 1fr));
  gap: 4px;
  padding-right: 2px;
}

.gb-icon-picker-cell {
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  cursor: pointer;
}

.gb-icon-picker-cell:hover,
.gb-icon-picker-preset:hover {
  background: var(--bg4);
}

.gb-icon-picker-cell.is-selected,
.gb-icon-picker-preset.is-selected {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.gb-icon-picker-empty {
  grid-column: 1 / -1;
  padding: 20px 8px;
  color: var(--fg2);
  font-size: 12px;
  text-align: center;
}

.gb-icon-picker-more {
  grid-column: 1 / -1;
  min-height: 30px;
  padding: 5px 8px;
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  cursor: pointer;
  font-size: 11px;
}

.gb-icon-picker-more:hover {
  background: var(--bg4);
}

.gb-icon-picker-presets {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  max-height: min(132px, 22vh);
  min-height: 0;
  overflow: auto;
  flex: 0 1 auto;
  padding-bottom: 2px;
}

.gb-icon-picker-preset {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 30px;
  padding: 4px 8px;
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  cursor: pointer;
  font-size: 12px;
  text-align: left;
}

.gb-icon-picker-preset span:last-child {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.gb-icon-picker-preset-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.gb-icon-picker-footer {
  border-top: 1px solid var(--border);
  padding-top: 6px;
}

.gb-icon-picker-credit {
  min-width: 0;
  color: var(--fg2);
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gb-icon-picker-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

@media (pointer: coarse), (max-width: 640px) {
  .gb-icon-picker,
  .gb-context-menu.gb-icon-picker {
    width: min(420px, calc(100vw - 16px));
    max-height: min(680px, calc(100dvh - 16px));
    gap: 10px;
  }

  .gb-icon-picker-close {
    width: 44px;
    height: 44px;
    min-width: 44px;
    min-height: 44px;
  }

  .gb-icon-picker-tab,
  .gb-icon-picker-preset,
  .gb-icon-picker-more,
  .gb-icon-picker-actions .gb-btn {
    min-height: 44px;
  }

  .gb-icon-picker-search {
    min-height: 44px;
  }

  .gb-icon-picker-grid {
    grid-template-columns: repeat(auto-fill, minmax(44px, 1fr));
  }

  .gb-icon-picker-cell {
    width: 44px;
    height: 44px;
    min-width: 44px;
    min-height: 44px;
  }
}

/* ==============================
   リセット・基本
   ============================== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html {
  width: 100%;
  height: 100%;
  overflow: hidden;
  color-scheme: dark;
  scrollbar-color: var(--ui-scrollbar-thumb-bg, var(--bg4)) var(--ui-scrollbar-track-bg, var(--bg2));
}
html[data-desktop-launch="1"] {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  max-width: none;
  max-height: none;
}
html[data-desktop-launch="1"] body {
  position: fixed;
  inset: 0;
  display: flex;
  width: auto;
  height: auto;
  min-width: 0;
  min-height: 0;
  max-width: none;
  max-height: none;
}
body {
  display: flex; flex-direction: row; width: 100%; height: 100%; min-width: 0; min-height: 0; overflow: hidden;
  /* 通常文字の書式設定（--ui-text-*）をアプリ全体に反映。
     未設定時は既存のフォント/サイズ/ウェイトに戻る */
  background-color: var(--ui-text-bg, transparent);
  font-size: var(--ui-text-font-size, inherit);
  font-weight: var(--ui-text-bold, inherit);
  font-style: var(--ui-text-italic, inherit);
}
html.light-theme { color-scheme: light; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--ui-scrollbar-track-bg, var(--bg2)); }
::-webkit-scrollbar-thumb { background: var(--ui-scrollbar-thumb-bg, var(--bg4)); border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: var(--ui-scrollbar-thumb-hover-bg, var(--fg2)); }
input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
input[type=number] { -moz-appearance: textfield; }
/* カスタムツールチップ */
.gb-tooltip {
  position: fixed; z-index: 99999; pointer-events: none;
  background: var(--ui-tooltip-bg, var(--ui-popup-bg, var(--bg2, #252525))); color: var(--ui-tooltip-fg, var(--fg, #d4d4d4));
  border: 1px solid var(--ui-tooltip-border, var(--ui-popup-border, var(--ui-border-strong, var(--border, #333333)))); border-radius: 3px;
  padding: 3px 8px; font-size: 11px; white-space: nowrap;
  box-shadow: 0 2px 6px rgba(0,0,0,0.3);
  opacity: 0; transition: opacity 0.15s;
}
.gb-tooltip.visible { opacity: 1; }

