.pivot-table th { background: var(--ui-header-bg); color: var(--ui-header-fg); font-family: var(--db-th-font, var(--ui-header-font, var(--ui-font, inherit))); font-weight: var(--db-th-bold, bold); font-style: var(--db-th-italic, normal); text-align: left; padding: 4px 8px; white-space: nowrap; user-select: none; position: relative; cursor: pointer; font-size: var(--db-th-font-size, 12px); border: var(--db-show-grid, 0px) solid var(--db-grid-border, var(--border)); }
