.meldex-chat-listbox-popup[hidden] { display: none; }
.meldex-chat-listbox-popup [role="option"] { display: block; width: 100%; padding: 6px 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: left; background: transparent; color: var(--fg); border: 0; border-radius: 4px; cursor: pointer; }
.meldex-chat-listbox-popup [role="option"]:hover,
.meldex-chat-listbox-popup [role="option"][aria-selected="true"] { background: var(--bg4); }
