  position: relative; overflow: visible;
  z-index: 20; touch-action: none;
  --gb-split-anchor-x: 50%;
  --gb-split-anchor-y: 50%;
}
.gb-split-horizontal > .gb-split-handle { width: 4px; cursor: col-resize; }
.gb-split-vertical > .gb-split-handle { height: 4px; cursor: row-resize; }
.gb-split-handle:hover, .gb-split-handle.active { background: var(--accent); }
.gb-split-handle.gb-split-handle-fixed {
  cursor: default;
  pointer-events: none;
}
.gb-split-handle.gb-split-handle-fixed:hover,
.gb-split-handle.gb-split-handle-fixed.active {
  background: transparent;
}
.gb-split-handle.gb-split-handle-resize-only {
  cursor: col-resize;
}
.gb-split-vertical > .gb-split-handle.gb-split-handle-resize-only {
  cursor: row-resize;
}

/* 掴みやすさ向上: 本体は 4px のまま、擬似要素で当たり判定を 8px に拡張 */
.gb-split-handle::before {
  content: ""; position: absolute; z-index: 1;
  background: transparent; transition: background 0.15s;
}
.gb-split-handle.gb-split-handle-fixed::before {
  display: none;
}
.gb-split-horizontal > .gb-split-handle::before {
  top: 0; bottom: 0; left: -2px; right: -2px;
  cursor: col-resize;
}
.gb-split-vertical > .gb-split-handle::before {
  left: 0; right: 0; top: -2px; bottom: -2px;
  cursor: row-resize;
}
/* 当たり判定は隣のパネル側へ 2〜4px はみ出しているため、ここに色を付けるとパネル内で開いた
   ポップアップ（シートのセルのメニュー・選択肢リスト等）の上へハイライトが重なって見える。
   ハイライトはハンドル本体（4px、はみ出さない）の :hover / .active に任せ、当たり判定は透明のままにする。 */

/* ドロップインジケータ */
.gb-drop-indicator {
  position: fixed; pointer-events: none; z-index: 9999;
  background: color-mix(in srgb, var(--ui-selection-bg) 40%, transparent);
  border: 2px solid var(--accent);
  border-radius: 4px;
  transition: all 0.1s;
}

/* === タッチフレンドリー: pointer:coarse === */
@media (pointer: coarse) {
  /* Part 3-1: タブ×ボタン常時表示 */
  .tab-item .tab-close { opacity: 0.5; }
  .gb-tab .gb-tab-close { opacity: 0.5; }
  .gb-tab .gb-tab-more { display: none; }
  /* Part 3-5: パネル制御ボタン常時表示 */
  .gb-pane-collapse { opacity: 0.8; }
  .gb-pane-btn { opacity: 0.9; }
  /* Part 2-3: 分割ハンドル折りたたみボタン */
  .split-collapse-btn { opacity: 0.6; }
  /* タッチ時はハンドルの当たり判定をさらに拡張 (合計 12px) */
  .gb-split-horizontal > .gb-split-handle::before {
    left: -4px; right: -4px;
  }
  .gb-split-vertical > .gb-split-handle::before {
    top: -4px; bottom: -4px;
  }
}

/* Part 2-3: 分割ハンドル折りたたみボタン (border 上の hover ボタン、双方向 2 個) */
.split-collapse-btn {
  position: absolute;
  width: 18px; height: 18px; display: flex; align-items: center; justify-content: center;
  font-size: 9px; color: var(--fg); background: var(--bg3); border: 1px solid var(--border); border-radius: 50%;
  cursor: pointer; opacity: 0; transition: opacity 0.15s; z-index: 5;
  user-select: none; pointer-events: auto;
}
.gb-split-handle:hover .split-collapse-btn,
.split-collapse-btn:hover { opacity: 1; }
.gb-split-handle.active .split-collapse-btn { opacity: 0; pointer-events: none; }
/* 横分割 (handle が縦線): ボタンを境界線に沿って上下に並べる */
.gb-split-horizontal > .gb-split-handle .split-collapse-btn-prev {
  top: var(--gb-split-anchor-y, 50%);
  left: 50%;
  transform: translate(-50%, calc(-100% - 8px));
}
.gb-split-horizontal > .gb-split-handle .split-collapse-btn-next {
  top: var(--gb-split-anchor-y, 50%);
  left: 50%;
  transform: translate(-50%, 8px);
}
/* 縦分割 (handle が横線): ボタンを境界線に沿って左右に並べる */
.gb-split-vertical > .gb-split-handle .split-collapse-btn-prev {
  top: 50%;
  left: var(--gb-split-anchor-x, 50%);
  transform: translate(calc(-100% - 8px), -50%);
}
.gb-split-vertical > .gb-split-handle .split-collapse-btn-next {
  top: 50%;
  left: var(--gb-split-anchor-x, 50%);
  transform: translate(8px, -50%);
}
.split-collapse-btn:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); border-color: var(--accent); }

/* タブの D&D 並び替えインジケータ (DOM 挿入は bar のレイアウトを変動させるため、
   target タブ自身の box-shadow inset で描く) */
/* ドロップインジケータ: アクティブタブの背景に隠れないよう疑似要素で
   絶対配置 + z-index で常に前面に描画。太さ 3px + 上下 2px はみ出しで視認性を確保。 */
.gb-tab.gb-tab-drop-before,
.gb-tab.gb-tab-drop-after {
  position: relative;
}
.gb-tab.gb-tab-drop-before::before,
.gb-tab.gb-tab-drop-after::after {
  content: '';
  position: absolute;
  top: -2px;
  bottom: -2px;
  width: 3px;
  background: var(--accent, #4a90d9);
  z-index: 10;
  pointer-events: none;
  border-radius: 1px;
}
.gb-tab.gb-tab-drop-before::before { left: -1px; }
.gb-tab.gb-tab-drop-after::after { right: -1px; }


/* === 列（カラム）: 水平スプリットの子 or 単独ルート === */
.gb-column {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
/* 列ヘッダバーは廃止。カラム D&D は Shift+ドラッグで発動。
   パネルセット時のタブバーは .gb-panelset-tabbar で直接表示。 */
.gb-column-body {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  overflow: hidden;
}
.gb-column-body > * { flex: 1 1 auto; min-width: 0; min-height: 0; }
.gb-panelset-content {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  overflow: hidden;
}
.gb-panelset-content > * { flex: 1 1 auto; min-width: 0; min-height: 0; }

/* === パネルセットのアイコンタブバー（列ヘッダ内に入る） === */
.gb-panelset-tabbar {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 2px;
  padding: 2px 4px;
  width: 100%;
  flex: 0 0 auto;
  background: var(--ui-panelset-tabbar-bg, var(--bg2, #222));
  overflow-x: auto;
}
.gb-panelset-tabbar-drop {
  outline: 2px dashed var(--accent);
  outline-offset: -2px;
}
.gb-panelset-icon[draggable="true"] {
  cursor: grab;
}
.gb-panelset-icon[draggable="true"]:active {
  cursor: grabbing;
}
.gb-panelset-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 24px;
  padding: 0 4px;
  border: 1px solid transparent;
  border-radius: 3px;
  background: transparent;
  color: var(--fg2, #bbb);
  cursor: pointer;
  flex: 0 0 auto;
}
.gb-panelset-icon:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
.gb-panelset-icon.active {
  background: var(--ui-selection-bg);
  color: var(--ui-selection-fg);
  border-color: var(--accent, #4a90d9);
}
/* ドラッグ中の並び替えインジケータ（タブの前後に挿入線） */
.gb-panelset-icon { position: relative; }
.gb-panelset-icon.gb-panelset-drop-before::before,
.gb-panelset-icon.gb-panelset-drop-after::after {
  content: ""; position: absolute; top: 2px; bottom: 2px;
  width: 2px; background: var(--accent, #4a90d9); z-index: 5;
}
.gb-panelset-icon.gb-panelset-drop-before::before { left: -2px; }
.gb-panelset-icon.gb-panelset-drop-after::after { right: -2px; }
.gb-panelset-icon-box {
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: 1px;
}
.gb-panelset-mini-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
}
.gb-panelset-mini-icon svg { width: 12px; height: 12px; display: block; }
.gb-panelset-mini-extra {
  font-size: 9px;
  line-height: 1;
  color: var(--fg2, #888);
  margin-left: 2px;
}
.gb-panelset-mini-empty {
  color: var(--fg2, #888);
  font-size: 12px;
  line-height: 1;
}

/* =========================================================================
   CSP パレット方式リデザイン (Phase 1)
   ドックバー / ドックポップアップ / サブウィンドウモード
   ========================================================================= */

/* 固定レールの幅。ドックバー本体・ドラッグハンドル・group 間スペーサーが
   同じ値を参照する（以前は 38px が3箇所にベタ書きされていた）。 */
:root {
  --gb-rail-width: 38px;
}

/* ドックバー本体: 各 panelset ノードの端に常設される縦バー（単独ペインのカラムでは非表示） */
.gb-dock-bar {
  width: var(--gb-rail-width, 38px);
  min-width: var(--gb-rail-width, 38px);
  max-width: var(--gb-rail-width, 38px);
  flex: 0 0 var(--gb-rail-width, 38px);
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--ui-dockbar-bg, var(--ui-pane-tabbar-bg, var(--bg2)));
  border: none;
  padding: 0;
  gap: 0;
  overflow-y: auto;
  overflow-x: hidden;
  user-select: none;
  /* スクロールバーを実体で出すと内容幅が 10px 削られ、アイコン（34px）が
     横にはみ出して overflow-x:hidden で切られる。アイコン数がウィンドウ高を
     超えた時だけ「右端が見切れる」のはこれが原因。.gb-pane-tabs-scroll と
     同じ方式でスクロールバーを隠し、ホイールでのスクロールだけ残す。 */
  scrollbar-width: none;
}
.gb-dock-bar::-webkit-scrollbar { display: none; }
.gb-dock-fixed-left .gb-dock-bar {
  border-right: 1px solid var(--border);
  border-left: 0;
}
.gb-dock-fixed-right .gb-dock-bar {
  border-left: 1px solid var(--border);
  border-right: 0;
}
/* 固定レールのカラムは、分割比率やウィンドウ縮小でレール幅を下回らせない。
   .gb-split-child は overflow:hidden / min-width:0 なので、下限が無いと
   レールが親からはみ出して右端が切れる。境界線 1px 分を足して確保する。 */
.gb-dock-fixed-left,
.gb-dock-fixed-right {
  min-width: calc(var(--gb-rail-width, 38px) + 1px);
}
.gb-split-child:has(> .gb-dock-fixed-left),
.gb-split-child:has(> .gb-dock-fixed-right) {
  min-width: calc(var(--gb-rail-width, 38px) + 1px);
}
.gb-dock-bar-fixed {
  background: var(--ui-dockbar-bg, var(--bg2));
  padding: 3px 0;
  gap: 1px;
}
.gb-dock-rail-toggle {
  margin-top: 0;
  background: transparent;
}
.gb-dock-rail-separator {
  width: 24px;
  height: 1px;
  margin: 4px 0;
  flex: 0 0 1px;
  background: var(--border);
}
.gb-dock-rail-app {
  background: transparent;
}
.gb-rail-app-menu-icon {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.gb-rail-app-menu-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.gb-dock-fixed-left .gb-dock-body,
.gb-dock-fixed-right .gb-dock-body {
  min-width: 0;
}

/* ドラッグハンドル: ドックを別位置へ移動するためのつまみ */
.gb-dock-bar-handle {
  width: var(--gb-rail-width, 38px);
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.3;
  cursor: grab;
  color: var(--fg2);
  flex: 0 0 16px;
}
.gb-dock-bar-handle:hover { opacity: 0.8; }
.gb-dock-bar-handle:active { cursor: grabbing; }
.gb-dock-bar-handle svg { width: 16px; height: 16px; }

/* ドックタブスペーサー: group 間の視覚的な隙間（クリック操作はなし、純粋な余白）*/
.gb-dock-tab-spacer {
  width: var(--gb-rail-width, 38px);
  height: 12px;
  min-height: 12px;
  flex: 0 0 12px;
  pointer-events: none;
}
.gb-dock-tab-spacer:first-of-type { display: none; }

/* ドックバー内のパネルアイコンボタン */
.gb-dock-icon {
  width: 34px;
  height: 34px;
  min-height: 34px;
  margin: 2px 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ui-dock-button-bg, var(--ui-bg-control));
  border: var(--ui-dock-button-border-width, 0px) solid var(--ui-dock-button-border, transparent);
  border-radius: var(--ui-radius-sm, 4px);
  color: var(--ui-dock-button-fg, var(--ui-fg-default));
  font-family: var(--ui-dock-button-font, inherit);
  font-size: var(--ui-dock-button-font-size, var(--ui-font-13));
  line-height: var(--ui-dock-button-line-height, 100%);
  font-weight: var(--ui-dock-button-font-weight, var(--ui-weight-medium));
  font-style: var(--ui-dock-button-font-style, normal);
  box-shadow: inset 0 calc(-1 * var(--ui-dock-button-underline, 0px)) 0 var(--ui-dock-button-accent-color, var(--ui-accent));
  cursor: pointer;
  flex: 0 0 34px;
  padding: 0;
  position: relative;
}
.gb-dock-icon svg { width: 20px; height: 20px; }
.gb-dock-icon:hover {
  background: var(--ui-dock-button-hover-bg, var(--ui-bg-control-hover));
  color: var(--ui-dock-button-hover-fg, var(--ui-fg-default));
  border: var(--ui-dock-button-hover-border-width, 0px) solid var(--ui-dock-button-hover-border, transparent);
  box-shadow: inset 0 calc(-1 * var(--ui-dock-button-hover-underline, 0px)) 0 var(--ui-dock-button-hover-accent-color, var(--ui-accent));
  font-family: var(--ui-dock-button-hover-font, inherit);
  font-size: var(--ui-dock-button-hover-font-size, var(--ui-font-13));
  line-height: var(--ui-dock-button-hover-line-height, 100%);
  font-weight: var(--ui-dock-button-hover-font-weight, var(--ui-weight-medium));
  font-style: var(--ui-dock-button-hover-font-style, normal);
}
.gb-dock-bar-fixed .gb-dock-icon.active {
  background: var(--ui-dock-button-active-bg, color-mix(in srgb, var(--ui-accent) 94%, #000)) !important;
  color: var(--ui-dock-button-active-fg, var(--ui-accent-fg, var(--ui-fg-strong))) !important;
  border: var(--ui-dock-button-active-border-width, 0px) solid var(--ui-dock-button-active-border, transparent);
  box-shadow: inset 0 calc(-1 * var(--ui-dock-button-active-underline, 0px)) 0 var(--ui-dock-button-active-accent-color, var(--ui-accent));
  font-family: var(--ui-dock-button-active-font, inherit);
  font-size: var(--ui-dock-button-active-font-size, var(--ui-font-13));
  line-height: var(--ui-dock-button-active-line-height, 100%);
  font-weight: var(--ui-dock-button-active-font-weight, var(--ui-weight-medium));
  font-style: var(--ui-dock-button-active-font-style, normal);
}
.gb-dock-bar-fixed .gb-dock-icon.active svg { color: currentColor !important; stroke: currentColor !important; }
.gb-dock-icon[data-theme-rail-palette-index="0"] { --gb-rail-icon-color: var(--theme-palette-0); }
.gb-dock-icon[data-theme-rail-palette-index="1"] { --gb-rail-icon-color: var(--theme-palette-1); }
.gb-dock-icon[data-theme-rail-palette-index="2"] { --gb-rail-icon-color: var(--theme-palette-2); }
.gb-dock-icon[data-theme-rail-palette-index="3"] { --gb-rail-icon-color: var(--theme-palette-3); }
.gb-dock-icon[data-theme-rail-palette-index="4"] { --gb-rail-icon-color: var(--theme-palette-4); }
.gb-dock-icon[data-theme-rail-palette-index="5"] { --gb-rail-icon-color: var(--theme-palette-5); }
.gb-dock-icon[data-theme-rail-palette-index="6"] { --gb-rail-icon-color: var(--theme-palette-6); }
.gb-dock-icon[data-theme-rail-palette-index="7"] { --gb-rail-icon-color: var(--theme-palette-7); }
.gb-dock-icon[data-theme-rail-palette-index="8"] { --gb-rail-icon-color: var(--theme-palette-8); }
.gb-dock-icon[data-theme-rail-palette-index="9"] { --gb-rail-icon-color: var(--theme-palette-9); }
html[data-meldex-theme-id="builtin-pastel"] .gb-dock-bar-fixed .gb-dock-icon[data-theme-rail-icon="palette"]:not(.active),
html[data-meldex-theme-id="builtin-earth"] .gb-dock-bar-fixed .gb-dock-icon[data-theme-rail-icon="palette"]:not(.active) {
  color: var(--gb-rail-icon-color, var(--ui-fg-default));
}
/* テーマ設定の「左アクセントバー」を通常・ホバー・選択の各状態へ反映する。 */
.gb-dock-icon::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: var(--ui-dock-button-left-accent, 0px);
  background: var(--ui-dock-button-accent-color, var(--accent));
  border-radius: 1px;
  pointer-events: none;
}
.gb-dock-icon:hover::before {
  width: var(--ui-dock-button-hover-left-accent, 0px);
  background: var(--ui-dock-button-hover-accent-color, var(--accent));
}
.gb-dock-icon.active::before {
  width: var(--ui-dock-button-active-left-accent, 2px);
  background: var(--ui-dock-button-active-accent-color, var(--accent));
}

/* ドロップインジケータ (ドックタブ挿入位置) */
.gb-dock-tab-insert-indicator {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
  pointer-events: none;
  z-index: 2;
}

/* =========================================================================
   ドックポップアップ: ドックバーアイコンのクリックで一時表示
   ========================================================================= */
.gb-dock-popup {
  position: fixed;
  z-index: 10050;
  background: var(--bg);
  border: 1px solid var(--ui-popup-border, var(--ui-border-strong, var(--border, rgba(128,128,128,0.3))));
  box-shadow: 0 8px 24px rgba(0,0,0,0.25);
  display: flex;
  flex-direction: column;
  min-width: 200px;
  min-height: 150px;
  overflow: hidden;
}
.gb-dock-popup-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px;
  background: var(--bg2);
  border-bottom: 1px solid var(--border, rgba(128,128,128,0.2));
  font-size: 12px;
  flex: 0 0 auto;
  cursor: default;
}
.gb-dock-popup-title {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-dock-popup-close {
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--fg2);
  border-radius: 3px;
}
.gb-dock-popup-close:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
.gb-dock-popup-body {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  position: relative;
}

.gb-dock-popup ~ .gb-context-menu,
.gb-dock-popup ~ .ab-dropdown,
.gb-dock-popup ~ .bd-style-picker-menu,
.gb-dock-popup ~ #chat-title-dropdown {
  z-index: 10080 !important;
}

/* サブパネル上でも同じ重なり順を保つ。ドック用ルールは静的契約検査
   （test_meldex_dock_regressions）がセレクタの並びごと固定しているため、
   そちらへ追記せず独立したルールとして持つ。 */
.gb-subpanel ~ .gb-context-menu,
.gb-subpanel ~ .ab-dropdown,
.gb-subpanel ~ .bd-style-picker-menu,
.gb-subpanel ~ #chat-title-dropdown {
  z-index: 10080 !important;
}

/* 8方向リサイズハンドル */
.gb-dock-popup-resize-handle {
  position: absolute;
  z-index: 1;
}
.gb-dock-popup-resize-handle[data-dir="n"]  { top: 0; left: 4px; right: 4px; height: 4px; cursor: ns-resize; }
.gb-dock-popup-resize-handle[data-dir="s"]  { bottom: 0; left: 4px; right: 4px; height: 4px; cursor: ns-resize; }
.gb-dock-popup-resize-handle[data-dir="e"]  { top: 4px; bottom: 4px; right: 0; width: 4px; cursor: ew-resize; }
.gb-dock-popup-resize-handle[data-dir="w"]  { top: 4px; bottom: 4px; left: 0; width: 4px; cursor: ew-resize; }
.gb-dock-popup-resize-handle[data-dir="ne"] { top: 0; right: 0; width: 8px; height: 8px; cursor: nesw-resize; }
.gb-dock-popup-resize-handle[data-dir="nw"] { top: 0; left: 0; width: 8px; height: 8px; cursor: nwse-resize; }
.gb-dock-popup-resize-handle[data-dir="se"] { bottom: 0; right: 0; width: 8px; height: 8px; cursor: nwse-resize; }
.gb-dock-popup-resize-handle[data-dir="sw"] { bottom: 0; left: 0; width: 8px; height: 8px; cursor: nesw-resize; }

/* =========================================================================
   サブウィンドウモード: ?subwindow=1 起動時の chrome 非表示
   ========================================================================= */
.gb-subwindow-mode #activity-bar,
.gb-subwindow-mode [id^="sb-"],
.gb-subwindow-mode #gb-sidebar {
  display: none !important;
}
.gb-subwindow-mode .gb-subwindow-hidden { display: none !important; }


/* 固定レール共通シェル: 上端固定 / 中央のみスクロール / 下端固定 */
.gb-dock-bar-fixed {
  overflow: hidden;
}

.gb-rail-shell-top,
.gb-rail-shell-scroll,
.gb-rail-shell-bottom {
  display: flex;
  flex: 0 0 auto;
  width: 100%;
  min-height: 0;
  align-items: center;
  flex-direction: column;
}

.gb-rail-shell-scroll {
  position: relative;
  flex: 1 1 auto;
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: none;
  overscroll-behavior: contain;
}

.gb-rail-shell-scroll::-webkit-scrollbar { display: none; }

.gb-rail-shell-scroll::before,
.gb-rail-shell-scroll::after {
  content: '';
  position: sticky;
  z-index: 2;
  display: block;
  flex: 0 0 10px;
  width: 100%;
  height: 10px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 120ms ease;
}

.gb-rail-shell-scroll::before {
  top: 0;
  margin-bottom: -10px;
  background: linear-gradient(to bottom, var(--ui-pane-tabbar-bg, var(--bg3)), transparent);
}

.gb-rail-shell-scroll::after {
  bottom: 0;
  margin-top: -10px;
  background: linear-gradient(to top, var(--ui-pane-tabbar-bg, var(--bg3)), transparent);
}

.gb-rail-shell-scroll.can-scroll-up::before,
.gb-rail-shell-scroll.can-scroll-down::after { opacity: 1; }

.gb-rail-separator-after { margin-bottom: 7px; }
.gb-rail-separator-after::after {
  content: '';
  position: absolute;
  left: 7px;
  right: 7px;
  bottom: -4px;
  height: 1px;
  background: var(--ui-border, var(--border));
  pointer-events: none;
}

.gb-rail-shell-bottom {
  padding-top: 5px;
  border-top: 1px solid var(--ui-border, var(--border));
}

.gb-rail-shell-bottom:empty { display: none; }

@media (pointer: coarse) {
  .gb-dock-bar-fixed .gb-dock-icon {
    min-width: 44px;
    min-height: 44px;
  }
}

/* タイムラインビュー専用の上書き */

.tl-grid {
  column-gap: 0;
  row-gap: 0;
  padding: 2px 2px 4px;
  align-items: stretch;
  border-left: 1px solid var(--border);
  border-top: 1px solid var(--border);
}

.tl-header-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  border: 0;
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.tl-cell {
  border: 0;
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.tl-header-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tl-header-more-btn {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 3px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  opacity: 0;
}

.tl-header-cell:hover .tl-header-more-btn,
.tl-header-more-btn:focus-visible {
  opacity: 0.85;
}

@media (pointer: coarse) {
  .tl-header-more-btn {
    opacity: 0.85;
  }
}

.tl-header-more-btn:hover {
  background: var(--ui-hover-bg);
  color: var(--ui-hover-fg);
  border-color: var(--border);
}

.tl-header-cell.tl-col-header {
  padding-right: 8px;
}

.tl-col-resize-handle {
  z-index: 3;
}

.tl-header-cell.tl-axis-colored {
  background: color-mix(in srgb, var(--tl-axis-bg) 82%, #000);
  color: var(--tl-axis-fg);
  border-color: color-mix(in srgb, var(--tl-axis-bg) 65%, #000);
}

.tl-cell.tl-axis-colored {
  background: color-mix(in srgb, var(--tl-axis-bg) 14%, transparent);
  border-color: color-mix(in srgb, var(--tl-axis-bg) 55%, var(--border));
}

.tl-cell.tl-axis-colored:hover {
  background: color-mix(in srgb, var(--tl-axis-bg) 22%, var(--ui-hover-bg));
}

.tl-card.tl-axis-colored,
.tl-bar.tl-axis-colored {
  background: var(--tl-axis-bg);
  color: var(--tl-axis-fg);
}

.tl-card,
.tl-bar {
  border: 0 !important;
  box-shadow: none !important;
  outline: 0;
}

.tl-card {
  border-radius: 0;
  margin: 0;
  position: relative;
  z-index: 1;
}

.tl-bar {
  align-self: stretch;
  border-radius: 0;
  margin: 0;
  min-height: 0;
  position: relative;
  z-index: 4;
}

.tl-card.tl-axis-colored,
.tl-bar.tl-axis-colored,
.tl-card:hover {
  border-color: transparent !important;
  box-shadow: none !important;
}

.tl-card.tl-axis-colored .tl-card-prop-name,
.tl-bar.tl-axis-colored .tl-card-prop-name {
  color: color-mix(in srgb, var(--tl-axis-fg) 76%, transparent);
}

.tl-card-prop-value--editable {
  display: inline-flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.tl-card-prop-value--editable .cell-value {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  padding: 0 18px 0 0;
  line-height: 1.25;
  color: inherit;
}

.tl-card-prop-value--editable .value-text,
.tl-card-prop-value--editable .cell-number,
.tl-card-prop-value--editable .cell-date,
.tl-card-prop-value--editable .cell-select-val {
  color: inherit;
  min-width: 0;
  overflow-wrap: anywhere;
}

.tl-card-prop-value--editable .cell-value-more {
  right: 0;
  background: color-mix(in srgb, var(--bg3) 88%, transparent);
}

.tl-bar-label {
  pointer-events: auto;
}

.tl-color-modal {
  box-sizing: border-box;
  width: min(420px, calc(100vw - 24px));
  min-width: 0;
  max-width: 420px;
}

.timeline-view[data-db-time-view="gantt"] .tl-grid,
#timeline-view[data-db-time-view="gantt"] .tl-grid {
  --gantt-today-bg: color-mix(in srgb, var(--accent) 9%, transparent);
}
.tl-view-kind { display:inline-flex; align-items:center; gap:5px; font-weight:600; color:var(--fg); }
.tl-gantt-row-meta { display:block; margin-top:2px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:10px; font-weight:400; color:var(--fg2); }
.tl-today-column { background:var(--gantt-today-bg, color-mix(in srgb, var(--accent) 9%, transparent)) !important; }
.tl-gantt-bar { min-height:24px; }
.tl-gantt-progress { position:absolute; inset:0 auto 0 0; z-index:0; border-radius:inherit; background:color-mix(in srgb, var(--accent) 42%, transparent); pointer-events:none; }
.tl-gantt-bar > :not(.tl-gantt-progress) { position:relative; z-index:1; }
.tl-gantt-milestone { clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%); min-width:24px; min-height:24px; }
.tl-gantt-unscheduled { flex:0 0 auto; border-top:1px solid var(--border); padding:8px 12px 12px; }
.tl-gantt-unscheduled-title { margin-bottom:6px; font-size:12px; font-weight:600; color:var(--fg2); }
.tl-gantt-unscheduled-list { display:flex; flex-wrap:wrap; gap:6px; }
.tl-gantt-unscheduled-item { display:grid; gap:2px; min-width:140px; max-width:260px; padding:6px 8px; text-align:left; color:var(--fg); background:var(--bg2); border:1px solid var(--border); border-radius:var(--ui-radius-sm, 4px); }
.tl-gantt-unscheduled-item small { color:var(--fg2); }

.tl-color-header {
  gap: 12px;
}

.tl-color-header h3 {
  margin: 0;
}

.tl-color-close {
  margin-left: auto;
}

.tl-color-body {
  display: grid;
  gap: 12px;
}

.tl-color-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
}

.tl-color-row .field {
  min-width: 0;
}

.tl-color-target {
  color: var(--fg);
  font-size: 13px;
  padding: 4px 0;
}

.tl-settings .tl-calendar-date-field {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.tl-card-prop-move {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: var(--bg3);
  color: var(--fg);
  cursor: pointer;
}

.tl-card-prop-move:disabled {
  opacity: 0.38;
  cursor: default;
}

.tl-calendar-date-controls {
  display: grid;
  grid-template-columns: 64px minmax(96px, 1fr) 54px;
  gap: 4px;
  align-items: center;
}

.tl-calendar-date-controls .gb-input,
.tl-calendar-date-controls .gb-select {
  min-width: 0;
}

.tl-calendar-date-time {
  grid-column: span 3;
}

.tl-calendar-modal {
  box-sizing: border-box;
  width: min(700px, calc(100vw - 24px)) !important;
  min-width: 0 !important;
  max-width: 700px !important;
  max-height: calc(100vh - 32px);
  padding: 16px;
  overflow: auto;
}

.tl-calendar-preset-row {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto;
  gap: 10px;
  align-items: end;
  margin-bottom: 10px;
}

.tl-calendar-preset-row label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  font-size: 12px;
  color: var(--fg2);
}

.tl-calendar-preset-select-wrap {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
}

.tl-calendar-preset-select-wrap::after {
  content: "▼";
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  color: var(--fg2);
  font-size: 11px;
  line-height: 1;
}

.tl-calendar-preset-select-wrap select {
  display: block;
  width: 100% !important;
  padding-right: 30px;
  appearance: none;
}

.tl-calendar-preset-actions {
  display: flex;
  gap: 6px;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.tl-calendar-preset-actions button {
  white-space: nowrap;
}

.tl-calendar-top-grid {
  display: grid;
  grid-template-columns: minmax(220px, 0.75fr) minmax(320px, 1fr);
  gap: 10px;
  align-items: start;
}

.tl-calendar-fields {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
}

.tl-calendar-fields label,
.tl-calendar-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--fg2);
}

.tl-calendar-fields input,
.tl-calendar-fields select,
.tl-calendar-preset-row select,
.tl-calendar-leap-fields input,
.tl-calendar-leap-fields select,
.tl-calendar-list input {
  width: 100%;
  box-sizing: border-box;
  min-height: var(--ui-h-sm, 28px);
  background: var(--ui-bg-app, var(--bg));
  color: var(--ui-fg-default, var(--fg));
  border: 1px solid var(--ui-border, var(--border));
  border-radius: var(--ui-radius-xs, 3px);
  padding: 0 var(--ui-space-4, 8px);
  font: inherit;
}

input.tl-number-input {
  -moz-appearance: number-input;
}

input.tl-number-input::-webkit-outer-spin-button,
input.tl-number-input::-webkit-inner-spin-button {
  -webkit-appearance: auto;
  opacity: 0;
  transition: opacity 0.12s;
}

input.tl-number-input:hover::-webkit-outer-spin-button,
input.tl-number-input:hover::-webkit-inner-spin-button,
input.tl-number-input:focus::-webkit-outer-spin-button,
input.tl-number-input:focus::-webkit-inner-spin-button {
  opacity: 1;
}

.tl-calendar-sections-grid {
  display: grid;
  grid-template-columns: minmax(300px, 1fr) minmax(240px, 0.8fr);
  gap: 10px;
  align-items: start;
  margin-top: 10px;
}

.tl-calendar-section {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  box-sizing: border-box;
}

.tl-calendar-side-stack {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

.tl-calendar-section--units {
  margin-top: 0;
  max-width: none;
}

.tl-calendar-section-head {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.tl-calendar-section-head strong {
  color: var(--fg);
  font-size: 13px;
}

.tl-calendar-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
}

.tl-calendar-list-row {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) auto;
  gap: 8px;
  align-items: end;
  justify-content: start;
}

.tl-calendar-list-row--length {
  grid-template-columns: minmax(130px, 1fr) 72px auto;
}

.tl-calendar-list-row label {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--fg2);
  white-space: nowrap;
}

.tl-calendar-list-row label input {
  flex: 1 1 auto;
  min-width: 0;
}

.tl-calendar-list-row--length label input {
  max-width: none;
}

.tl-calendar-check {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  color: var(--fg);
}

.tl-calendar-check input {
  width: auto;
}

.tl-calendar-leap-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(120px, 1fr));
  gap: 8px;
}

.tl-calendar-leap-fields label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  color: var(--fg2);
}

.tl-calendar-row-remove {
  white-space: nowrap;
}

.tl-calendar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.tl-calendar-actions-spacer {
  display: none;
}

@media (max-width: 640px) {
  .tl-calendar-preset-row,
  .tl-calendar-top-grid,
  .tl-calendar-fields,
  .tl-calendar-sections-grid {
    grid-template-columns: 1fr;
  }

  .tl-calendar-modal {
    width: min(520px, calc(100vw - 16px)) !important;
    padding: 12px;
  }

  .tl-calendar-list {
    grid-template-columns: 1fr;
  }

  .tl-calendar-actions {
    flex-wrap: wrap;
  }

  .tl-calendar-list-row,
  .tl-calendar-list-row--length {
    grid-template-columns: 1fr;
  }

  .tl-calendar-leap-fields {
    grid-template-columns: 1fr;
  }

  .tl-calendar-date-controls {
    grid-template-columns: 1fr;
  }

  .tl-calendar-date-time {
    grid-column: auto;
  }

  .tl-header-more-btn {
    flex-basis: 44px;
    width: 44px;
    height: 44px;
  }

  .tl-color-modal {
    width: min(520px, calc(100vw - 16px));
    max-width: calc(100vw - 16px);
  }

  .tl-color-row {
    grid-template-columns: 1fr;
  }

  .tl-color-row .gb-fmt-swatch-bg,
  .tl-color-row .gb-fmt-swatch-fg,
