.el-cell-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 14px;
  height: 14px;
  cursor: nwse-resize;
  background:
    linear-gradient(135deg, transparent 50%, var(--el-fg2, var(--fg2)) 50%, var(--el-fg2, var(--fg2)) 60%, transparent 60%,
      transparent 70%, var(--el-fg2, var(--fg2)) 70%, var(--el-fg2, var(--fg2)) 80%, transparent 80%);
  opacity: 0.7;
  z-index: 2;
}

@media (pointer: coarse), (max-width: 900px) {
  /* タッチ時は視覚サイズだけでなく実際の操作領域を44px確保する。
     小さい罫線セルでも操作が切れないよう、編集時のチロームだけはセル外へ出せる。 */
  .el-viewport.el-editing { overflow: visible; }
  .el-cell.el-editable { overflow: visible; }
  .el-cell.el-editable > .el-cell-content {
    overflow: hidden;
    border-radius: inherit;
  }
  .el-cell-remove,
  .el-cell-settings {
    top: calc(100% + (4px * var(--el-inverse-scale, 1)));
    right: auto;
    width: calc(44px * var(--el-inverse-scale, 1));
    height: calc(44px * var(--el-inverse-scale, 1));
    font-size: calc(14px * var(--el-inverse-scale, 1));
  }
  /* モバイル右ドロワー中央左の閉じるハンドルと重ならないよう、1枠分右へ寄せる。 */
  .el-cell-settings { left: calc(48px * var(--el-inverse-scale, 1)); }
  .el-cell-remove { left: calc(96px * var(--el-inverse-scale, 1)); }
  .el-cell-remove svg,
  .el-cell-settings svg {
    width: calc(14px * var(--el-inverse-scale, 1));
    height: calc(14px * var(--el-inverse-scale, 1));
  }
  .el-cell-resize {
    top: calc(100% + (4px * var(--el-inverse-scale, 1)));
    right: auto;
    bottom: auto;
    left: calc(144px * var(--el-inverse-scale, 1));
    width: calc(44px * var(--el-inverse-scale, 1));
    height: calc(44px * var(--el-inverse-scale, 1));
  }
}

