/* Dropbox conflict resolver */

.cloud-conflict-resolver-overlay {
  position: fixed;
  inset: 0;
  z-index: 10090;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(0, 0, 0, 0.62);
}

.cloud-conflict-resolver {
  box-sizing: border-box;
  width: min(1180px, 96vw);
  height: min(760px, 92vh);
  max-height: calc(100dvh - 36px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  background: var(--bg, #1e1e1e);
  color: var(--fg, #d4d4d4);
  border: 1px solid var(--border, #333);
  border-radius: 8px;
  box-shadow: 0 18px 56px rgba(0, 0, 0, 0.48);
  overflow: hidden;
}

.cloud-conflict-resolver:focus-visible {
  outline: 2px solid var(--focus, var(--accent, #569cd6));
  outline-offset: -3px;
}

.cloud-conflict-header,
.cloud-conflict-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border, #333);
}

.cloud-conflict-footer {
  justify-content: flex-end;
  flex-wrap: wrap;
  border-top: 1px solid var(--border, #333);
  border-bottom: 0;
}

.cloud-conflict-title {
  font-size: 16px;
  font-weight: 700;
}

.cloud-conflict-status {
  margin-left: auto;
  color: var(--fg2, #969696);
  font-size: 12px;
}

.cloud-conflict-body {
  display: grid;
  grid-template-columns: minmax(220px, 280px) minmax(0, 1fr);
  min-height: 0;
}

.cloud-conflict-list {
  border-right: 1px solid var(--border, #333);
  overflow: auto;
  background: var(--bg2, #252525);
}

.cloud-conflict-list-item {
  box-sizing: border-box;
  width: 100%;
  min-height: 44px;
  display: block;
  padding: 10px 12px;
  border: 0;
  border-bottom: 1px solid var(--border, #333);
  background: transparent;
  color: var(--fg, #d4d4d4);
  text-align: left;
  cursor: pointer;
}

.cloud-conflict-list-item:hover,
.cloud-conflict-list-item.active {
  background: var(--ui-selection-bg, #264f78);
  color: var(--ui-selection-fg, #fff);
}

.cloud-conflict-list-name {
  display: block;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cloud-conflict-list-path {
  display: block;
  margin-top: 4px;
  color: var(--fg2, #969696);
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cloud-conflict-detail {
  display: grid;
  grid-template-rows: auto 1fr;
  min-width: 0;
  min-height: 0;
}

.cloud-conflict-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 10px;
  border-bottom: 1px solid var(--border, #333);
}

.cloud-conflict-meta-card {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid var(--border, #333);
  border-radius: 6px;
  background: var(--bg2, #252525);
}

.cloud-conflict-meta-label {
  color: var(--fg2, #969696);
  font-size: 11px;
}

.cloud-conflict-meta-path {
  margin-top: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.cloud-conflict-compare {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 0;
}

.cloud-conflict-pane {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border, #333);
}

.cloud-conflict-pane:last-child {
  border-right: 0;
}

.cloud-conflict-pane-title {
  flex: 0 0 auto;
  padding: 8px 10px;
  background: var(--bg2, #252525);
  border-bottom: 1px solid var(--border, #333);
  font-size: 12px;
  font-weight: 700;
}

.cloud-conflict-code {
  flex: 1 1 auto;
  overflow: auto;
  margin: 0;
  padding: 8px 0;
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-size: 12px;
  line-height: 1.55;
  background: var(--bg, #1e1e1e);
}

.cloud-conflict-line {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 8px;
  padding: 0 10px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.cloud-conflict-line.is-different {
  background: color-mix(in srgb, var(--ui-selection-bg, #264f78) 42%, transparent);
  box-shadow: inset 3px 0 0 var(--accent, #569cd6);
}

.cloud-conflict-line-no {
  color: var(--fg2, #969696);
  text-align: right;
  user-select: none;
}

.cloud-conflict-inline-diff {
  display: inline;
  padding: 0 2px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--red, #f48771) 36%, transparent);
  color: var(--ui-fg-strong, #fff);
}

.cloud-conflict-empty {
  padding: 24px;
  color: var(--fg2, #969696);
}

.cloud-conflict-btn {
  box-sizing: border-box;
  min-height: 34px;
  padding: 6px 12px;
  border: 1px solid var(--border, #333);
  border-radius: 5px;
  background: var(--bg3, #2d2d2d);
  color: var(--fg, #d4d4d4);
  cursor: pointer;
}

.cloud-conflict-btn:hover {
  background: var(--ui-hover-bg, #333);
  color: var(--ui-hover-fg, #fff);
}

.cloud-conflict-btn:disabled {
  cursor: not-allowed;
  color: var(--fg2, #969696);
  background: var(--bg2, #252525);
  border-color: transparent;
}

.cloud-conflict-btn.primary {
  border-color: var(--accent, #569cd6);
  background: var(--accent, #569cd6);
  color: var(--ui-fg-strong, #fff);
}

@media (max-width: 760px) {
  .cloud-conflict-resolver-overlay {
    align-items: stretch;
    box-sizing: border-box;
    padding:
      calc(8px + env(safe-area-inset-top, 0px))
      max(8px, env(safe-area-inset-right, 0px))
      max(8px, env(safe-area-inset-bottom, 0px))
      max(8px, env(safe-area-inset-left, 0px));
  }

  .cloud-conflict-resolver {
    width: 100%;
    height: auto;
    max-height: calc(100dvh - max(16px, env(safe-area-inset-top, 0px)) - max(8px, env(safe-area-inset-bottom, 0px)));
    min-height: 0;
  }

  .cloud-conflict-header {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .cloud-conflict-status {
    flex: 1 1 100%;
    margin-left: 0;
  }

  .cloud-conflict-body,
  .cloud-conflict-meta,
  .cloud-conflict-compare {
    grid-template-columns: 1fr;
  }

  .cloud-conflict-body {
    grid-template-rows: minmax(120px, auto) minmax(0, 1fr);
  }

  .cloud-conflict-detail {
    min-height: 0;
  }

  .cloud-conflict-compare {
    display: flex;
    flex-direction: column;
    grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
  }

  .cloud-conflict-list {
    max-height: 180px;
    border-right: 0;
    border-bottom: 1px solid var(--border, #333);
  }

  .cloud-conflict-pane {
    flex: 1 1 0;
    min-height: 88px;
    border-right: 0;
    border-bottom: 1px solid var(--border, #333);
  }

  .cloud-conflict-pane:last-child {
    border-bottom: 0;
  }

  .cloud-conflict-footer {
    justify-content: stretch;
    padding-bottom: max(10px, env(safe-area-inset-bottom, 0px));
  }

  .cloud-conflict-footer .cloud-conflict-btn {
    flex: 1 1 140px;
    min-height: 44px;
    min-width: 0;
  }
}

/* gb-tools.css: split stylesheet loader */
/* 汎用ホバーアイテム（インラインonmouseenter/onmouseleave置き換え用） */
.gb-hover-item:hover { background: var(--bg4); }

/* ==============================
   ピボットテーブル
   ============================== */
#pivot-view { flex: 1; overflow: auto; padding: 0; background: var(--db-row-bg, var(--content-bg, var(--bg))); }
#pivot-table {
  border-collapse: collapse; width: max-content; table-layout: fixed;
}
#pivot-table thead {
  position: sticky;
  top: -1px;
  z-index: 20;
  background: var(--db-th-bg);
  box-shadow: 0 -8px 0 var(--db-th-bg);
}
#pivot-table {
  --db-grid-h: var(--db-show-grid); --db-grid-v: var(--db-show-grid);
  --db-grid-h-color: var(--db-grid-border); --db-grid-v-color: var(--db-grid-border);
}
#pivot-table th, #pivot-table td, .pivot-table th, .pivot-table td {
  box-sizing: border-box;
}
#pivot-table th {
  background: var(--db-th-bg); color: var(--db-th-fg);
  font-family: var(--db-th-font, var(--ui-font, inherit));
  font-weight: var(--db-th-bold); font-style: var(--db-th-italic); font-size: var(--db-th-font-size, 13px);
  text-align: left; padding: 3px 8px; user-select: none;
  border-top: var(--db-grid-h) solid var(--db-grid-h-color);
  border-bottom: var(--db-grid-h) solid var(--db-grid-h-color);
  border-left: var(--db-grid-v) solid var(--db-grid-v-color);
  border-right: var(--db-grid-v) solid var(--db-grid-v-color);
  position: relative; min-width: 100px;
  -webkit-text-stroke-color: var(--db-th-stroke-color, transparent);
  -webkit-text-stroke-width: var(--db-th-stroke-width, 0px);
  paint-order: stroke fill;
  box-shadow: inset var(--db-th-left-accent, 0px) 0 0 var(--db-th-accent-color, var(--db-th-fg));
  text-decoration-line: var(--db-th-underline, none);
  text-decoration-color: var(--db-th-accent-color, currentColor);
}
#pivot-table td {
  border-top: var(--db-grid-h) solid var(--db-grid-h-color);
  border-bottom: var(--db-grid-h) solid var(--db-grid-h-color);
  border-left: var(--db-grid-v) solid var(--db-grid-v-color);
  border-right: var(--db-grid-v) solid var(--db-grid-v-color);
  padding: 1px 8px;
  vertical-align: top; font-size: var(--db-cell-font-size, 13px); color: var(--db-cell-fg); background: var(--db-cell-bg);
  font-family: var(--db-cell-font, var(--ui-font, inherit));
  font-weight: var(--db-cell-bold); font-style: var(--db-cell-italic);
  -webkit-text-stroke-color: var(--db-cell-stroke-color, transparent);
  -webkit-text-stroke-width: var(--db-cell-stroke-width, 0px);
  paint-order: stroke fill;
  box-shadow: inset var(--db-cell-left-accent, 0px) 0 0 var(--db-cell-accent-color, var(--db-cell-fg));
  text-decoration-line: var(--db-cell-underline, none);
  text-decoration-color: var(--db-cell-accent-color, currentColor);
}
#pivot-table tr:hover td { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
/* 可変高の画像セルを持つ table-row に content-visibility:auto を指定すると、
   Chromium が行高を36pxと誤推定し、下側を空白のまま未描画にすることがある。
   通常行は確実に描画し、大規模シートはJSの仮想行レンダラーで軽量化する。 */
#pivot-table tbody tr {
  content-visibility: visible;
  contain-intrinsic-size: none;
}
#pivot-table tbody tr.group-header-row,
#pivot-table tbody tr.new-entity-row,
#pivot-table tbody tr.db-virtual-spacer-row,
#pivot-table tbody tr.new-entity-spacer-row {
  content-visibility: visible;
  contain-intrinsic-size: none;
}
/* left は JS が付与する（行先頭コントロール列の幅ぶん右へずらす）。ここで left:0 を書くと
   ヘッダー側（JS が 52px 相当を付与）とズレて、横スクロール時にエントリ名列だけ左へ食い込む。 */
#pivot-table td.col-entity {
  position: sticky; z-index: 5;
  /* 固定列は水平スクロール時に他列が背後を通過するため、必ず不透明背景にする。
     行ホバーや条件付き書式の半透明色との二重描画を避けるため background-color を直接指定し、
     後段の半透明 background ルールで上書きされても base 色が完全不透明になるよう --bg を下敷きにする */
  background-image: linear-gradient(var(--db-entity-bg), var(--db-entity-bg));
  background-color: var(--db-entity-bg);
  color: var(--db-entity-fg);
  font-family: var(--db-entity-font, var(--db-cell-font, var(--ui-font, inherit)));
  font-weight: var(--db-entity-bold); font-style: var(--db-entity-italic);
  font-size: var(--db-entity-font-size, inherit);
  -webkit-text-stroke-color: var(--db-entity-stroke-color, transparent);
  -webkit-text-stroke-width: var(--db-entity-stroke-width, 0px);
  paint-order: stroke fill;
  box-shadow: inset var(--db-entity-left-accent, 0px) 0 0 var(--db-entity-accent-color, var(--db-entity-fg));
  text-decoration-line: var(--db-entity-underline, none);
  text-decoration-color: var(--db-entity-accent-color, currentColor);
  cursor: pointer; white-space: normal; vertical-align: top;
  min-width: 120px; width: 120px;
  overflow: hidden;
}
#pivot-table td.col-entity .entity-name-cell-main {
  display: flex; align-items: center; align-content: center; width: 100%; min-height: 20px;
  position: relative; padding-right: 42px; box-sizing: border-box;
}
#pivot-table td.col-entity .entity-name-label {
  display: block; overflow: hidden; text-overflow: ellipsis; flex: 1; min-width: 0; line-height: 1.4; word-break: break-word;
}
#pivot-table td.col-entity:hover { color: var(--accent); }
/* 行先頭コントロール列（＋追加/ドラッグハンドル/選択チェックボックス）。常に先頭固定・並べ替え対象外。
   エントリ名列（col-entity）は列順に関係なく、固定設定時に JS が共通 left 値を付与する。 */
/* 行先頭コントロール列の幅。JS 側（固定列の sticky left の起点）もこの変数を読むので、
   タッチ環境などで広げる場合はこの変数だけを上書きする（両者がズレると固定列が横にずれる）。
   幅の内訳: ＋(14) + 2 + ハンドル(12) + 2 + チェックボックス(16) = 46px + 左右の余白と枠線。 */
#pivot-table, .pivot-table { --db-row-controls-w: 56px; }
#pivot-table th.col-row-controls-header, .pivot-table th.col-row-controls-header {
  position: sticky; left: 0; z-index: 12;
  min-width: var(--db-row-controls-w); width: var(--db-row-controls-w); max-width: var(--db-row-controls-w);
  box-sizing: border-box;
  background: var(--db-th-bg);
  padding: 3px 2px;
  text-align: center;
}
#pivot-table td.col-row-controls, .pivot-table td.col-row-controls {
  position: sticky; left: 0; z-index: 7;
  background-image: linear-gradient(var(--db-th-bg), var(--db-th-bg));
  background-color: var(--db-th-bg);
  min-width: var(--db-row-controls-w); width: var(--db-row-controls-w); max-width: var(--db-row-controls-w);
  box-sizing: border-box;
  padding: 1px 2px;
  overflow: hidden;
}
.row-select-all-cb {
  --gb-checkbox-size-override: 16px;
  width: 16px; height: 16px; margin: 0; cursor: pointer;
  accent-color: var(--accent); vertical-align: middle;
}
#pivot-table td.col-row-controls .row-controls-main, .pivot-table td.col-row-controls .row-controls-main {
  display: flex; align-items: center; height: 100%;
}
/* DB9: エントリ名列の固定解除 */
#pivot-table.entity-col-unpinned td.col-entity,
#pivot-table.entity-col-unpinned th.col-entity-header,
#pivot-table.entity-col-unpinned tfoot td.col-entity {
  position: static;
}
/* アクティブセル */
#pivot-table td.active-cell {
  outline: none !important; z-index: 6; position: relative;
  border: var(--db-active-width) solid var(--db-active-color) !important;
  box-shadow: inset var(--db-cell-left-accent, 0px) 0 0 var(--db-cell-accent-color, var(--db-cell-fg)) !important;
}
#pivot-table td.active-cell.col-entity {
  box-shadow: inset var(--db-entity-left-accent, 0px) 0 0 var(--db-entity-accent-color, var(--db-entity-fg)) !important;
