}

/* プロパティ型セル */
.cell-checkbox {
  width: 18px; height: 18px; padding: 0; border-radius: 4px;
  border: 1.5px solid var(--fg2); background: transparent; color: #fff;
  cursor: pointer; user-select: none; display: inline-flex; align-items: center; justify-content: center;
  vertical-align: middle;
}
.cell-checkbox:hover { border-color: var(--ui-accent); background: color-mix(in srgb, var(--ui-accent) 10%, transparent); }
.cell-checkbox.is-checked { border-color: var(--ui-accent); background: var(--ui-accent); color: var(--ui-accent-fg, #fff); }
.cell-checkbox:focus-visible { outline: 2px solid var(--a11y-focus-ring, var(--ui-accent)); outline-offset: 2px; }
.cell-checkbox:disabled { cursor: wait; }
.cell-number { font-variant-numeric: tabular-nums; }
.cell-date { white-space: nowrap; }
