/* グループヘッダー */
.group-header-row td {
  background: var(--bg3) !important; padding: 3px 12px !important;
  font-weight: bold; font-size: 13px; cursor: pointer; user-select: none;
}
.group-header-row:hover td { background: var(--bg4) !important; }
.group-header-row.db-option-color-header td {
  background: var(--db-option-bg) !important;
  color: var(--db-option-fg) !important;
}
.group-header-row.db-option-color-header:hover td {
  background: color-mix(in srgb, var(--db-option-bg) 86%, var(--db-option-fg)) !important;
}
.group-header-row.db-option-color-header .group-count { color: inherit; opacity: 0.78; }
.group-header-row.group-drop-target td {
