.group-header-row .group-toggle { margin-right: 6px; display: inline-block; transition: transform 0.15s; }
.group-header-row .group-toggle.collapsed { transform: rotate(-90deg); }
.group-header-row .group-count { color: var(--fg2); font-weight: normal; font-size: 12px; margin-left: 8px; }

/* ビュー切替タブ */
.view-tabs {
