.view-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
.view-tab-add { color: var(--fg2); font-size: 11px; padding: 6px 8px; cursor: pointer; background: none; border: none; }
.view-tab-add:hover { color: var(--accent); }

/* ギャラリービュー */
#gallery-view, .gallery-view {
  flex: 1; display: flex; overflow: hidden; padding: 0; flex-direction: column; min-height: 0;
}
.gallery-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  flex: 1; gap: 12px; padding: 16px; overflow: auto; min-height: 0;
}
.gallery-card {
  background: var(--bg2); border: 1px solid var(--border); border-radius: 6px;
  padding: 12px; cursor: pointer; transition: border-color 0.15s;
  overflow: hidden;
}
.gallery-card:hover { border-color: var(--accent); }
.gallery-card-title {
  font-weight: bold; font-size: 14px; margin-bottom: 8px;
  color: var(--fg); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.gallery-card-thumb {
  width: 100%; height: 140px; object-fit: cover; border-radius: 4px;
  margin-bottom: 8px; background: var(--bg3);
}
.gallery-card-props { font-size: 12px; color: var(--fg2); }
.gallery-card-prop { display: flex; gap: 4px; margin-bottom: 2px; }
.gallery-card-prop-name { color: var(--fg2); flex-shrink: 0; }
.gallery-card-prop-val { color: var(--fg); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* カンバンビュー（ボード表示） */
#kanban-view, .kanban-view { flex: 1; display: flex; flex-direction: column; overflow: hidden; padding: 0; min-height: 0; }
.kanban-board { flex: 1; display: flex; gap: 12px; min-height: 0; overflow-x: auto; overflow-y: hidden; align-items: flex-start; padding: 12px; }
.kanban-column {
  min-width: 240px; width: 240px; flex-shrink: 0;
  background: var(--bg2); border-radius: 8px; display: flex; flex-direction: column;
  max-height: 100%; overflow: hidden;
}
.kanban-column-header {
  padding: 8px 12px; font-size: 13px; font-weight: bold;
  border-bottom: 2px solid var(--border); display: flex; align-items: center; gap: 6px;
  flex-shrink: 0; user-select: none;
}
.kanban-column-header.db-option-color-header {
  background: var(--db-option-bg);
  color: var(--db-option-fg);
}
.kanban-column-header.db-option-color-header .kanban-count {
  color: inherit;
  background: color-mix(in srgb, var(--db-option-fg) 18%, transparent);
}
.kanban-column-header .kanban-count {
  font-size: 11px; font-weight: normal; color: var(--fg2);
  background: var(--bg4); border-radius: 8px; padding: 1px 6px;
}
.kanban-column-header .kanban-dot {
  width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0;
}
.kanban-column-body {
  flex: 1; overflow-y: auto; padding: 6px; display: flex; flex-direction: column; gap: 6px;
}
.kanban-column-body.drag-over { background: color-mix(in srgb, var(--ui-selection-bg) 22%, transparent); }
.kanban-card {
  background: var(--bg3); border: 1px solid var(--border); border-radius: 6px;
  padding: 8px 10px; cursor: grab; font-size: 13px; transition: border-color 0.1s;
}
.kanban-card:hover { border-color: var(--accent); }
.kanban-card.dragging { opacity: 0.5; }
.kanban-card-title { font-weight: bold; margin-bottom: 4px; }
.kanban-card-props { font-size: 11px; color: var(--fg2); }
.kanban-card-prop { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* タイムラインビュー */
#timeline-view, .timeline-view { flex: 1; overflow: auto; padding: 0; }
/* チャートビュー */
#chart-view, .chart-view { flex: 1; overflow: auto; padding: 0; flex-direction: column; }
.chart-settings-bar { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border-bottom: 1px solid var(--border); flex-shrink: 0; font-size: 12px; flex-wrap: wrap; }
.chart-label { color: var(--fg2); }
.chart-select { font-size: 12px; padding: 2px 4px; background: var(--bg3); color: var(--fg); border: 1px solid var(--border); border-radius: 3px; }
.chart-color-input { width: 28px; height: 24px; padding: 0; border: 1px solid var(--border); border-radius: 3px; background: var(--bg3); cursor: pointer; }
.chart-check { display: inline-flex; align-items: center; gap: 4px; color: var(--fg2); cursor: pointer; }
.chart-check input { margin: 0; }
.chart-area { flex: 1; display: flex; align-items: center; justify-content: center; padding: 16px; overflow: auto; }
.chart-area svg { max-width: 100%; }
/* グラフビュー */
#graph-view { flex: 1; overflow: hidden; padding: 0; display: none; flex-direction: column; }
.graph-view { flex: 1; overflow: hidden; padding: 0; display: flex; flex-direction: column; }
.widget-actions .tb-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.widget-actions .tb-icon-btn .ico {
  display: inline-block;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
}
.widget-actions .tb-icon-btn {
  width: 24px;
  height: 24px;
  min-width: 24px;
  padding: 0;
  border: 1px solid transparent;
}
.widget-header { display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; background: var(--bg3); border-bottom: 1px solid var(--border); font-size: 12px; }
.widget-title { font-weight: bold; color: var(--fg); }
.widget-actions { display: flex; gap: 4px; }
.widget-actions button { background: none; border: none; color: var(--fg2); cursor: pointer; padding: 2px; }
.widget-actions button:hover { color: var(--fg); }
.widget-content { padding: 12px; min-height: 60px; }
/* DB横断検索 */
.db-search-result { padding: 10px 12px; border-bottom: 1px solid var(--bg4); cursor: pointer; }
.db-search-result:hover { background: var(--bg4); }
/* 比較ビュー */
.compare-header { display: flex; justify-content: space-between; align-items: center; padding: 6px 12px; background: var(--bg2); border-bottom: 1px solid var(--border); flex-shrink: 0; }
.compare-label { font-size: 13px; font-weight: bold; color: var(--fg); max-width: 40%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compare-stats { font-size: 12px; color: var(--fg2); }
.compare-body { display: flex; flex: 1; overflow: hidden; }
.compare-panel { flex: 1; overflow-y: auto; padding: 0; font-family: monospace; font-size: 13px; line-height: 1.6; border-right: 1px solid var(--border); }
.compare-panel:last-child { border-right: none; }
.compare-line { padding: 1px 12px; white-space: pre-wrap; word-break: break-all; min-height: 1.6em; }
.compare-changed { background: rgba(86,156,214,0.15); }
.compare-removed { background: rgba(209,105,105,0.2); }
.compare-added { background: rgba(96,139,78,0.2); }
.compare-empty { background: var(--bg3); min-height: 1.6em; }

/* Calendar Month Grid */
.cal-month-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 0; border: 1px solid var(--border); }
.cal-month-header { background: var(--bg3); color: var(--fg2); font-size: 11px; font-weight: bold; padding: 4px; text-align: center; border-bottom: 1px solid var(--border); }
.cal-month-cell { min-height: 80px; border: 1px solid var(--border); padding: 2px; cursor: default; position: relative; }
.cal-month-cell:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
.cal-month-cell.cal-other-month { opacity: 0.4; }
.cal-month-cell.cal-today { background: color-mix(in srgb, var(--ui-selection-bg) 22%, transparent); }
.cal-day-num { font-size: 11px; color: var(--fg2); padding: 2px 4px; }
.cal-today .cal-day-num { color: var(--accent); font-weight: bold; }
.cal-month-event { font-size: 10px; padding: 1px 22px 1px 4px; margin: 1px 0; border-radius: 3px; color: #fff; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; position: relative; }
.cal-month-event:hover { opacity: 0.8; }
.cal-month-more { font-size: 10px; color: var(--fg2); padding: 1px 4px; }

/* Calendar Week Grid */
.cal-week-grid { display: grid; grid-template-columns: 50px repeat(7, 1fr); gap: 0; border: 1px solid var(--border); overflow-y: auto; max-height: calc(100vh - 200px); }
.cal-week-corner { background: var(--bg3); border: 1px solid var(--border); }
.cal-week-header { background: var(--bg3); color: var(--fg2); font-size: 11px; font-weight: bold; padding: 4px; text-align: center; border: 1px solid var(--border); position: sticky; top: 0; z-index: 2; }
.cal-week-time { font-size: 10px; color: var(--fg2); padding: 2px 4px; text-align: right; border: 1px solid var(--border); background: var(--bg2); box-sizing: border-box; }
.cal-week-cell { min-height: 28px; border: 1px solid var(--border); position: relative; box-sizing: border-box; }
.cal-week-cell:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }

/* Calendar Day Grid */
.cal-day-grid { display: grid; grid-template-columns: 50px 1fr; gap: 0; border: 1px solid var(--border); overflow-y: auto; max-height: calc(100vh - 200px); }
.cal-day-time { font-size: 10px; color: var(--fg2); padding: 2px 4px; text-align: right; border: 1px solid var(--border); background: var(--bg2); box-sizing: border-box; }
.cal-day-cell { min-height: 32px; border: 1px solid var(--border); padding: 2px; position: relative; box-sizing: border-box; }
.cal-day-cell:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
.cal-day-event { font-size: 10px; padding: 2px 26px 2px 6px; margin: 1px 0; border-radius: 3px; color: #fff; cursor: pointer; position: relative; box-sizing: border-box; }
.cal-event-title { display: block; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cal-day-event:hover { opacity: 0.8; }
.cal-day-event[draggable=true] { cursor: grab; }
.cal-drag-preview { opacity: 0.6; pointer-events: none; }
.cal-week-cell { min-height: 40px; }
.cal-week-time, .cal-day-time { height: 40px; line-height: 40px; }

/* ==============================
   エントリページ
   ============================== */
#entity-view { display: none; flex: 1; overflow: auto; padding: 16px; flex-direction: column; gap: 16px; }
#entity-view.active { display: flex; }
#entity-title {
  font-size: 22px; font-weight: var(--page-title-bold); font-style: var(--page-title-italic);
  font-family: var(--page-title-font, inherit);
  color: var(--page-title-fg);
  background: var(--page-title-bg, transparent);
  -webkit-text-stroke-color: var(--page-title-stroke-color, transparent);
  -webkit-text-stroke-width: var(--page-title-stroke-width, 0px);
  paint-order: stroke fill;
  box-shadow: calc(-1 * var(--page-title-left-accent, 0px)) 0 0 0 var(--page-title-accent-color, var(--page-title-fg));
  text-decoration-line: var(--page-title-underline, none);
  text-decoration-color: var(--page-title-accent-color, currentColor);
  padding: 4px 0 12px 0; border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}

/* プロパティテーブル（縦型） — 旧形式 */
#entity-props-table {
  border-collapse: collapse; width: 100%;
}
#entity-props-table th, #entity-props-table td {
  border: 1px solid var(--border); padding: 3px 10px;
  vertical-align: top; font-size: 13px; text-align: left;
}
#entity-props-table th {
  background: var(--bg3); color: var(--fg2); font-weight: normal;
  width: 140px; white-space: nowrap;
}

/* エントリ親 DB リンク */
#entity-parent-link a {
  color: var(--fg2); text-decoration: none; cursor: pointer;
  display: inline-flex; align-items: center; gap: 4px;
}
#entity-parent-link a:hover { color: var(--accent); text-decoration: underline; }

/* エントリプロパティグリッド (複数段表示・D&D 並べ替え・開閉・列幅設定)
   .entity-props-grid-container は renderEntityPropsGridInto がフルページ版(#entity-props-grid)・
   サブパネル版にも付与する共通クラス。列幅は --entity-prop-col-width
   (既定300px, 列幅設定ポップアップで上書き) で揃える。 */
.entity-props-grid-container {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--entity-prop-col-width, 300px), 1fr));
  gap: 4px 12px;
}
#entity-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--entity-prop-col-width, 300px), 1fr));
  gap: 4px 12px;
  padding: 6px 12px 12px;
}
/* プロパティ一覧ヘッダー (開閉トグル + 列幅設定ボタン)。グリッドの先頭行として全幅を占める。 */
.entity-props-header {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0 4px;
}
.entity-props-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 0;
  background: transparent;
  color: var(--fg2);
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  padding: 4px 2px;
  border-radius: 3px;
}
.entity-props-toggle:hover { color: var(--fg); background: var(--bg3); }
.entity-props-toggle-chevron { display: inline-flex; align-items: center; justify-content: center; transition: transform 0.15s; }
.entity-props-toggle[aria-expanded="true"] .entity-props-toggle-chevron { transform: rotate(90deg); }
.entity-props-col-width-btn { margin-left: auto; }
@media (pointer: coarse), (max-width: 640px) {
  .entity-props-toggle,
  .entity-props-col-width-btn {
    min-height: 44px !important;
    min-width: 44px !important;
  }
}
/* プロパティ本体 (並び替えツールバー + グループ見出し + カード)。display:contents で
   ラッパー自体はレイアウトに関与させず、子要素を外側グリッドの直接の子として複数列に配置する。 */
.entity-props-body { display: contents; }
/* 列幅設定ポップアップ (.gb-context-menu 共通クラスに相乗り)。.gb-context-menu.entity-props-col-width-popup
   と複合セレクタにして、CSS読み込み順に依存せず確実に padding 等を上書きする。 */
.gb-context-menu.entity-props-col-width-popup {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 220px;
  padding: 10px 12px;
}
.entity-props-col-width-popup-title { font-size: 12px; color: var(--fg2); }
.entity-props-col-width-popup-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 12px; color: var(--fg); }
.entity-props-col-width-popup-row input[type="number"] {
  width: 72px;
  padding: 3px 6px;
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 3px;
}
/* 列一覧の文字選択コピー ポップアップ（gb-entity-props-selection.js）。
   .gb-context-menu 共通クラスへ相乗りしつつ、複合セレクタで確実に上書きする。 */
.gb-context-menu.entity-props-selection-copy-popup {
  display: flex;
  padding: 3px;
}
.entity-props-selection-copy-btn {
  display: flex; align-items: center; gap: 4px;
  font-size: 12px;
  padding: 4px 8px;
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 3px;
  cursor: pointer;
}
.entity-props-selection-copy-btn:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }

.entry-prop-card {
  display: flex; align-items: flex-start; gap: 6px;
  padding: 4px 8px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: var(--bg2);
  min-height: 28px;
}
.entry-prop-card:hover { border-color: var(--border); }
.entry-prop-card.dragging { opacity: 0.4; }
.entry-prop-card.drag-over-left { box-shadow: inset 3px 0 0 var(--accent); }
.entry-prop-card.drag-over-right { box-shadow: inset -3px 0 0 var(--accent); }
.entry-prop-name {
  font-size: 12px; color: var(--fg2); font-weight: 500;
  min-width: 80px; padding-top: 2px;
  user-select: none;
  display: inline-flex; align-items: center; gap: 4px;
}
/* レイアウト編集時の並べ替え専用ハンドル（row-drag-handle と同じ慣行）。
   カード自体は draggable にしないため、掴めるのはこのハンドルだけになる。 */
.entry-prop-drag-handle {
  flex: 0 0 auto;
  width: 14px; height: 14px;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--fg2);
  cursor: grab;
}
.entry-prop-drag-handle:active { cursor: grabbing; }
.entry-prop-type-icon { display: inline-flex; align-items: center; flex: 0 0 auto; color: var(--fg2); }
.entry-prop-type-icon svg { width: 14px; height: 14px; }
.entry-prop-values {
  flex: 1; display: flex; flex-direction: column; gap: 2px;
  font-size: 13px; color: var(--fg);
}
/* ＋（候補値を追加）を最後の値と同じ行に並べるための末尾ラッパー */
.entry-prop-value-tail { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; min-width: 0; }
.entry-prop-value-tail > .cell-value { flex: 0 1 auto; min-width: 0; }
/* 列タイプ選択のカスタムドロップダウン（アイコン付き） */
.pt-type-select-btn {
  display: flex; align-items: center; gap: 6px; width: 100%;
  padding: 5px 8px; background: var(--bg); color: var(--fg);
  border: 1px solid var(--border); border-radius: 4px; cursor: pointer;
  font-size: 13px; text-align: left; box-sizing: border-box;
}
.pt-type-select-btn:hover { border-color: var(--accent); }
.pt-type-select-icon, .pt-type-select-caret { display: inline-flex; align-items: center; color: var(--fg2); flex: 0 0 auto; }
.pt-type-select-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pt-type-menu { max-height: 60vh; overflow-y: auto; }
.pt-type-menu-item { display: flex; align-items: center; gap: 8px; }
.pt-type-menu-icon { display: inline-flex; align-items: center; color: var(--fg2); flex: 0 0 auto; }
.pt-type-menu-item.active { color: var(--accent); font-weight: 600; }
/* カラー列タイプ: 横長のカラースウォッチ（共通カラーパレットで設定） */
.cell-color-swatch {
  display: inline-block; width: 100%; max-width: 120px; min-width: 48px; height: 18px;
  border-radius: 3px; border: 1px solid var(--border); cursor: pointer;
  box-sizing: border-box; vertical-align: middle;
}
.cell-color-swatch.is-empty {
  background: transparent; color: var(--fg2); font-size: 11px;
  text-align: center; line-height: 16px; white-space: nowrap; overflow: hidden;
}

/* エントリ「ノートを作成」ボタン */
#entity-create-note-btn {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
#entity-create-note-btn button {
  padding: 6px 12px; font-size: 12px;
  background: var(--bg3); color: var(--fg);
  border: 1px solid var(--border); border-radius: 4px;
  cursor: pointer;
}
#entity-create-note-btn button:hover { background: var(--bg4); border-color: var(--accent); }
/* エントリ画面の作成系アクションボタンは、置かれる場所（未作成エントリの
   作成ボタン欄／エントリ詳細のアクション欄）に関わらず同じ見た目にする。
   以前は #entity-create-note-btn 配下だけに指定していたため、同じボタンが
   詳細側では素のボタンとして描画されていた。 */
.entity-create-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  white-space: nowrap;
  line-height: 1.2;
}
.entity-create-action-btn .entity-create-action-icon,
.entity-create-action-btn .entity-create-action-icon svg {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
}
@media (max-width: 430px) {
  .entity-create-action-btn {
    min-height: 44px;
    padding: 10px 12px;
  }
}

/* 自由記述エリア */
#entity-freetext {
  min-height: 200px; padding: 12px;
  background: var(--page-text-bg, var(--content-bg, var(--bg))); border: 1px solid var(--border); border-radius: 4px;
  color: var(--page-text-fg); font-size: 13px; line-height: 1.6;
  font-weight: var(--page-text-bold); font-style: var(--page-text-italic);
  outline: none; flex: 1;
}
#entity-freetext:focus { border-color: var(--accent); }
/* ドラッグオーバー */
.drop-caret { position: absolute; block-size: 2px; background: var(--accent); pointer-events: none; z-index: 100; inset-inline: 0; transition: inset-block-start 0.05s; }
/* 埋め込みメディア */
.embed-media { position: relative; display: block; margin-block: 4px; margin-inline: auto; max-inline-size: 100%; inline-size: fit-content; }
.embed-media img, .embed-media video { display: block; border-radius: 4px; max-inline-size: 100%; }
.embed-media:hover { outline: 2px solid var(--accent); outline-offset: 2px; }
/* シート: カンバン/ギャラリーカード上部ツールバーと画像プレビュー */
.db-card-view-toolbar {
  display: flex; align-items: center; gap: 8px; padding: 6px 12px;
  border-bottom: 1px solid var(--border); flex-shrink: 0; font-size: 12px; flex-wrap: wrap;
}
.db-card-view-toolbar-btn {
  min-height: 24px; padding: 2px 8px; font-size: 12px;
}
.db-card-props-settings {
  border-top: 1px solid var(--border);
  margin-top: 6px;
  padding-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.db-card-props-settings-title {
  padding: 0 6px 2px;
  color: var(--fg2);
  font-size: 11px;
}
.db-card-props-number-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  color: var(--fg);
}
.db-card-props-number-option span {
  flex: 1 1 auto;
  min-width: 0;
}
.db-card-props-number-input {
  width: 64px;
  min-width: 64px;
  height: 24px;
  padding: 2px 6px;
  font-size: 12px;
  box-sizing: border-box;
}
.gallery-grid {
  align-content: start; grid-auto-rows: minmax(188px, auto);
}
.gallery-card {
  min-height: 188px; box-sizing: border-box;
  display: flex; flex-direction: column; gap: 8px;
}
.gallery-card-title {
  margin-bottom: 0; padding-right: 24px; flex-shrink: 0;
}
.gallery-card-thumb {
  margin-bottom: 0; display: block; flex: 0 0 140px;
}
.gallery-card-props {
  display: flex; flex-direction: column; gap: 2px; min-width: 0;
}
.gallery-card-prop {
  min-width: 0; margin-bottom: 0;
}
.gallery-card-prop-val {
  flex: 1; min-width: 0;
}
.gallery-card-prop-val,
.kanban-card-prop,
.tl-card-prop-value:not(.tl-card-prop-value--editable) {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--db-card-prop-lines, 1);
  white-space: normal;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tl-card-prop-value--editable .value-text,
.tl-card-prop-value--editable .cell-number,
.tl-card-prop-value--editable .cell-date,
.tl-card-prop-value--editable .cell-select-val {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--db-card-prop-lines, 1);
  white-space: normal;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tl-grid[data-cell-overflow="wrap"] .tl-card-prop-value:not(.tl-card-prop-value--editable),
.tl-grid[data-cell-overflow="clip"] .tl-card-prop-value:not(.tl-card-prop-value--editable),
.tl-grid[data-cell-overflow="wrap"] .tl-card-prop-value--editable .value-text,
.tl-grid[data-cell-overflow="clip"] .tl-card-prop-value--editable .value-text,
.tl-grid[data-cell-overflow="wrap"] .tl-card-prop-value--editable .cell-number,
.tl-grid[data-cell-overflow="clip"] .tl-card-prop-value--editable .cell-number,
.tl-grid[data-cell-overflow="wrap"] .tl-card-prop-value--editable .cell-date,
.tl-grid[data-cell-overflow="clip"] .tl-card-prop-value--editable .cell-date,
.tl-grid[data-cell-overflow="wrap"] .tl-card-prop-value--editable .cell-select-val,
.tl-grid[data-cell-overflow="clip"] .tl-card-prop-value--editable .cell-select-val {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--db-card-prop-lines, 1);
  white-space: normal;
  overflow: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.db-card-image-preview {
  display: grid; grid-template-columns: repeat(var(--db-card-thumb-columns, 3), minmax(0, 1fr)); gap: 4px;
  margin: 6px 0 8px; position: relative; flex-shrink: 0;
}
.db-card-image-preview img,
.db-card-media-placeholder {
  width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 4px;
  background: var(--bg4); border: 1px solid var(--border); cursor: zoom-in;
}
.db-card-image-host {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
}
.db-card-image-host > img {
  display: block;
  width: 100%;
  height: 100%;
}
.db-card-media-placeholder {
  display: inline-flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 3px; color: var(--fg2); font-size: 11px;
}
.gallery-card-image-preview {
  grid-template-columns: repeat(var(--db-card-thumb-columns, 2), minmax(0, 1fr)); margin-top: 0; margin-bottom: 0;
}
.gallery-card-image-preview img {
  aspect-ratio: 16 / 10;
}
.gallery-card-image-preview .db-card-image-host { aspect-ratio: 16 / 10; }
.kanban-card-image-preview {
  margin-bottom: 6px;
}
.db-card-image-more {
  position: absolute; right: 5px; bottom: 5px; min-width: 24px; height: 20px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 6px; border-radius: 10px; background: rgba(0, 0, 0, 0.68);
  color: #fff; font-size: 11px; line-height: 1;
}
/* フローティングメディアコントロール（body直下に生成） */
#media-float-controls {
  display: none;
  position: fixed;
  z-index: calc(var(--ui-z-menu, 200) - 2);
  align-items: center;
  gap: var(--ui-space-1, 2px);
  padding: var(--ui-space-1, 2px);
  background: var(--ui-bg-surface, rgba(0,0,0,0.82));
  color: var(--ui-fg-default, #e5e5e5);
  border: 1px solid var(--ui-border-strong, var(--ui-border, #555));
  border-radius: var(--ui-radius-md, 6px);
  box-shadow: var(--ui-shadow-lg, 0 10px 28px rgba(0,0,0,0.38));
  backdrop-filter: blur(4px);
}
#media-float-controls.visible { display: flex; }
#media-float-controls button {
  width: var(--ui-h-sm, 28px);
  min-width: var(--ui-h-sm, 28px);
  height: var(--ui-h-sm, 28px);
  min-height: var(--ui-h-sm, 28px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font-size: var(--ui-font-12, 12px);
  line-height: 1;
  border-radius: var(--ui-radius-xs, 3px);
}
#media-float-controls button:hover,
#media-float-controls button:focus-visible {
  background: var(--ui-hover-bg, rgba(255,255,255,0.16));
  color: var(--ui-hover-fg, var(--ui-fg-strong, #fff));
  border-color: var(--ui-border, #555);
  outline: none;
}
#media-float-controls button.active {
  background: color-mix(in srgb, var(--ui-accent, var(--accent)) 24%, transparent);
  color: var(--ui-accent, var(--accent));
  border-color: color-mix(in srgb, var(--ui-accent, var(--accent)) 55%, transparent);
}
#media-float-controls .media-float-danger { color: var(--ui-danger, var(--red)); }
#media-float-controls svg,
#media-float-controls .ico {
  width: var(--ui-icon-sm, 14px) !important;
  height: var(--ui-icon-sm, 14px) !important;
  display: block;
}
#media-float-controls .media-float-icon-fallback {
  width: var(--ui-icon-sm, 14px);
  height: var(--ui-icon-sm, 14px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
}
@media (max-width: 640px) {
  #media-float-controls {
    gap: var(--ui-space-2, 4px);
    padding: var(--ui-space-2, 4px);
    z-index: var(--ui-z-toast, 400);
  }
  #media-float-controls button {
    width: 44px;
    min-width: 44px;
    height: 44px;
    min-height: 44px;
  }
  #media-float-controls svg,
  #media-float-controls .ico {
    width: var(--ui-icon-md, 16px) !important;
    height: var(--ui-icon-md, 16px) !important;
  }
}
/* リサイズハンドル（四隅）。メニュー・モーダル・トーストより背面に置く。 */
.em-resize-handle {
  display: none; position: fixed; width: 14px; height: 14px; z-index: calc(var(--ui-z-menu, 200) - 1);
  background: var(--accent); border: 2px solid var(--ui-accent-fg, var(--ui-fg-strong)); border-radius: 2px; cursor: nwse-resize;
}
.em-resize-handle.visible { display: block; }
.em-resize-handle[data-media-resize-corner="nw"],
.em-resize-handle[data-media-resize-corner="se"] { cursor: nwse-resize; }
.em-resize-handle[data-media-resize-corner="ne"],
.em-resize-handle[data-media-resize-corner="sw"] { cursor: nesw-resize; }
@media (max-width: 640px) {
  .em-resize-handle {
    width: 24px;
    height: 24px;
    border-radius: var(--ui-radius-sm, 4px);
  }
}
/* アウトライナー読み込み中 */
.tree-spinner { display: flex; align-items: center; padding: 2px 0; }
/* グローバルフィルタバー */
#global-filter-bar { background: var(--bg2); }
@keyframes spin { to { transform: rotate(360deg); } }
.chat-spinner {
  display: inline-block; width: 14px; height: 14px; border: 2px solid var(--fg2);
  border-top-color: var(--accent); border-radius: 50%; animation: spin 0.8s linear infinite;
}
#entity-freetext > div, #page-content > div { margin-block: 2px; }
#entity-freetext:empty::before { content: '自由記述...'; color: var(--fg2); }

/* 目次の項目。旧実装は見た目もホバーも JS のインラインstyle直書きだったため、
   ポインタが項目に乗ったまま目次が作り直されると mouseleave が発火せず、
   ハイライトが消えないまま残った。CSS の :hover へ移して構造的に解消する。 */
#note-toc .note-toc-item {
  display: block;
  inline-size: 100%;
  padding-block: 2px;
  padding-inline: 0 4px;
  cursor: pointer;
  border: 0;
  background: transparent;
  text-align: start;
  font: inherit;
  border-radius: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
}
#note-toc .note-toc-item:hover,
#note-toc .note-toc-item:focus-visible { background: var(--bg4); }
#note-toc .note-toc-level-1 { padding-inline-start: 0; color: var(--accent); }
#note-toc .note-toc-level-2 { padding-inline-start: 12px; }
#note-toc .note-toc-level-3 { padding-inline-start: 24px; }
#note-toc .note-toc-level-4 { padding-inline-start: 36px; }
#note-toc .note-toc-level-5 { padding-inline-start: 48px; }
#note-toc .note-toc-level-6 { padding-inline-start: 60px; }
#note-toc .note-toc-empty { color: var(--fg2); padding: 4px; }

#note-toc-resize {
  --note-toc-resize-hit: 8px;
  position: relative;
  outline: none;
  box-sizing: border-box;
  background: transparent !important;
  border-right-color: transparent !important;
}
.note-editor-body {
  min-height: 0;
}
.note-editor-body #note-toc,
.note-editor-body #note-toc-resize {
  min-height: 0;
  box-sizing: border-box;
}
/* 本文だけ min-height を 0 にしない。旧実装では Meldex.html のインラインstyleが
   min-height:200px を持っていたため、この規則の min-height:0 は #page-content には
   元から効いていなかった。レイアウトを外部CSS（gb-layout.part01.css）へ移すにあたり、
   当時の実効値（200px）を保つために本文を対象から外す。 */
.note-editor-body #page-content {
  box-sizing: border-box;
}
#note-toc-resize::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: var(--ui-border, var(--border));
}
#note-toc-resize:hover,
#note-toc-resize:focus-visible {
  background: transparent !important;
  border-right-color: transparent !important;
}
#note-toc-resize:hover::before,
#note-toc-resize:focus-visible::before {
  width: 2px;
  background: var(--ui-accent, var(--accent));
}
@media (pointer: coarse), (max-width: 640px) {
  #page-view {
    --note-page-mobile-top-offset: 52px;
    height: min(
      calc((var(--meldex-window-inner-height, 100dvh) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1)),
      calc((var(--cloud-visual-vh, 100dvh) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1)),
      calc((100dvh - var(--cloud-visual-offset-top, 0px) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1))
    ) !important;
    max-height: min(
      calc((var(--meldex-window-inner-height, 100dvh) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1)),
      calc((var(--cloud-visual-vh, 100dvh) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1)),
      calc((100dvh - var(--cloud-visual-offset-top, 0px) - var(--note-page-mobile-top-offset)) * var(--meldex-inverse-layout-zoom, 1))
    ) !important;
    min-height: 0 !important;
  }
  #page-view .note-editor-body {
    flex: 1 1 auto;
    min-height: 0 !important;
  }
  #note-toc-resize {
    --note-toc-resize-hit: 24px;
    align-self: stretch;
    max-height: 100%;
  }
}

/* テンプレートギャラリー（刷新UI: 検索付きヘッダー + Tierチップ行 + カード/プレビューペインの2ペイン構成） */
.db-template-modal {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.db-template-gallery-modal {
  width: min(1040px, calc(100vw - 48px));
  max-width: min(1040px, calc(100vw - 48px));
  max-height: min(85vh, 820px);
}
.db-template-preview-modal,
.db-template-create-modal,
.db-template-edit-modal {
  width: min(500px, calc(100vw - 32px));
  max-width: min(500px, calc(100vw - 32px));
  max-height: min(74vh, 680px);
  overflow: auto;
}
.db-template-gallery-modal.gb-modal-shell > .gb-modal-shell-body {
  display: flex;
  flex-direction: column;
  overflow: hidden;
