/* .gb-swatch スタイルは gb-color-palette.js から注入 */
.tree-toggle {
  width: 16px; height: 16px; flex-shrink: 0; color: var(--outliner-muted-fg); font-size: 0;
  display: inline-flex; align-items: center; justify-content: center;
