}
/* メインレイアウト */
.gb-cal-main { display: flex; flex: 1; min-width: 0; min-height: 0; overflow: hidden; }
.gb-cal-sidebar { width: 260px; flex-shrink: 0; min-height: 0; border-right: 1px solid var(--cal-grid-line, var(--border)); overflow-y: auto; padding: 12px; background: var(--cal-sidebar-bg, var(--bg2)); color: var(--cal-sidebar-fg, var(--cal-fg, var(--fg))); }
.gb-cal-sidebar.gb-cal-hidden { display: none; }
.gb-cal-root.gb-cal-sidebar-only .gb-cal-sidebar { display: block; width: 100%; border-right: 0; }
.gb-cal-root.gb-cal-sidebar-only .gb-cal-sidebar-resize,
.gb-cal-root.gb-cal-sidebar-only .gb-cal-content,
.gb-cal-root.gb-cal-sidebar-only .gb-cal-right-panel { display: none !important; }
