.gb-cal-sidebar-add-task:hover { border-color: var(--cal-accent, var(--accent)); color: var(--cal-accent, var(--accent)); }
.gb-cal-sidebar-add-task svg { width: 16px; height: 16px; display: block; }
.gb-cal-mini-nav { width: 22px; height: 22px; padding: 0; border: 1px solid transparent; border-radius: 4px; background: transparent; color: var(--cal-muted-fg, var(--fg2)); cursor: pointer; display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; }
.gb-cal-mini-nav:hover { background: var(--cal-cell-hover-bg, var(--ui-hover-bg)); color: var(--cal-cell-hover-fg, var(--ui-hover-fg)); border-color: var(--cal-control-border, var(--ui-border)); }
