/* 月カレンダー */
.gb-cal-month { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-template-rows: 28px repeat(6, minmax(0, 1fr)); gap: 1px; background: var(--cal-grid-line, var(--border)); flex: 1 1 auto; min-height: 0; height: 100%; overflow: hidden; }
