.gb-cal-week-event { position: absolute; left: 2px; right: var(--cal-event-create-gap); background: var(--cal-event-bg, var(--accent)); color: var(--cal-event-fg, var(--ui-accent-fg, var(--ui-fg-strong))); border: 1px solid var(--cal-event-border, transparent); box-sizing: border-box; font-size: 10px; padding: 2px 26px 2px 4px; border-radius: 3px; overflow: hidden; cursor: pointer; z-index: 2; }
.gb-cal-production-task-event { border-color: color-mix(in srgb, var(--cal-event-fg, var(--ui-fg-strong)) 52%, transparent) !important; box-shadow: inset 3px 0 0 color-mix(in srgb, var(--cal-event-fg, var(--ui-fg-strong)) 74%, transparent); }
