  font-family: var(--page-table-header-font, inherit);
  font-size: var(--page-table-header-font-size, inherit);
  text-align: start;
}
#page-content td, #entity-freetext td, #dp-editable td, #board-note-editable td {
  background: var(--page-table-cell-bg, transparent) !important;
  color: var(--page-table-cell-fg, var(--page-text-fg, var(--fg))) !important;
  font-weight: var(--page-table-cell-bold, normal);
  font-style: var(--page-table-cell-italic, normal);
  font-family: var(--page-table-cell-font, inherit);
  font-size: var(--page-table-cell-font-size, inherit);
}
#page-content th, #page-content td,
#entity-freetext th, #entity-freetext td,
#dp-editable th, #dp-editable td,
#board-note-editable th, #board-note-editable td {
  padding: var(--page-table-cell-padding-y, 6px) var(--page-table-cell-padding-x, 10px) !important;
  border: var(--page-table-border-width, 1px) solid var(--page-table-border-color, var(--border)) !important;
  /* セルの寸法は表レイアウト内部の値。JS側（gb-note-enhance.part03.js）も物理プロパティで
     書き込むため、ここも物理のまま揃える（論理プロパティにすると列幅調整が効かなくなる）。 */
  min-width: 1em;
  height: auto;
  line-height: var(--page-text-line-height, 160%);
}
#page-content td:empty::before, #page-content th:empty::before,
#entity-freetext td:empty::before, #entity-freetext th:empty::before,
#dp-editable td:empty::before, #dp-editable th:empty::before,
#board-note-editable td:empty::before, #board-note-editable th:empty::before {
  content: '\200B';
}
#page-content tr:hover td, #entity-freetext tr:hover td, #dp-editable tr:hover td, #board-note-editable tr:hover td {
  background: var(--page-table-row-hover-bg, var(--bg2)) !important;
  color: var(--page-table-row-hover-fg, var(--page-table-cell-fg, var(--page-text-fg, var(--fg)))) !important;
}

/* === Note styling: copy button === */
.copy-btn {
  position: absolute;
  inset-block-start: 4px;
  inset-inline-end: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  min-width: 24px;
  height: 24px;
  background: var(--page-copy-button-bg, var(--bg3));
  border: var(--page-copy-button-border-width, 1px) solid var(--page-copy-button-border, var(--border));
  border-radius: var(--page-copy-button-radius, 4px);
  padding: 0;
  cursor: pointer;
  color: var(--page-copy-button-fg, var(--fg2));
  font-size: var(--page-copy-button-font-size, inherit);
  font-family: var(--page-copy-button-font, inherit);
  font-weight: var(--page-copy-button-bold, normal);
  font-style: var(--page-copy-button-italic, normal);
  opacity: var(--page-copy-button-opacity, 0.7);
  transition: opacity 0.15s;
  z-index: 5;
  line-height: 1;
}
.copy-btn svg {
  width: 14px;
  height: 14px;
  display: block;
}
.copy-btn:hover {
  opacity: 1;
  background: var(--page-copy-button-hover-bg, var(--bg4));
  color: var(--page-copy-button-hover-fg, var(--page-copy-button-fg, var(--fg)));
}

/* === Note styling: table add buttons === */
.table-add-row,
.table-add-col {
  position: fixed;
  z-index: 10000;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 52px;
  height: 24px;
  padding: 0 8px;
  margin: 0;
  background: var(--page-table-control-bg, var(--bg2));
  border: var(--page-table-control-border-width, 1px) dashed var(--page-table-control-border, var(--border));
  border-radius: var(--page-table-control-radius, 999px);
  color: var(--page-table-control-fg, var(--fg2));
  font-size: var(--page-table-control-font-size, 12px);
  font-family: var(--page-table-control-font, inherit);
  font-weight: var(--page-table-control-bold, normal);
  font-style: var(--page-table-control-italic, normal);
  line-height: 1;
  cursor: pointer;
  text-align: center;
  box-shadow: 0 2px 8px var(--page-table-control-shadow, rgba(0,0,0,0.25));
  user-select: none;
  white-space: nowrap;
}
.table-add-row:hover,
.table-add-col:hover {
  background: var(--page-table-control-hover-bg, var(--bg3));
  color: var(--page-table-control-hover-fg, var(--fg));
  border-color: var(--page-table-control-hover-border, var(--page-table-control-border, var(--border)));
}
.table-mini-toolbar {
  position: fixed;
  z-index: 10000;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  background: var(--page-table-toolbar-bg, var(--page-table-control-bg, var(--bg2)));
  border: var(--page-table-toolbar-border-width, 1px) solid var(--page-table-toolbar-border, var(--page-table-control-border, var(--border)));
  border-radius: var(--page-table-toolbar-radius, 4px);
  box-shadow: 0 2px 10px var(--page-table-toolbar-shadow, rgba(0,0,0,0.28));
  font-size: var(--page-table-toolbar-font-size, 11px);
  font-family: var(--page-table-toolbar-font, inherit);
  font-weight: var(--page-table-toolbar-bold, normal);
  font-style: var(--page-table-toolbar-italic, normal);
  line-height: 1;
  user-select: none;
}
.table-mini-toolbar-btn {
  padding: 2px 6px;
  font-size: 11px;
  line-height: 1.4;
  background: var(--page-table-toolbar-button-bg, var(--bg3));
  border: var(--page-table-toolbar-button-border-width, 1px) solid var(--page-table-toolbar-button-border, var(--border));
  border-radius: var(--page-table-toolbar-button-radius, 2px);
  cursor: pointer;
  color: var(--page-table-toolbar-fg, var(--fg));
}
.table-mini-toolbar-btn:hover {
  background: var(--page-table-toolbar-button-hover-bg, var(--bg4));
  color: var(--page-table-toolbar-hover-fg, var(--page-table-toolbar-fg, var(--fg)));
}
td:has(.cell-edit), th:has(.cell-edit) {
  outline: var(--page-cell-edit-outline-width, 2px) solid var(--page-cell-edit-outline-color, var(--accent));
}

/* === Note styling: blockquote citation === */
blockquote .quote-cite {
  display: block;
  margin-block-start: 8px;
  font-size: var(--page-quote-cite-font-size, 0.85em);
  font-family: var(--page-quote-cite-font, inherit);
  font-weight: var(--page-quote-cite-bold, normal);
  color: var(--page-quote-cite-fg, var(--fg2));
  font-style: var(--page-quote-cite-italic, italic);
  -webkit-text-stroke-color: var(--page-quote-cite-stroke-color, transparent);
  -webkit-text-stroke-width: var(--page-quote-cite-stroke-width, 0px);
  paint-order: stroke fill;
  text-decoration-line: var(--page-quote-cite-underline, none);
  text-decoration-color: var(--page-quote-cite-accent-color, currentColor);
  opacity: var(--page-quote-cite-opacity, 0.6);
  transition: opacity 0.2s;
}
blockquote:hover .quote-cite {
  opacity: var(--page-quote-cite-hover-opacity, 1);
}
blockquote .quote-cite a {
  color: var(--page-quote-cite-link-fg, var(--accent));
  font-size: var(--page-quote-cite-link-font-size, inherit);
  font-family: var(--page-quote-cite-link-font, inherit);
  font-weight: var(--page-quote-cite-link-bold, inherit);
  font-style: var(--page-quote-cite-link-italic, inherit);
