}

/* === Note styling: link hover === */
#page-content .auto-link:hover, #entity-freetext .auto-link:hover, #dp-editable .auto-link:hover, #board-note-editable .auto-link:hover {
  background: var(--page-link-hover-bg, var(--bg3));
  border-radius: var(--page-link-hover-radius, 2px);
}

/* === Note styling: code block === */
#page-content pre, #entity-freetext pre, #dp-editable pre, #board-note-editable pre {
  border-radius: var(--page-code-block-radius, 4px);
  border: var(--page-code-block-border-width, 1px) solid var(--page-code-block-border, var(--border));
}

/* === Note styling: list markers === */
#page-content ul, #entity-freetext ul, #dp-editable ul, #board-note-editable ul {
  list-style-type: disc;
}
#page-content ul ul, #entity-freetext ul ul, #dp-editable ul ul, #board-note-editable ul ul {
  list-style-type: circle;
}

/* === Note styling: kbd (keyboard shortcut) === */

#page-content kbd,
#entity-freetext kbd,
#dp-editable kbd,
#board-note-editable kbd {
  display: inline-block;
  padding: 2px 6px;
  font-size: var(--page-kbd-font-size, 0.85em);
  font-family: var(--page-kbd-font, inherit);
  font-weight: var(--page-kbd-bold, normal);
  font-style: var(--page-kbd-italic, normal);
  color: var(--page-kbd-fg, var(--fg));
  background: var(--page-kbd-bg, var(--bg3));
  border: var(--page-kbd-border-width, 1px) solid var(--page-kbd-border, var(--border));
  border-block-end-width: var(--page-kbd-border-bottom-width, 2px);
  border-radius: var(--page-kbd-radius, 4px);
  box-shadow: 0 1px 0 var(--page-kbd-shadow, var(--border));
  vertical-align: middle;
  line-height: 1.4;
}

/* === Note styling: details/summary (collapsible) === */
#page-content details,
#entity-freetext details,
#dp-editable details,
#board-note-editable details {
  margin-block: 8px;
  border: var(--page-details-border-width, 1px) solid var(--page-details-border, var(--border));
  border-radius: var(--page-details-radius, 4px);
  overflow: hidden;
  background: var(--page-details-bg, transparent);
}
#page-content details summary,
#entity-freetext details summary,
#dp-editable details summary,
#board-note-editable details summary {
  padding: 8px 12px;
  background: var(--page-details-summary-bg, var(--bg2));
  color: var(--page-details-summary-fg, var(--fg));
  font-size: var(--page-details-summary-font-size, inherit);
  font-family: var(--page-details-summary-font, inherit);
  cursor: pointer;
  font-weight: var(--page-details-summary-bold, bold);
  font-style: var(--page-details-summary-italic, normal);
  user-select: none;
}
#page-content details summary:hover,
#entity-freetext details summary:hover,
#dp-editable details summary:hover,
#board-note-editable details summary:hover {
  background: var(--page-details-summary-hover-bg, var(--bg3));
  color: var(--page-details-summary-hover-fg, var(--page-details-summary-fg, var(--fg)));
}
#page-content details[open] summary,
#entity-freetext details[open] summary,
#dp-editable details[open] summary,
#board-note-editable details[open] summary {
  border-block-end: var(--page-details-open-border-width, 1px) solid var(--page-details-open-border, var(--page-details-border, var(--border)));
}
#page-content details > :not(summary),
#entity-freetext details > :not(summary),
#dp-editable details > :not(summary),
#board-note-editable details > :not(summary) {
  padding: 8px 12px;
}

/* === Note styling: heading icon === */
#page-content .heading-icon,
#entity-freetext .heading-icon,
#dp-editable .heading-icon,
#board-note-editable .heading-icon {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  margin-right: 4px;
  color: var(--page-heading-icon-fg, var(--accent));
  font-size: var(--page-heading-icon-font-size, inherit);
  font-family: var(--page-heading-icon-font, inherit);
  font-weight: var(--page-heading-icon-bold, normal);
  font-style: var(--page-heading-icon-italic, normal);
  opacity: var(--page-heading-icon-opacity, 0.8);
}

/* === Note styling: title heading block === */
#page-content .note-title,
#entity-freetext .note-title,
#dp-editable .note-title,
#board-note-editable .note-title {
  font-size: var(--page-title-font-size, 28px);
  font-weight: var(--page-title-bold, bold);
  font-style: var(--page-title-italic, normal);
  font-family: var(--page-title-font, inherit);
  color: var(--page-title-fg);
  background: var(--page-title-bg, transparent);
  -webkit-text-stroke-color: var(--page-title-stroke-color, transparent);
  -webkit-text-stroke-width: var(--page-title-stroke-width, 0px);
  paint-order: stroke fill;
  box-shadow: calc(-1 * var(--page-title-left-accent, 0px)) 0 0 0 var(--page-title-accent-color, var(--page-title-fg));
  border-bottom: var(--page-title-underline, 0px) solid var(--page-title-accent-color, currentColor);
  padding-left: var(--page-title-left-accent, 0px);
  margin: 16px 0 8px;
}

/* === Note styling: toolbar file name edit ===
   ツールバー上のファイル名欄は UI 部品として扱い、本文の「タイトル」書式は適用しない。 */
#page-rt-toolbar #page-title {
  color: inherit;
  font-family: inherit;
  font-weight: inherit;
  font-style: normal;
  font-size: var(--ui-font-12);
  background: transparent;
  -webkit-text-stroke-color: var(--page-title-stroke-color, transparent);
  -webkit-text-stroke-width: 0;
  paint-order: stroke fill;
  box-shadow: none;
  border-bottom: 0;
  padding-left: var(--ui-space-3);
  line-height: 1.2;
  display: flex;
  align-items: center;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#page-rt-toolbar #page-title:empty::before {
  content: attr(data-placeholder);
  color: var(--ui-fg-muted);
}
/* 貼り付け等で混入したインライン書式（太字・斜体・フォント・文字色・背景色）を無効化し、
   常にツールバー標準フォントで表示する。 */
#page-rt-toolbar #page-title * {
  font: inherit !important;
  color: inherit !important;
  background: none !important;
}

/* === Note styling: block drag handle ===
   工程7: gb-note-block-reorder.js が全編集ホスト（メイン/エンティティ自由記述/
   詳細パネル内ノート）で同じクラス名を使うため、3ホストすべてを対象にする
   （旧実装は #page-content 専用で他2ホストにスタイルが当たらなかった）。 */
#page-content .dragging, #entity-freetext .dragging, #dp-editable .dragging {
  opacity: var(--page-dragging-opacity, 0.4);
}
#page-content .drag-guide-top, #entity-freetext .drag-guide-top, #dp-editable .drag-guide-top {
  border-block-start: var(--page-drag-guide-width, 2px) solid var(--page-drag-guide-color, var(--accent)) !important;
}
#page-content .drag-guide-bottom, #entity-freetext .drag-guide-bottom, #dp-editable .drag-guide-bottom {
  border-block-end: var(--page-drag-guide-width, 2px) solid var(--page-drag-guide-color, var(--accent)) !important;
}
/* 工程7-1: pointerdown直後〜pointerup/cancelまで対象ブロック全体を「捕捉中」として
   マークする状態クラス。
   計画書2026-08-04版§2.3で、対象行の実際のハイライト表示は #note-logical-row-highlight
   （gb-note-logical-rows.js の矩形オーバーレイ。子リストを含まない行自身の矩形に
   正確に追従する）へ一本化した。本クラス自体は gb-note-block-reorder.js /
   gb-note-block-context-menu.js が状態フラグとして引き続き付け外しし、既存E2E契約
   （targeted-note-micro-handle-drag-persists-order 等）もこのクラスの有無で検証する
   ため残しているが、旧来のCSSアウトラインは二重表示（新オーバーレイと重なって表示
   される）を避けるため描画しない（クラスは残す・見た目だけ無効化する）。 */
#page-content .note-block-reorder-armed, #entity-freetext .note-block-reorder-armed, #dp-editable .note-block-reorder-armed {
  outline: none;
}
/* 工程7-7: 先頭/末尾でこれ以上移動できない状態を視覚的に示す（ハンドルの小さな
   横揺れ）。prefers-reduced-motion では無効化する。 */
#block-drag-handle.note-block-reorder-boundary { animation: note-block-reorder-shake 0.3s ease-in-out; }
@keyframes note-block-reorder-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-2px); }
  75% { transform: translateX(2px); }
}
/* 縦書きでは行が横に並ぶので、揺れる向きも縦にする（横書きの鏡映し）。 */
#block-drag-handle.is-note-vertical.note-block-reorder-boundary { animation: note-block-reorder-shake-vertical 0.3s ease-in-out; }
@keyframes note-block-reorder-shake-vertical {
  0%, 100% { transform: translateY(0); }
  25% { transform: translateY(-2px); }
  75% { transform: translateY(2px); }
}
/* 行ハンドルのグリップ記号は2列×3行の点なので、縦書き（行が横に並ぶ）では90度回す。
   ホスト側の transform は上の揺れアニメーションが使うため、内側の span を回す。 */
#block-drag-handle .block-drag-handle-glyph,
#table-row-drag-handle .block-drag-handle-glyph { display: block; line-height: 1; }
#block-drag-handle.is-note-vertical .block-drag-handle-glyph,
#table-row-drag-handle.is-note-vertical .block-drag-handle-glyph { transform: rotate(90deg); }
@media (prefers-reduced-motion: reduce) {
  #block-drag-handle.note-block-reorder-boundary,
  #block-drag-handle.is-note-vertical.note-block-reorder-boundary { animation: none; }
}

/* === Note styling: heading indent sections === */
.heading-section {
  margin-inline-start: 4px;
  padding-inline-start: 16px;
}
.heading-section.level-5,
.heading-section.level-6 { padding-inline-start: 12px; }
/* 見出し自体はセクションのインデントから引き戻し、段落のみ深くする。#page-content h2等にpadding-leftがあるため、ID付きで上書きする */
#page-content .heading-section > h1,
#page-content .heading-section > h2,
#page-content .heading-section > h3,
#page-content .heading-section > h4,
#entity-freetext .heading-section > h1,
#entity-freetext .heading-section > h2,
#entity-freetext .heading-section > h3,
#entity-freetext .heading-section > h4 {
  margin-inline-start: -12px;
  padding-inline-start: 4px;
}
#page-content .heading-section > h5,
#page-content .heading-section > h6,
#entity-freetext .heading-section > h5,
#entity-freetext .heading-section > h6 {
  margin-inline-start: -8px;
  padding-inline-start: 4px;
}


/* gb-tools.part04.css: split stylesheet loader */
/* Note styling: slash command menu
   旧 #slash-menu 専用スタイルは gb-note-block-menu.css の .note-block-menu へ
   統合済み（note-editor-regression-performance-conflict-plan-2026-08-01.md 工程5）。 */

/* ============================================================
   共通ドロップダウン
   ============================================================ */
.gb-select {
  font-size: 12px;
  padding: 2px 6px;
  background: var(--bg3);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 3px;
  cursor: pointer;
  outline: none;
}
.gb-select:hover { background: var(--bg4); }
.gb-select:focus { border-color: var(--accent); }
.gb-select-sm { font-size: 11px; padding: 1px 4px; }

/* ============================================================
   共通コンテキストメニュー
   ============================================================ */
.gb-context-menu {
  position: fixed;
  z-index: 200;
  /* ポップアップ視認性向上: 背景は --ui-popup-bg（テーマで変更可）、未定義時は --ui-bg-control (bg3) にフォールバック。
     border を --ui-border-strong で強化、外側に強い影 + 内側に薄い白ハイライトを重ねて
     ダークテーマでも境界が明瞭に見えるようにする */
  background: var(--ui-popup-bg, var(--ui-bg-control));
  border: 1px solid var(--ui-popup-border, var(--ui-border-strong));
  border-radius: var(--ui-radius-md);
  padding: var(--ui-space-2) 0;
  min-width: 160px;
  box-shadow: var(--ui-shadow-lg), inset 0 1px 0 rgba(255,255,255,0.05);
  font-size: var(--ui-font-13);
}
/* 詳細度を上げて gb-tools.css:1081 の `.gb-context-menu > div { padding: 4px 12px }` に勝つ。
   そうしないと padding が上書きされ、sep は 1px + padding で太い横線になり、item も意図外の padding になる。*/
.gb-context-menu > .gb-context-menu-item,
.gb-context-menu-item {
  padding: 5px 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--ui-space-4);
  color: var(--ui-fg-default);
  letter-spacing: 0px;
  word-spacing: 0px;
  white-space: nowrap;
}
/* 詳細度は (0,1,1) に抑えること。`.gb-context-menu > button.gb-context-menu-item` (0,2,1) にすると
   :hover / :focus-visible (0,2,0) の background に勝ってしまい、ホバーハイライトが消える。 */
button.gb-context-menu-item {
  width: 100%;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: left;
  -webkit-appearance: none;
  appearance: none;
}
/* 背景が bg3 に上がったので、hover は控えめの accent 混色に寄せてコントラストを確保 */
.gb-context-menu-item:hover { background: var(--ui-bg-control-active); }
.gb-context-menu-item:focus-visible {
  outline: 2px solid var(--ui-accent);
  outline-offset: -2px;
  background: var(--ui-bg-control-hover);
}
.gb-context-menu-item.disabled { opacity: 0.55; pointer-events: none; color: var(--ui-fg-muted); }
.gb-context-menu-label {
  padding: 4px 14px;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  cursor: default;
  user-select: none;
  white-space: nowrap;
}
