.meldex-note-embed-title { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.meldex-note-embed[data-embed-header="hidden"] .meldex-note-embed-header { display:none; }
.meldex-note-embed-body { position:relative; height:var(--meldex-embed-height, 420px); max-width:100%; overflow:auto; overscroll-behavior:contain; }
.meldex-note-embed[data-board-interaction-active="true"] .meldex-note-embed-body { touch-action:pan-x pan-y; }
.meldex-note-embed:not([data-board-interaction-active="true"]) .meldex-note-embed-body { touch-action:pan-y; }
