.note-heading-toolbar-menu [data-type-id="h4"] .note-heading-toolbar-sample {
  font-size: var(--page-h4-font-size, 16px);
  font-weight: var(--page-h4-bold, normal);
  font-style: var(--page-h4-italic, normal);
