  font-weight: var(--page-h5-bold, normal);
  font-style: var(--page-h5-italic, normal);
  font-family: var(--page-h5-font, inherit);
  color: var(--page-h5-fg);
  background: var(--page-h5-bg, transparent);
}
.note-heading-toolbar-menu [data-type-id="h6"] .note-heading-toolbar-sample {
  font-size: var(--page-h6-font-size, 13px);
  font-weight: var(--page-h6-bold, normal);
  font-style: var(--page-h6-italic, normal);
  font-family: var(--page-h6-font, inherit);
  color: var(--page-h6-fg);
  background: var(--page-h6-bg, transparent);
}
/* 本文は編集ホスト本体（gb-tools.part02.part01.css の #page-content 等）と同じ
   --page-text-* を参照する。ファイル単位の太字・斜体・フォント・背景も見本へ
   反映し、文字色だけが合っている不完全な見本にしない。 */
.note-heading-toolbar-menu [data-type-id="body"] .note-heading-toolbar-sample {
  font-size: var(--page-text-font-size, var(--ui-font-13, 13px));
  font-weight: var(--page-text-bold, normal);
  font-style: var(--page-text-italic, normal);
  font-family: var(--page-text-font, inherit);
  color: var(--page-text-fg, var(--page-fg, var(--fg)));
  background: var(--page-text-bg, var(--content-bg, var(--page-bg, var(--bg))));
}

@media (prefers-reduced-motion: reduce) {
  .note-heading-toolbar-btn,
  .note-heading-toolbar-menu .note-heading-toolbar-sample {
    transition: none !important;
    animation: none !important;
  }
}

.note-status-filter-popup{position:fixed;z-index:100050;min-width:220px;max-height:min(70vh,520px);overflow:auto;padding:6px}
.note-status-filter-popup-title,.note-status-filter-section-title{padding:6px 9px;font-size:11px;font-weight:700;color:var(--fg2);letter-spacing:.04em}
.note-status-filter-row{display:flex;width:100%;align-items:center;gap:9px;padding:7px 9px;border:0;border-radius:5px;background:transparent;color:var(--fg);text-align:left;cursor:pointer}
.note-status-filter-row:hover,.note-status-filter-row[aria-checked="true"]{background:var(--bg4)}
.note-status-filter-check{display:flex;align-items:center;gap:8px;padding:6px 9px;cursor:pointer;color:var(--fg);font-size:12px}
.note-status-dot{width:9px;height:9px;border-radius:50%;background:var(--fg3)}
.note-status-dot[data-status="todo"],[data-note-status="todo"]::after{--note-status-color:#7b8794}
.note-status-dot[data-status="doing"],[data-note-status="doing"]::after{--note-status-color:#2f80ed}
.note-status-dot[data-status="done"],[data-note-status="done"]::after{--note-status-color:#27ae60}
.note-status-dot[data-status="hold"],[data-note-status="hold"]::after{--note-status-color:#f2994a}
.note-status-dot:not([data-status="unset"]){background:var(--note-status-color)}
#page-content .note-status-block{position:relative}
#page-content .note-status-block::after{content:attr(data-note-status-label);float:right;margin-inline-start:8px;padding:1px 6px;border:1px solid var(--note-status-color,var(--border));border-radius:999px;color:var(--note-status-color,var(--fg2));font-size:10px;line-height:1.5;pointer-events:none}
#page-content [data-note-status="todo"]::after{content:"未着手"}
#page-content [data-note-status="doing"]::after{content:"進行中"}
#page-content [data-note-status="done"]::after{content:"完了"}
#page-content [data-note-status="hold"]::after{content:"保留"}
#page-content .note-filter-hidden{display:none!important}
#page-note-filter-btn.active{color:var(--accent);background:color-mix(in srgb,var(--accent) 15%,transparent)}

/* Schedule production task workspace */
.gb-cal-toolbar-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  align-items: center;
  gap: var(--ui-space-3);
  margin-left: auto;
}

.gb-cal-toolbar-actions > .sep {
  width: 1px;
  height: 18px;
  margin: 0 var(--ui-space-1);
  flex: 0 0 auto;
  background: var(--cal-grid-line, var(--ui-border, var(--border)));
}

.gb-cal-surface-switch {
  display: flex;
  align-items: center;
  align-content: center;
  flex: 1 0 420px;
  flex-wrap: nowrap;
  min-width: min(240px, 100%);
  max-width: 100%;
  gap: 0;
  padding: 0;
  border: 0;
  border-bottom: 1px solid var(--cal-control-border, var(--ui-border, var(--border)));
  border-radius: 0;
  background: transparent;
  overflow: visible;
}

/* 中央3面と右操作群はそれぞれ分割しない。幅不足時は共通ツールバー自身が
   グループ境界で折り返し、各グループを次段へ送る。 */
.gb-toolbar-cal > .gb-cal-surface-switch,
.gb-toolbar-cal > .gb-cal-toolbar-actions {
  white-space: nowrap;
}

.gb-cal-root[data-cal-surface="productionTasks"] .gb-toolbar-cal {
  flex-wrap: wrap;
}

body:where([data-cloud-mode="dropbox"], [data-mobile-ui-local="1"])[data-cloud-mobile-editing-ui="1"]
  .gb-cal-root[data-cal-surface="productionTasks"] .gb-toolbar-cal {
  display: none !important;
}

.gb-cal-root[data-cal-surface="productionTasks"] [data-cal-action="template"] {
  display: none !important;
}

.gb-cal-surface-btn {
  flex: 1 1 0;
  min-width: 0;
  padding-inline: var(--ui-space-2);
}

.gb-cal-surface-btn .gb-inner-tab-label {
  min-width: 0;
  text-overflow: ellipsis;
}

/* 制作面ではカレンダー用ナビ（今日/前後/表示切替）が非表示になり、タブ列の右隣が
   直接ツールバー右端ボタン群になる。既定の .tb-spacer (flex:1) を伸ばしたままだと
   余白がタブ列とスペーサーで折半され、タブ折り返し時にタブ領域と右寄せボタン群の
   間へ大きな隙間が生まれるため、制作面ではスペーサーを畳み、タブ列へ余白を全部渡す
   （タブが1行に収まりやすくなり、隙間は最小化される）。カレンダー面はタイトル中央
   寄せの配置が変わらないよう従来のままにする。 */
.gb-cal-root[data-cal-surface="productionTasks"] .gb-toolbar-cal > .tb-spacer {
  flex: 0 0 0;
  min-width: 0;
}

.gb-cal-surface-btn:hover {
  background: var(--cal-cell-hover-bg, var(--ui-hover-bg, var(--bg3)));
  color: var(--cal-fg, var(--fg));
}

.gb-toolbar-cal .gb-cal-surface-btn.gb-inner-tab-active,
.gb-toolbar-cal .gb-cal-surface-btn.gb-inner-tab-active:hover {
  background: color-mix(in srgb, var(--cal-accent, var(--accent)) 14%, transparent);
  color: var(--cal-accent, var(--accent));
  border-bottom-color: var(--cal-accent, var(--accent));
}

.gb-cal-surface-btn:focus-visible,
.gb-production-task-workspace button:focus-visible,
.gb-production-task-workspace input:focus-visible,
.gb-production-task-workspace select:focus-visible,
.gb-production-sidebar button:focus-visible,
.gb-production-sidebar input:focus-visible,
.gb-production-sidebar select:focus-visible,
.gb-production-sidebar textarea:focus-visible {
  outline: 2px solid var(--cal-accent, var(--accent));
  outline-offset: 1px;
}

.gb-cal-root[data-cal-surface="productionTasks"] .gb-cal-calendar-control,
.gb-cal-root[data-cal-surface="productionTasks"] .gb-cal-sidebar,
.gb-cal-root[data-cal-surface="productionTasks"] .gb-cal-sidebar-resize,
.gb-cal-root[data-cal-surface="productionTasks"] .gb-cal-right-panel {
  display: none !important;
}

.gb-cal-root:not([data-cal-surface="productionTasks"]) .gb-cal-production-control {
  display: none !important;
}

.gb-cal-root[data-cal-surface="productionTasks"].gb-cal-sidebar-only .gb-cal-content,
.gb-cal-root[data-cal-surface="productionTasks"] .gb-cal-content {
  display: flex !important;
  padding: 0;
  overflow: hidden;
}

.gb-production-task-view,
.gb-production-task-workspace {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--cal-content-bg, var(--content-bg, var(--bg)));
  color: var(--cal-fg, var(--fg));
}

/* --- リスト切替バー (作品ごとのタスクリスト + 管理リスト) --- */
.gb-production-list-switch {
  flex: 0 0 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 4px;
  padding: 6px 10px;
  border-bottom: 1px solid var(--cal-grid-line, var(--border));
  background: var(--cal-toolbar-bg, var(--bg2));
  overflow-x: auto;
}

.gb-production-list-switch[hidden] { display: none; }

.gb-production-list-switch-btn {
  flex: 0 0 auto;
  min-height: 28px;
  padding: 4px 10px;
  border: 1px solid var(--cal-control-border, var(--border));
  border-radius: 999px;
  background: var(--cal-control-bg, var(--bg));
  color: var(--cal-muted-fg, var(--fg2));
  font-size: 11px;
  white-space: nowrap;
  cursor: pointer;
}

.gb-production-list-switch-btn:hover {
  border-color: var(--cal-accent, var(--accent));
  color: var(--cal-fg, var(--fg));
}

.gb-production-list-switch-btn.is-active {
  border-color: var(--cal-accent, var(--accent));
  background: var(--cal-accent, var(--accent));
  color: var(--cal-accent-fg, #fff);
  font-weight: 600;
}

.gb-production-list-switch-add {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

.gb-production-list-switch-add-btn {
  min-width: 28px;
  padding: 4px 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.gb-production-list-switch-add-form {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.gb-production-list-switch-add-form input {
  height: 28px;
  min-width: 160px;
  padding: 3px 8px;
  border: 1px solid var(--cal-accent, var(--accent));
  border-radius: 5px;
  background: var(--cal-control-bg, var(--bg));
  color: var(--cal-control-fg, var(--fg));
  font: inherit;
  font-size: 11px;
}

.gb-production-list-switch-add-confirm,
.gb-production-list-switch-add-cancel {
  min-width: 26px;
  min-height: 26px;
  padding: 0;
  border: 1px solid var(--cal-control-border, var(--border));
  border-radius: 5px;
  background: var(--cal-control-bg, var(--bg3));
  color: var(--cal-control-fg, var(--fg));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.gb-production-list-switch-add-confirm {
  border-color: var(--cal-accent, var(--accent));
  color: var(--cal-accent, var(--accent));
}

.gb-production-list-switch-loading,
.gb-production-list-switch-error {
  color: var(--cal-muted-fg, var(--fg2));
  font-size: 11px;
}

.gb-production-list-switch-error {
  color: var(--red, #e06c75);
}

.gb-production-write-availability {
  flex: 0 0 auto;
  margin: 8px 10px 0;
  padding: 8px 10px;
  border-left: 3px solid var(--yellow, #d7b35b);
  background: color-mix(in srgb, var(--yellow, #d7b35b) 10%, var(--cal-content-bg, var(--bg)));
  color: var(--cal-fg, var(--fg));
  font-size: 12px;
  line-height: 1.5;
}

.gb-production-write-availability[hidden] { display: none; }

.gb-production-task-filter,
.gb-production-sidebar-field,
.gb-production-template-field,
.gb-production-quick-plan-form label,
.gb-production-quick-advanced label {
  display: grid;
  gap: 3px;
  min-width: 108px;
  color: var(--cal-muted-fg, var(--fg2));
  font-size: 10px;
}

.gb-production-sidebar-field input,
.gb-production-sidebar-field select,
.gb-production-sidebar-field textarea,
.gb-production-template-field input,
.gb-production-template-field select,
.gb-production-template-field textarea,
.gb-production-template-placement input,
.gb-production-template-placement select,
.gb-production-quick-plan input,
.gb-production-quick-plan select {
  height: 30px;
  min-width: 0;
  padding: 4px 7px;
  border: 1px solid var(--cal-control-border, var(--border));
  border-radius: 5px;
  background: var(--cal-control-bg, var(--bg));
  color: var(--cal-control-fg, var(--fg));
  font: inherit;
}

.gb-production-sidebar-field textarea,
.gb-production-template-field textarea {
  min-height: 72px;
  resize: vertical;
}

.gb-production-sidebar-actions,
.gb-production-template-card-actions,
.gb-production-dialog-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.gb-production-task-button,
.gb-production-sidebar-button,
.gb-production-template-button,
.gb-production-dialog-actions button {
  min-height: 30px;
  padding: 4px 9px;
  border: 1px solid var(--cal-control-border, var(--border));
  border-radius: 5px;
  background: var(--cal-control-bg, var(--bg3));
  color: var(--cal-control-fg, var(--fg));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 11px;
  white-space: nowrap;
  cursor: pointer;
}

.gb-production-task-button:hover,
.gb-production-sidebar-button:hover,
.gb-production-template-button:hover,
.gb-production-dialog-actions button:hover {
  border-color: var(--cal-accent, var(--accent));
  color: var(--cal-accent, var(--accent));
}

.gb-production-task-button.primary,
.gb-production-sidebar-button.primary,
.gb-production-template-button.primary,
.gb-production-dialog-actions button.primary {
  border-color: var(--cal-accent, var(--accent));
  background: var(--cal-accent, var(--accent));
  color: var(--cal-accent-fg, #fff);
}

.gb-production-task-button:disabled,
.gb-production-sidebar-button:disabled,
.gb-production-template-button:disabled {
  color: var(--ui-disabled-fg, var(--cal-muted-fg, var(--fg2)));
  background: var(--ui-disabled-bg, var(--cal-control-bg, var(--bg)));
  border-color: transparent;
  opacity: 1;
  cursor: wait;
}

.gb-production-template-button:disabled {
  cursor: not-allowed;
}

[data-production-write-blocked] {
  cursor: not-allowed !important;
}

/* --- 埋め込みシート表の領域 --- */
.gb-production-embed-host {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  overflow: hidden;
}

.gb-production-embed-host .gb-production-sheet-embed {
  flex: 1 1 auto;
}

.gb-production-task-empty-notice {
  padding: 32px 16px;
  color: var(--cal-muted-fg, var(--fg2));
  text-align: center;
}

.is-template-drop-target,
.is-production-template-drop-target {
  box-shadow: inset 0 0 0 2px var(--cal-accent, var(--accent)) !important;
  background: color-mix(in srgb, var(--cal-accent, var(--accent)) 14%, var(--cal-content-bg, var(--bg))) !important;
}

.gb-production-quick-plan {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.gb-production-quick-description,
.gb-production-template-toolbar p,
.gb-production-template-card p,
.gb-production-classification-note {
  margin: 3px 0 0;
  color: var(--cal-muted-fg, var(--fg2));
  font-size: 10px;
  line-height: 1.45;
}

.gb-production-quick-description {
  margin: 0;
  font-size: 12px;
}

.gb-production-quick-plan-form {
  display: grid;
  grid-template-columns: minmax(100px, 140px) minmax(210px, 260px) max-content;
  align-items: end;
  gap: 8px;
  margin-top: 9px;
}

.gb-production-quick-plan-form label,
.gb-production-quick-field-label {
  white-space: nowrap;
}

.gb-production-quick-advanced {
  margin-top: 8px;
  font-size: 11px;
}

.gb-production-quick-advanced summary {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 32px;
  color: var(--cal-muted-fg, var(--fg2));
  cursor: pointer;
  list-style: none;
}

.gb-production-quick-advanced summary::-webkit-details-marker {
  display: none;
}

.gb-production-quick-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 120ms ease;
}

.gb-production-quick-advanced[open] .gb-production-quick-chevron {
  transform: rotate(90deg);
}

.gb-production-quick-advanced:not([open]) > :not(summary) {
  display: none !important;
}

.gb-production-quick-advanced label {
  max-width: 280px;
  margin-top: 8px;
}

.gb-production-assumption-note {
  margin-top: 8px;
  padding: 7px 8px;
  border-left: 3px solid var(--cal-accent, var(--accent));
  background: color-mix(in srgb, var(--cal-accent, var(--accent)) 8%, transparent);
  color: var(--cal-muted-fg, var(--fg2));
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: 10px;
  line-height: 1.5;
}

.gb-production-quick-result:not(:empty) {
  margin-top: 9px;
  padding-top: 9px;
  border-top: 1px solid var(--cal-grid-line, var(--border));
}

.gb-production-quick-summary {
  margin-bottom: 7px;
  font-size: 12px;
  font-weight: 700;
}

.gb-production-assumption-list {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 3px 10px;
  margin: 0 0 8px;
  font-size: 10px;
}

.gb-production-assumption-list dt { color: var(--cal-muted-fg, var(--fg2)); }
.gb-production-assumption-list dd { margin: 0; }
.gb-production-assumption-list dd.is-auto { color: var(--cal-accent, var(--accent)); }

.gb-production-quick-solutions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.gb-production-quick-solutions strong {
  margin-right: 3px;
  font-size: 11px;
}

/* Right production sidebar */
.gb-production-sidebar {
  min-width: 0;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  box-sizing: border-box;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--cal-panel-bg, var(--bg2));
  color: var(--cal-fg, var(--fg));
}

/* 作品ごとのボタンは別シートではなく、同じタスクシートの保存ビューとして表示する。 */
.gb-production-list-switch.db-view-tabs {
  padding: 0 8px;
  gap: 0;
}

.gb-production-list-switch.db-view-tabs .gb-production-list-switch-btn {
  min-height: 32px;
  padding: 5px 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--cal-muted-fg, var(--fg2));
}

.gb-production-list-switch.db-view-tabs .gb-production-list-switch-btn.is-active {
  border-bottom-color: var(--cal-accent, var(--accent));
  background: color-mix(in srgb, var(--cal-accent, var(--accent)) 10%, transparent);
  color: var(--cal-fg, var(--fg));
}

.gb-production-sidebar-entrances {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  padding: 6px;
  border-bottom: 1px solid var(--cal-grid-line, var(--border));
}

.gb-production-sidebar-entrances .gb-production-sidebar-button {
  min-width: 0;
  justify-content: center;
  padding-inline: 6px;
}

.gb-production-sidebar-tabs {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid var(--cal-grid-line, var(--border));
}

.gb-production-sidebar-tab {
  min-width: 0;
  min-height: 36px;
  padding: 5px 4px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--cal-muted-fg, var(--fg2));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  font-size: 10px;
  white-space: nowrap;
  cursor: pointer;
}

.gb-production-sidebar-tab:hover { background: var(--cal-cell-hover-bg, var(--bg3)); color: var(--cal-fg, var(--fg)); }
.gb-production-sidebar-tab.is-active {
  border-bottom-color: var(--cal-accent, var(--accent));
  color: color-mix(in srgb, var(--cal-accent, var(--accent)) 55%, #fff);
}

.gb-production-sidebar-content {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 100%;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 10px;
  box-sizing: border-box;
}

/* 制作設定: 左はテンプレート階層、右は現役シート埋め込み。 */
.gb-production-settings-modal {
  width: min(1120px, calc(100vw - 32px));
  max-width: min(1120px, calc(100vw - 32px));
  height: min(820px, calc(100vh - 32px));
  max-height: calc(100vh - 32px);
}

.gb-production-settings-modal > .gb-modal-body {
  min-height: 0;
  overflow: hidden;
  padding: 0;
}

.gb-production-settings-dialog {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  height: 100%;
  color: var(--cal-fg, var(--fg));
}

.gb-production-settings-state,
.gb-production-settings-write-state,
.gb-production-settings-sheet-state {
  flex: 0 0 auto;
  padding: 7px 10px;
  color: var(--cal-muted-fg, var(--fg2));
  font-size: 12px;
  line-height: 1.4;
}

.gb-production-settings-write-state,
.gb-production-settings-sheet-state {
  border-bottom: 1px solid var(--cal-grid-line, var(--border));
}

.gb-production-settings-state.is-error,
.gb-production-settings-sheet-state.is-error,
.gb-production-settings-write-state.is-blocked {
  color: var(--ui-danger, var(--danger, #dc2626));
}

.gb-production-settings-layout {
  display: grid;
  grid-template-columns: minmax(190px, 260px) minmax(0, 1fr);
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
}

.gb-production-settings-nav {
  min-width: 0;
  min-height: 0;
  overflow: auto;
