     コンテナを問わず全インスタンスへ適用する。 */
  .gb-scheduler-button,
  .gb-scheduler-modal .gb-scheduler-scope-item,
  .gb-scheduler-field input,
  .gb-scheduler-field select,
  .gb-scheduler-advanced summary,
  .gb-scheduler-advanced > .gb-check { min-height: 44px; }
  .gb-scheduler-allocation-form { min-width: 0; }
  .gb-scheduler-scope-grid { grid-template-columns: 1fr; }
  .gb-scheduler-scope-grid .gb-scheduler-field:last-child { grid-column: auto; }
  .gb-scheduler-proposal-selector.is-toolbar label { font-size: 0; }
  .gb-scheduler-proposal-selector.is-toolbar select { width: min(34vw, 150px); min-height: 44px; font-size: 12px; }
  .gb-scheduler-proposal-actions { grid-template-columns: 1fr; }
  .gb-scheduler-capability-grid { grid-template-columns: 1fr; }
