  .gb-scheduler-editor-heading { align-items: stretch; flex-direction: column; }
  .gb-scheduler-inline-actions,
  .gb-scheduler-baseline-controls { display: grid; grid-template-columns: 1fr; }
  .gb-scheduler-placement-card { grid-template-columns: 1fr; min-height: 88px; }
