/* ============================================================
   Phase 1 (緊急実装): Color Swatch
   gb-color-palette.js のJS注入版を v3.9 spec値で上書きする。
   形状: 全て四角統一。サイズ: toolbar 22 / field 20 / inline 18 / detail 24。
   フチ: 1px solid var(--ui-border) で統一。
   ============================================================ */
.gb-color-swatch {
  position: relative;
  display: inline-block;
  padding: 0;
  width: 22px;
  height: 22px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  box-sizing: border-box;
  flex-shrink: 0;
  cursor: pointer;
  appearance: none;
  background-color: var(--ui-bg-app);
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  vertical-align: middle;
}
.gb-color-swatch:hover { border-color: var(--ui-accent); }
.gb-color-swatch:focus-visible {
  outline: 1px solid var(--ui-accent);
  outline-offset: 1px;
}
.gb-color-swatch--toolbar { width: 22px; height: 22px; border-radius: var(--ui-radius-sm); }
.gb-color-swatch--field   { width: 20px; height: 20px; border-radius: var(--ui-radius-sm); }
.gb-color-swatch--inline  { width: 18px; height: 18px; border-radius: var(--ui-radius-sm); }
.gb-color-swatch--detail  { width: 24px; height: 24px; border-radius: var(--ui-radius-sm); }
/* 旧 modifier (--status, --round) は v3 で取り下げだが既存DOMが残っている可能性があるため
   形状崩れを防ぐ目的で四角に正規化する */
.gb-color-swatch--status  { width: 22px; height: 22px; border-radius: var(--ui-radius-sm); }
.gb-color-swatch--round   { border-radius: var(--ui-radius-sm); }
.modal button.gb-color-swatch {
  padding: 0;
}
.modal button.gb-color-swatch--toolbar { width: 22px; height: 22px; min-width: 22px; min-height: 22px; }
.modal button.gb-color-swatch--field   { width: 20px; height: 20px; min-width: 20px; min-height: 20px; }
.modal button.gb-color-swatch--inline  { width: 18px; height: 18px; min-width: 18px; min-height: 18px; }
.modal button.gb-color-swatch--detail  { width: 24px; height: 24px; min-width: 24px; min-height: 24px; }

/* オーバーライドインジケータ */
.gb-color-swatch.is-overridden::after {
  content: '';
  position: absolute;
  top: -2px;
  right: -2px;
  width: 6px;
  height: 6px;
  border-radius: var(--ui-radius-pill);
  background: var(--ui-accent);
  border: 1px solid var(--ui-bg-panel);
  pointer-events: none;
}

/* ============================================================
   Phase 2: Button
   ============================================================ */
.gb-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ui-space-3);
  height: var(--ui-h-md);
  padding: 0 var(--ui-space-5);
  font-size: var(--ui-button-font-size);
  font-weight: var(--ui-button-font-weight);
  font-style: var(--ui-button-font-style);
  font-family: var(--ui-button-font);
  line-height: var(--ui-button-line-height);
  color: var(--ui-button-fg);
  background: var(--ui-button-bg);
  border: var(--ui-button-border-width) solid var(--ui-button-border);
  box-shadow: inset var(--ui-button-left-accent) 0 0 var(--ui-button-accent-color), inset 0 calc(-1 * var(--ui-button-underline)) 0 var(--ui-button-accent-color);
  border-radius: var(--ui-radius-sm);
  cursor: pointer;
  white-space: nowrap;
  user-select: none;
  box-sizing: border-box;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.gb-btn > svg,
.gb-btn > .ico {
  flex: 0 0 auto;
}
.gb-btn:hover {
  color: var(--ui-button-hover-fg);
  background: var(--ui-button-hover-bg);
  border: var(--ui-button-hover-border-width) solid var(--ui-button-hover-border);
  box-shadow: inset var(--ui-button-hover-left-accent) 0 0 var(--ui-button-hover-accent-color), inset 0 calc(-1 * var(--ui-button-hover-underline)) 0 var(--ui-button-hover-accent-color);
  font-style: var(--ui-button-hover-font-style);
  font-weight: var(--ui-button-hover-font-weight);
  font-size: var(--ui-button-hover-font-size);
  font-family: var(--ui-button-hover-font);
  line-height: var(--ui-button-hover-line-height);
}
.gb-btn:active,
.gb-btn.active,
.gb-btn.selected,
.gb-btn[aria-pressed="true"] {
  color: var(--ui-button-active-fg);
  background: var(--ui-button-active-bg);
  border: var(--ui-button-active-border-width) solid var(--ui-button-active-border);
  box-shadow: inset var(--ui-button-active-left-accent) 0 0 var(--ui-button-active-accent-color), inset 0 calc(-1 * var(--ui-button-active-underline)) 0 var(--ui-button-active-accent-color);
  font-style: var(--ui-button-active-font-style);
  font-weight: var(--ui-button-active-font-weight);
  font-size: var(--ui-button-active-font-size);
  font-family: var(--ui-button-active-font);
  line-height: var(--ui-button-active-line-height);
}
.gb-btn:focus-visible {
  outline: none;
  border-color: var(--ui-accent);
  box-shadow: 0 0 0 1px var(--ui-accent);
}
.gb-btn:disabled,
.gb-btn[disabled],
.gb-btn.is-disabled {
  color: var(--ui-disabled-fg) !important;
  background: var(--ui-disabled-bg) !important;
  border-color: transparent !important;
  box-shadow: none !important;
  opacity: 1;
  pointer-events: none;
}

/* サイズ */
.gb-btn-xs {
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-3);
  font-size: var(--ui-font-11);
  border-radius: var(--ui-radius-xs);
  gap: var(--ui-space-2);
}
.gb-btn-sm {
  height: var(--ui-h-sm);
  padding: 0 var(--ui-space-4);
