  cursor: pointer;
  text-align: left;
  user-select: none;
  white-space: nowrap;
  box-sizing: border-box;
}
.gb-inner-tab:hover,
.view-tab:hover,
.settings-theme-preview-sheet-view .db-view-tab:hover {
  color: var(--ui-inner-tab-hover-fg);
  background: var(--ui-inner-tab-hover-bg);
  border: var(--ui-inner-tab-hover-border-width) solid var(--ui-inner-tab-hover-border);
  box-shadow: inset var(--ui-inner-tab-hover-left-accent) 0 0 var(--ui-inner-tab-hover-accent-color), inset 0 calc(-1 * var(--ui-inner-tab-hover-underline)) 0 var(--ui-inner-tab-hover-accent-color);
  font-style: var(--ui-inner-tab-hover-font-style);
  font-weight: var(--ui-inner-tab-hover-font-weight);
  font-size: var(--ui-inner-tab-hover-font-size);
  font-family: var(--ui-inner-tab-hover-font);
  line-height: var(--ui-inner-tab-hover-line-height);
}
.gb-inner-tab.gb-inner-tab-active,
.gb-inner-tab-active,
.view-tab.active,
.settings-theme-preview-sheet-view .db-view-tab.active {
  color: var(--ui-inner-tab-active-fg);
  font-weight: var(--ui-inner-tab-active-font-weight);
  font-style: var(--ui-inner-tab-active-font-style);
  font-family: var(--ui-inner-tab-active-font);
  font-size: var(--ui-inner-tab-active-font-size);
  line-height: var(--ui-inner-tab-active-line-height);
  border: var(--ui-inner-tab-active-border-width) solid var(--ui-inner-tab-active-border);
  box-shadow: inset var(--ui-inner-tab-active-left-accent) 0 0 var(--ui-inner-tab-active-underline), inset 0 calc(-1 * var(--ui-inner-tab-active-underline-width)) 0 var(--ui-inner-tab-active-underline);
  background: var(--ui-inner-tab-active-bg);
}
.gb-inner-tab-icon {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  width: var(--ui-icon-sm);
  height: var(--ui-icon-sm);
}
.gb-inner-tab-label {
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ============================================================
   Phase 2: Section
   ============================================================ */
.gb-section {
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-3);
  margin-top: var(--ui-space-6);
}
.gb-section:first-child { margin-top: 0; }

.gb-section-title {
  font-family: var(--ui-header-font, var(--ui-font, inherit));
  font-size: var(--ui-font-12);
  font-weight: var(--ui-weight-semibold);
  color: var(--ui-header-fg);
  border-left: 2px solid var(--ui-accent);
  padding-left: var(--ui-space-3);
  margin-bottom: var(--ui-space-3);
  line-height: 1.2;
}
.gb-section-desc {
  font-family: var(--ui-muted-font, var(--ui-font, inherit));
  /* --ui-muted-font-size が未設定なら従来どおり --ui-font-11。
     テーマ側で --ui-muted-font-size を指定するとサブテキスト全体のサイズを上書きできる */
  font-size: var(--ui-muted-font-size, var(--ui-font-11));
  font-weight: var(--ui-muted-bold, var(--ui-weight-regular));
  font-style: var(--ui-muted-italic, normal);
  color: var(--ui-fg-muted);
}

/* フィールド用ヘルプアイコン: ラベル横の小さな「?」。長い説明文は基本UIに直接載せず、
   このアイコンのツールチップへ集約する（fieldHelp() が生成）。 */
.gb-field-help {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: -0.15em;
  margin-left: var(--ui-space-1, 4px);
  color: var(--ui-fg-muted);
  opacity: 0.65;
  cursor: help;
  border-radius: 50%;
  line-height: 0;
  flex: none;
}
.gb-field-help:hover {
  color: var(--ui-accent);
  opacity: 1;
}
.gb-field-help:focus-visible {
  color: var(--ui-accent);
  opacity: 1;
  outline: 2px solid var(--ui-accent);
  outline-offset: 1px;
}
.gb-field-help > svg { display: block; }

/* チェックボックス/トグルの右にヘルプアイコンを添える横並びラッパー。
   ラベル内に置くとアイコンのクリックでトグルが誤作動するため、ラベルの外に置く。 */
.gb-check-help-row {
  display: flex;
  align-items: center;
  gap: var(--ui-space-2, 6px);
}
.gb-check-help-row > label { margin-top: 0; margin-bottom: 0; }
.gb-check-help-row > .gb-field-help { margin-left: 0; }
/* セクション内インデント: タイトル以外は 1em インデント */
.gb-section > *:not(.gb-section-title) {
  margin-left: 1em;
}

/* 箱型 modifier (限定用途) */
.gb-section--boxed {
  padding: var(--ui-space-3);
  background: var(--ui-bg-panel);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  gap: var(--ui-space-2);
}
.gb-section--boxed > .gb-section-title {
  border-left: none;
  padding-left: 0;
}
/* インデントは非boxed共通ルール（.gb-section > *:not(.gb-section-title)）に集約済み */

/* 詳細パネル用密度調整 modifier (detail-panel-section-unification-plan.md) */
.gb-section--detail {
  margin-top: var(--ui-space-5);
  gap: var(--ui-space-2);
}
.gb-section--detail:first-child { margin-top: 0; }
.gb-section--detail > .gb-section-title { margin-bottom: var(--ui-space-2); }

/* ============================================================
   Phase 2: Field (4階層レイアウト)
   ============================================================ */
.gb-field {
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-1);
}
.gb-field-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ui-space-2) 1em;  /* 縦 4px / 横 1em */
  min-height: var(--ui-h-xs);
}
.gb-field-inline {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-2);
  font-size: var(--ui-font-11);
  color: var(--ui-fg-muted);
  min-height: var(--ui-h-xs);
}
.gb-field-inline > .gb-label {
  flex-shrink: 0;
  font-size: var(--ui-font-11);
  color: var(--ui-fg-muted);
}
.gb-label {
  font-size: var(--ui-font-12);
  color: var(--ui-fg-muted);
  margin-bottom: var(--ui-space-1);
}

/* 標準入力欄 */
.gb-input,
.gb-textarea {
  display: block;
  width: 100%;
  height: var(--ui-h-md);
  padding: 0 var(--ui-space-3);
  font-size: var(--ui-font-13);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: var(--ui-bg-field, var(--ui-bg-app));
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  outline: none;
  box-sizing: border-box;
  transition: border-color 0.12s;
}
.gb-textarea {
  height: auto;
  min-height: 72px;
  padding: var(--ui-space-2) var(--ui-space-3);
  resize: vertical;
  line-height: 1.4;
}
.gb-textarea-sm {
  min-height: 54px;
  font-size: var(--ui-font-11);
}
.gb-input:focus,
.gb-textarea:focus { border-color: var(--ui-accent); }
.gb-input-sm {
  display: inline-block;
  width: auto;
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-2);
  font-size: var(--ui-font-11);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: var(--ui-bg-field, var(--ui-bg-app));
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  outline: none;
  box-sizing: border-box;
}
.gb-input-sm:focus { border-color: var(--ui-accent); }

/* セレクト
   注意: native <select> 要素なので display は inline-block。inline-flex は推奨外
   (ブラウザによってはオプションリスト表示が不安定になる)。
   align-items 等は native control なので効かない */
.gb-select {
  display: inline-block;
  height: var(--ui-h-md);
  padding: 0 var(--ui-space-8) 0 var(--ui-space-3);
  font-size: var(--ui-font-13);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: var(--ui-bg-control);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  cursor: pointer;
  outline: none;
  box-sizing: border-box;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
}
.gb-select:hover { background: var(--ui-bg-control-hover); }
.gb-select:focus { border-color: var(--ui-accent); }
.gb-select-sm {
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-7) 0 var(--ui-space-2);
  font-size: var(--ui-font-11);
  border-radius: var(--ui-radius-xs);
}


/* gb-ui.part04.css: split stylesheet loader */
/* gb-ui.part04.css: number inputs */

:root {
  --ui-scrollbar-track-bg: var(--bg2);
  --ui-scrollbar-thumb-bg: var(--bg4);
  --ui-scrollbar-thumb-hover-bg: var(--fg2);
  --ui-pane-tabbar-bg: var(--bg2);
  --ui-pane-tab-active-bg: var(--bg);
  --ui-panelset-tabbar-bg: var(--ui-pane-tabbar-bg);
  --ui-collapsed-tabbar-bg: var(--ui-pane-tabbar-bg);
  --ui-dockbar-bg: var(--ui-pane-tabbar-bg);
  --ui-tooltip-bg: var(--ui-popup-bg);
  --ui-tooltip-fg: var(--ui-fg-default);
  --ui-tooltip-border: var(--ui-border);
}

/* 数値入力 */
.gb-num-input {
  width: calc(6ch + 24px);
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-2);
  font-size: var(--ui-font-11);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: var(--ui-bg-app);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  text-align: right;
  outline: none;
  box-sizing: border-box;
}
.gb-num-input:focus { border-color: var(--ui-accent); }
.gb-num-input[type=number] {
  appearance: auto;
  -moz-appearance: number-input;
}
.gb-num-input::-webkit-outer-spin-button,
.gb-num-input::-webkit-inner-spin-button {
  -webkit-appearance: auto;
  opacity: 0;
  margin-left: var(--ui-space-3);
  transition: opacity 0.12s;
}
.gb-num-input:hover::-webkit-outer-spin-button,
.gb-num-input:hover::-webkit-inner-spin-button,
.gb-num-input:focus::-webkit-outer-spin-button,
.gb-num-input:focus::-webkit-inner-spin-button { opacity: 1; }

.gb-num-unit {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-1);
}
.gb-num-unit > .unit {
  font-size: var(--ui-font-10);
  color: var(--ui-fg-muted);
  white-space: nowrap;
}

/* Disabled controls: swatches and checks must lose their source colors. */
.gb-color-swatch:disabled,
.gb-color-swatch[disabled],
.gb-color-swatch[aria-disabled="true"],
.gb-color-swatch.is-disabled,
.gb-swatch:disabled,
.gb-swatch[disabled],
.gb-swatch[aria-disabled="true"],
.gb-swatch.is-disabled,
.gb-fmt-swatch:disabled,
.gb-fmt-swatch[disabled],
.gb-fmt-swatch[aria-disabled="true"],
.gb-fmt-swatch.is-disabled,
.gb-fmt-swatch-bg:disabled,
.gb-fmt-swatch-bg[disabled],
.gb-fmt-swatch-bg[aria-disabled="true"],
.gb-fmt-swatch-bg.is-disabled,
.gb-fmt-swatch-fg:disabled,
.gb-fmt-swatch-fg[disabled],
.gb-fmt-swatch-fg[aria-disabled="true"],
.gb-fmt-swatch-fg.is-disabled {
  background: var(--ui-disabled-bg) !important;
  border-color: transparent !important;
  color: var(--ui-disabled-fg) !important;
  filter: grayscale(1) saturate(0) !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
  pointer-events: none !important;
}

input[type="checkbox"]:disabled,
input[type="checkbox"][aria-disabled="true"],
input[type="radio"]:disabled,
input[type="radio"][aria-disabled="true"] {
  accent-color: var(--ui-disabled-accent) !important;
  filter: grayscale(1) saturate(0) !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
}

label:has(input[type="checkbox"]:disabled),
label:has(input[type="checkbox"][aria-disabled="true"]),
label:has(input[type="radio"]:disabled),
label:has(input[type="radio"][aria-disabled="true"]) {
  color: var(--ui-disabled-fg) !important;
}

button:disabled,
button[disabled],
button[aria-disabled="true"] {
  color: var(--ui-disabled-fg) !important;
  border-color: transparent !important;
  box-shadow: none !important;
  filter: grayscale(1) saturate(0) !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
}

[role="button"][aria-disabled="true"],
[role="button"][data-cloud-disabled="1"],
[data-action][data-cloud-disabled="1"] {
  color: var(--ui-disabled-fg) !important;
  border-color: transparent !important;
  box-shadow: none !important;
  filter: grayscale(1) saturate(0) !important;
  cursor: not-allowed !important;
}

.gb-input:disabled,
.gb-textarea:disabled,
.gb-select:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  color: var(--ui-disabled-fg) !important;
  background: var(--ui-disabled-bg) !important;
  border-color: var(--ui-disabled-border) !important;
  opacity: 1 !important;
  pointer-events: none;
}

.meldex-dropdown-close-row {
  display: flex;
  justify-content: flex-end;
  gap: var(--ui-space-2);
  padding: var(--ui-space-2) var(--ui-space-2) 0;
  margin-top: var(--ui-space-2);
  border-top: 1px solid var(--ui-border);
  cursor: default;
}
.gb-context-menu > .meldex-dropdown-close-row,
.sn2-header-popup > .meldex-dropdown-close-row,
.gb-fmt-popup > .meldex-dropdown-close-row,
.sn2-role-menu > .meldex-dropdown-close-row { padding: var(--ui-space-2) var(--ui-space-2) 0; }
.gb-context-menu > .meldex-dropdown-close-row:hover,
.sn2-header-popup > .meldex-dropdown-close-row:hover,
.gb-fmt-popup > .meldex-dropdown-close-row:hover,
.sn2-role-menu > .meldex-dropdown-close-row:hover { background: transparent; }
.meldex-dropdown-close-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--ui-h-sm);
  height: var(--ui-h-sm);
  padding: 0 var(--ui-space-2);
  color: var(--ui-fg-muted);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--ui-radius-xs);
  cursor: pointer;
}
.meldex-dropdown-close-btn:hover,
.meldex-dropdown-close-btn:focus-visible {
  color: var(--ui-fg-default);
  background: var(--ui-bg-control-hover, rgba(255,255,255,0.08));
  border-color: var(--ui-border);
  outline: none;
}

/* Global tag management tab */
.gb-tag-chip {
  display: inline-flex;
  position: relative;
  align-items: center;
  min-width: 0;
  height: 26px;
  flex: 0 0 auto;
  border: 1px solid var(--ui-border-strong, var(--border));
  border-radius: 999px;
  background: var(--ui-bg-control, var(--bg3));
  color: var(--gb-tag-color, var(--fg));
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  vertical-align: middle;
}
.gb-tag-chip:hover {
  border-color: var(--ui-border-focus, color-mix(in srgb, var(--fg2) 58%, var(--border)));
  background: var(--ui-bg-control-hover, var(--bg2));
}
.gb-tag-chip__label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-width: 0;
  max-width: 150px;
  height: 100%;
  padding: 0 8px;
  overflow: hidden;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  line-height: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}

input[type="number"]:not([data-number-drag="off"]):not(:disabled):not([readonly]) {
  cursor: ew-resize;
  appearance: textfield;
  -moz-appearance: textfield;
}
input[type="number"]:not([data-number-drag="off"]):focus {
  cursor: text;
}
input[type="number"]:not([data-number-drag="off"])::-webkit-inner-spin-button,
input[type="number"]:not([data-number-drag="off"])::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
}
html.gb-number-scrubbing,
html.gb-number-scrubbing * {
  cursor: ew-resize !important;
  user-select: none !important;
}
.gb-tag-chip__scope {
  display: inline-grid;
  width: 18px;
  height: 18px;
  margin-right: 4px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  background: var(--ui-bg-panel, var(--bg2));
  color: var(--ui-fg-muted, var(--fg2));
  font-size: 9px;
  font-weight: 800;
  cursor: help;
}
.gb-tag-chip__scope--duplicate {
  border-style: double;
}
.gb-tag-chip__scope:focus-visible {
  outline: 2px solid var(--ui-border-focus, var(--accent));
  outline-offset: 1px;
}
button.gb-tag-chip__label {
  cursor: pointer;
}
.gb-tag-chip--removable .gb-tag-chip__label {
  padding-right: 31px;
}
.gb-tag-chip__remove {
  display: grid;
  position: absolute;
  inset: 0 0 0 auto;
  width: 27px;
  height: 100%;
  padding: 0;
  place-items: center;
  border: 0;
  border-left: 1px solid transparent;
  border-radius: 0 999px 999px 0;
  background: transparent;
  color: var(--fg2);
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease, color 120ms ease, background-color 120ms ease, border-color 120ms ease;
}
.gb-tag-chip:hover .gb-tag-chip__remove,
.gb-tag-chip:focus-within .gb-tag-chip__remove {
  border-left-color: var(--ui-border-strong, var(--border));
  opacity: 1;
  pointer-events: auto;
}
.gb-tag-chip__remove:hover,
.gb-tag-chip__remove:focus-visible {
  background: color-mix(in srgb, var(--danger) 12%, transparent);
  color: var(--danger);
}
.gb-tag-chip--compact {
  height: 20px;
  font-size: 10px;
}
.gb-tag-chip--compact .gb-tag-chip__label {
  max-width: 102px;
  padding-right: 6px;
  padding-left: 6px;
}
.gb-tag-chip--summary {
  border-style: dashed;
  color: var(--fg2);
  font-weight: 500;
}
.gb-tag-chip--summary .gb-tag-chip__label {
  padding-right: 6px;
  padding-left: 6px;
}
.gb-tag-tree-label--colored {
  color: var(--gb-tag-color, var(--fg)) !important;
}
.gb-tag-tree-label {
  font-size: 12px;
}
.gb-tag-group-actions {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 2px;
}
.gb-tag-tree-row.is-drop-before {
  box-shadow: inset 0 2px 0 var(--accent) !important;
}
.gb-tag-tree-row.is-drop-after {
  box-shadow: inset 0 -2px 0 var(--accent) !important;
}
.gb-tag-tree-row.is-drop-before-h {
  box-shadow: inset 2px 0 0 var(--accent) !important;
}
.gb-tag-tree-row.is-drop-after-h {
  box-shadow: inset -2px 0 0 var(--accent) !important;
}

@media (hover: none) {
  .gb-tag-chip__remove {
    border-left-color: var(--ui-border-strong, var(--border));
    opacity: 1;
    pointer-events: auto;
  }
}

.gb-tag-management-panel {
  box-sizing: border-box;
  /* タグの格子並びの最小列幅。パネル内側の余白8px×2＋グループ入れ物の字下げ18pxを
     差し引いた実効幅で、240px→1列・360px→2列・560px→3列になるよう実測して調整した値。
     PCは約148px（フォント12px・チェックボックス廃止を織り込み）、タッチ環境は操作部品が
     44pxになるため約195pxへ引き上げる（下のmobileルールで上書き）。 */
  --gb-tag-tree-col-min: 148px;
}
.gb-tag-tree-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--gb-tag-tree-col-min, 148px), 1fr));
  gap: 2px;
  align-items: start;
  min-width: 0;
}
.gb-tag-panel-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  width: 100%;
  min-height: 30px;
  flex: 0 0 auto;
}
.gb-tag-panel-tab {
  width: 100%;
  max-width: none;
  justify-content: center;
  min-width: 0;
  gap: 5px;
