/* Support diagnostics dialog and error notice */
/* 共通 createModal controller がviewport内へ実寸を固定するため、旧controller用の760px最小高は
   持たせない。狭い画面では本文だけをスクロールさせ、ヘッダーと操作を画面内に保つ。 */
.meldex-support-dialog {
  width: min(440px, calc(100vw - 32px));
  min-width: min(440px, calc(100vw - 32px));
  max-width: 440px;
  height: min(720px, calc(100vh - 48px));
  min-height: min(520px, calc(100vh - 48px));
  max-height: calc(100vh - 48px);
}
.meldex-support-dialog-title {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-2);
}
.meldex-support-dialog-body {
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-3);
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
  padding-right: 2px;
}
.meldex-support-field {
  gap: var(--ui-space-2);
}
.meldex-support-textarea {
  resize: vertical;
}
.meldex-support-textarea--activity {
  min-height: 118px;
}
.meldex-support-textarea--comment {
  min-height: 132px;
}
.meldex-support-details {
  margin-top: 2px;
}
.meldex-support-details summary {
  min-height: 32px;
  cursor: pointer;
}
.meldex-support-technical {
  white-space: pre-wrap;
  max-height: 220px;
  overflow: auto;
  background: var(--bg);
  border: 1px solid var(--border);
  padding: var(--ui-space-3);
}
.meldex-support-actions {
  margin-top: var(--ui-space-4);
  flex-shrink: 0;
}
.meldex-support-dialog .gb-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 0 var(--ui-space-4);
  line-height: 1;
}
.meldex-error-notice-head {
  display: flex;
  align-items: flex-start;
  gap: var(--ui-space-2);
}
.meldex-error-notice-title {
  min-width: 0;
  flex: 1 1 auto;
  font-weight: 700;
}
.meldex-error-notice-close {
