}
.meldex-error-notice-actions {
  display: flex;
  gap: var(--ui-space-3);
  justify-content: flex-end;
  flex-wrap: wrap;
}
#meldex-error-support-notice[data-compact="1"] .meldex-error-notice-actions .gb-btn {
  flex: 1 1 0;
  min-width: 0;
}

@media (max-width: 430px), (pointer: coarse) {
