/* Chat CLI transcript panel */
.chat-cli-panel {
  min-height: 0;
}
.chat-cli-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ui-space-3);
  padding: var(--ui-space-3) var(--ui-space-4);
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-bg-control);
  flex-shrink: 0;
  min-width: 0;
}
.chat-cli-main-toggle,
.chat-cli-provider-toggle {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  white-space: nowrap;
}
.chat-cli-main-toggle {
  font-size: var(--ui-font-12);
  color: var(--ui-fg-muted);
}
.chat-cli-provider-toggle {
  font-size: var(--ui-font-11);
  color: var(--ui-fg-muted);
}
.chat-cli-ellipsis {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chat-cli-actions {
  display: flex;
  align-items: center;
  gap: var(--ui-space-2);
  flex-wrap: wrap;
}
.chat-cli-action-btn {
  flex-shrink: 0;
}
.chat-cli-provider-settings {
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-2);
  padding: var(--ui-space-3) var(--ui-space-4);
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-bg-panel);
  flex-shrink: 0;
}
.chat-cli-provider-row {
  display: grid;
  grid-template-columns: minmax(92px, auto) minmax(120px, 1fr);
  align-items: center;
  gap: var(--ui-space-3);
  min-width: 0;
}
.chat-cli-watch-path {
  width: 100%;
  min-width: 0;
}
.chat-cli-status {
  min-height: 24px;
  padding: var(--ui-space-2) var(--ui-space-4);
  border-bottom: 1px solid var(--ui-border);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  flex-shrink: 0;
}
.chat-cli-content {
  display: grid;
  grid-template-columns: minmax(140px, 34%) 1fr;
  min-height: 0;
  flex: 1 1 auto;
  overflow: hidden;
}
.chat-cli-session-list {
  border-right: 1px solid var(--ui-border);
  overflow: auto;
}
.chat-cli-session-view {
  overflow: auto;
  padding: var(--ui-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-4);
}
.chat-cli-empty {
  padding: var(--ui-space-6);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-12);
}
.chat-cli-session-row {
  display: block;
  width: 100%;
  min-height: 48px;
  text-align: left;
  padding: var(--ui-space-4);
  border: 0;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-bg-panel);
  color: var(--ui-fg-default);
  cursor: pointer;
  box-sizing: border-box;
}
.chat-cli-session-row:hover {
  background: var(--ui-bg-control-hover);
}
.chat-cli-session-row.is-active {
  background: var(--ui-bg-control);
}
.chat-cli-session-title {
  display: flex;
  align-items: center;
  gap: var(--ui-space-3);
  font-size: var(--ui-font-12);
  font-weight: var(--ui-weight-semibold);
}
.chat-cli-session-path,
.chat-cli-session-meta {
  color: var(--ui-fg-muted);
  margin-top: var(--ui-space-1);
}
.chat-cli-session-path {
  font-size: var(--ui-font-11);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chat-cli-session-meta {
  font-size: 10px;
}
.chat-cli-quote-btn {
  color: var(--ui-fg-muted);
  flex-shrink: 0;
}

@media (max-width: 430px) {
  .chat-cli-toolbar,
  .chat-cli-actions,
  .chat-cli-provider-row {
    align-items: stretch;
    flex-direction: column;
  }
  .chat-cli-provider-row {
    display: flex;
  }
  .chat-cli-main-toggle,
  .chat-cli-provider-toggle,
  .chat-cli-action-btn,
  .chat-cli-watch-path,
  .chat-cli-session-row,
  .chat-cli-quote-btn {
    min-height: 44px;
  }
  .chat-cli-main-toggle,
  .chat-cli-provider-toggle {
    display: flex !important;
    gap: var(--ui-space-3);
    width: 100%;
    box-sizing: border-box;
    font-size: var(--ui-font-13);
  }
  .chat-cli-action-btn,
  .chat-cli-watch-path {
    width: 100%;
    font-size: var(--ui-font-13);
  }
  .chat-cli-content {
    grid-template-columns: minmax(0, 1fr);
  }
  .chat-cli-session-list {
    max-height: 34vh;
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }
  .chat-cli-session-view {
    padding: var(--ui-space-3);
  }
  .chat-cli-session-title {
    font-size: var(--ui-font-13);
  }
  .chat-cli-session-path {
    font-size: var(--ui-font-12);
  }
  .chat-cli-quote-btn {
    min-width: 44px;
  }
}

