/* ============================================================
   ボタン: warn variant (バージョン復元等)
   ============================================================ */
.gb-btn-warn {
  background: transparent;
  border-color: var(--ui-border);
  color: var(--orange, #d79a52);
}
.gb-btn-warn:hover { background: color-mix(in srgb, var(--orange, #d79a52) 14%, transparent); }

/* ============================================================
   バージョン履歴・操作履歴 (gb-history.js)
   ============================================================ */
.gb-history-list {
  border: 1px solid var(--gb-history-border, var(--ui-border));
  border-radius: var(--ui-radius-sm);
  max-height: 400px;
  overflow-y: auto;
