  text-overflow: ellipsis;
}
.gb-history-size {
  font-size: var(--ui-font-11);
  color: var(--gb-history-muted-fg, var(--ui-fg-muted));
  flex-shrink: 0;
}
.gb-history-actions {
  display: flex;
  gap: 3px;
  flex-shrink: 0;
}
.gb-history-panel {
  padding: var(--ui-space-4);
  overflow-y: auto;
  height: 100%;
  box-sizing: border-box;
  background: var(--gb-history-bg, var(--ui-bg-app));
  color: var(--gb-history-fg, var(--ui-fg-default));
}
.gb-history-panel-header {
  display: flex;
  align-items: center;
  gap: var(--ui-space-4);
  margin-bottom: var(--ui-space-4);
}
.gb-history-panel-title {
  font-size: var(--ui-font-13);
  font-weight: var(--ui-weight-semibold);
  flex: 1 1 auto;
  min-width: 0;
}
.gb-history-panel-path {
  font-size: var(--ui-font-11);
  color: var(--gb-history-muted-fg, var(--ui-fg-muted));
  margin-bottom: var(--ui-space-3);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-history-loading {
  padding: var(--ui-space-5);
  color: var(--gb-history-muted-fg, var(--ui-fg-muted));
  font-size: var(--ui-font-12);
}
.gb-history-preview {
  font-size: var(--ui-font-13);
