}
.gb-history-table th,
.gb-history-table td {
  border: 1px solid var(--gb-history-border, var(--ui-border));
  padding: 3px var(--ui-space-2);
  text-align: left;
  vertical-align: top;
}
.gb-history-table th {
  background: var(--gb-history-row-bg, var(--ui-bg-control));
  color: var(--gb-history-fg, var(--ui-fg-default));
