}
.gb-diff-col + .gb-diff-col { border-left: 1px solid var(--gb-history-border, var(--ui-border)); }
.gb-diff-col-header {
  padding: var(--ui-space-2) var(--ui-space-4);
  font-size: var(--ui-font-11);
  font-weight: var(--ui-weight-semibold);
  background: var(--gb-history-row-bg, var(--ui-bg-control));
