}
.gb-diff-row-add > td { background: rgba(106, 153, 85, 0.15); }
.gb-diff-row-del > td { background: rgba(244, 71, 71, 0.15); }
.gb-diff-row-mod > td { background: rgba(234, 179, 8, 0.15); }

/* バージョン管理パネル (VersionComponent) */
.gb-version-panel {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  max-height: 100%;
}
.gb-version-section {
  margin-bottom: 12px;
}
.gb-version-section-header {
  font-size: var(--ui-font-13);
  font-weight: bold;
  padding: 6px 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--gb-history-fg, var(--ui-fg-default));
}
.gb-version-section-body {
