}

/* 台本差分ロール表示 */
.gb-sn-diff-role {
  font-weight: bold;
  color: var(--accent);
  margin-right: 4px;
}
.gb-sn-diff-role::after {
  content: '：';
  color: var(--ui-fg-muted);
}

/* 操作履歴パネル (renderHistoryPanel) */
.gb-hp-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ui-space-3);
  margin-bottom: var(--ui-space-4);
  flex-shrink: 0;
}
.gb-hp-entry {
  padding: 3px var(--ui-space-4);
  font-size: var(--ui-font-12);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ui-space-2);
  border-bottom: 1px solid var(--gb-history-border, var(--ui-border));
  background: var(--gb-history-row-bg, transparent);
  color: var(--gb-history-fg, var(--ui-fg-default));
}
.gb-hp-entry:hover { background: var(--gb-history-hover-bg, var(--ui-bg-control-hover)); }
.gb-hp-entry-redo { opacity: 0.4; }
.gb-hp-entry-clickable { cursor: pointer; }
button.gb-hp-entry {
  width: 100%;
  border: 0;
  border-bottom: 1px solid var(--gb-history-border, var(--ui-border));
  border-radius: 0;
  text-align: left;
  font-family: inherit;
}
button.gb-hp-entry:focus-visible { outline: 2px solid var(--ui-accent); outline-offset: -2px; }
button.gb-hp-entry:disabled { opacity: 0.5; cursor: wait; }
.gb-hp-entry-clickable:hover { background: var(--ui-bg-control-hover); }
.gb-hp-entry-disabled { opacity: 0.5; }
.gb-hp-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-hp-time {
  font-size: var(--ui-font-10);
  color: var(--ui-fg-muted);
  flex-shrink: 0;
}
.gb-hp-scope-tag {
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-10);
  background: var(--ui-bg-control-hover);
  padding: 0 3px;
  border-radius: 2px;
}
.gb-hp-current {
  padding: 3px var(--ui-space-4);
  color: var(--ui-accent);
  font-weight: var(--ui-weight-semibold);
  font-size: var(--ui-font-12);
  border-left: 3px solid var(--ui-accent);
  background: var(--ui-bg-panel);
  display: flex;
  align-items: center;
  gap: var(--ui-space-2);
}
.gb-hp-empty {
  padding: var(--ui-space-5);
  color: var(--ui-fg-muted);
  text-align: center;
  font-size: var(--ui-font-12);
}
.gb-hp-empty-hint {
  margin-top: var(--ui-space-3);
  font-size: var(--ui-font-11);
  line-height: 1.5;
}
.gb-hp-title {
  color: var(--ui-fg-default);
  font-weight: var(--ui-weight-semibold);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-hp-detail {
  flex: 0 0 100%;
  min-width: 0;
  margin-top: var(--ui-space-1);
  padding-left: var(--ui-space-1);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  line-height: 1.5;
  overflow-wrap: anywhere;
}

/* 大きめのアバター (48px、設定モーダルのマイプロフィール等) */
.gb-avatar-lg {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--ui-bg-control);
  border: 2px solid var(--ui-border);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  cursor: pointer;
  flex-shrink: 0;
}
.gb-avatar-lg > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.gb-avatar-initial {
  font-size: var(--ui-font-16);
  font-weight: var(--ui-weight-semibold);
  color: var(--ui-fg-muted);
}

/* 単位ラベル文字列専用 (数値でないテキスト) */
.gb-text-input-sm {
  width: calc(6ch + 24px);
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-2);
  font-size: var(--ui-font-11);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: var(--ui-bg-app);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  text-align: center;
  outline: none;
  box-sizing: border-box;
}
.gb-text-input-sm:focus { border-color: var(--ui-accent); }

/* チェックボックス並び */
.gb-check-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ui-space-2) 1em;  /* 縦 4px / 横 1em */
  min-height: var(--ui-h-xs);
}

.gb-check {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-1);
  min-height: 20px;
  font-size: var(--ui-font-11);
  color: var(--ui-fg-muted);
  cursor: pointer;
}

/* カスタムチェックボックス: アプリ全体を白チェックの同一デザインに統一 */
input[type=checkbox],
.modal input[type=checkbox],
.gb-check input[type=checkbox],
input[type=checkbox].gb-checkbox {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  --gb-checkbox-size: var(--gb-checkbox-size-override, 14px);
  --gb-checkbox-check-color: #fff;
  --gb-checkbox-mark-w: max(4px, calc(var(--gb-checkbox-size) * 0.32));
  --gb-checkbox-mark-h: max(8px, calc(var(--gb-checkbox-size) * 0.58));
  --gb-checkbox-mark-stroke: max(2px, calc(var(--gb-checkbox-size) * 0.13));
  width: var(--gb-checkbox-size);
  height: var(--gb-checkbox-size);
  min-width: var(--gb-checkbox-size);
  min-height: var(--gb-checkbox-size);
  margin: 0;
  padding: 0;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  background: var(--ui-bg-app);
  cursor: pointer;
  position: relative;
  display: inline-grid;
  place-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
  vertical-align: middle;
  line-height: 1;
  transition: background 0.12s, border-color 0.12s;
}
input[type=checkbox]:hover,
.modal input[type=checkbox]:hover,
.gb-check input[type=checkbox]:hover,
input[type=checkbox].gb-checkbox:hover {
  border-color: color-mix(in srgb, var(--ui-border) 50%, var(--ui-fg-muted));
}
input[type=checkbox]:checked,
.modal input[type=checkbox]:checked,
.gb-check input[type=checkbox]:checked,
input[type=checkbox].gb-checkbox:checked {
  background: var(--ui-accent);
  border-color: var(--ui-accent);
}
input[type=checkbox]::after,
.modal input[type=checkbox]::after,
.gb-check input[type=checkbox]::after,
input[type=checkbox].gb-checkbox::after {
  content: '';
  width: var(--gb-checkbox-mark-w);
  height: var(--gb-checkbox-mark-h);
  border-right: var(--gb-checkbox-mark-stroke) solid var(--gb-checkbox-check-color);
  border-bottom: var(--gb-checkbox-mark-stroke) solid var(--gb-checkbox-check-color);
  /* L字を 45° 回転させると border の太さ分だけ視覚的重心が右下にズレるので、
     mark-stroke の半分を上方向にオフセットして見た目を box の中心に合わせる。 */
  transform: translateY(calc(var(--gb-checkbox-mark-stroke) * -0.5)) rotate(45deg);
  transform-origin: center;
  box-sizing: border-box;
  opacity: 0;
}
input[type=checkbox]:checked::after,
.modal input[type=checkbox]:checked::after,
.gb-check input[type=checkbox]:checked::after,
input[type=checkbox].gb-checkbox:checked::after {
  opacity: 1;
}
input[type=checkbox]:focus-visible,
.modal input[type=checkbox]:focus-visible,
.gb-check input[type=checkbox]:focus-visible,
input[type=checkbox].gb-checkbox:focus-visible {
  outline: 1px solid var(--ui-accent);
  outline-offset: 1px;
}

/* ============================================================
   Dropboxフォルダ選択 (gb-dropbox-folder-picker.js)
   ============================================================ */
.modal-overlay.meldex-dropbox-folder-picker-overlay {
  /* スタンドアロンのファイルパネル（z-index: 9996）から開いた場合も前面に置く。 */
  z-index: 10010;
}

.meldex-dropbox-folder-picker-modal {
  width: min(620px, calc(100vw - 32px));
  max-height: min(680px, calc(100vh - 32px));
}
.meldex-dropbox-folder-picker-body {
  display: grid;
  grid-template-rows: auto auto minmax(220px, 1fr) auto;
  gap: var(--ui-space-3);
  min-width: 0;
  min-height: 0;
}
.meldex-dropbox-folder-picker-namespace {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--ui-space-2);
}
.meldex-dropbox-folder-picker-namespace[hidden] {
  display: none;
}
.meldex-dropbox-folder-picker-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ui-space-2);
  min-width: 0;
}
.meldex-dropbox-folder-picker-path {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--ui-fg-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.meldex-dropbox-folder-picker-list {
  min-width: 0;
  min-height: 220px;
  overflow: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-bg-app);
}
.meldex-dropbox-folder-picker-status {
  min-height: 18px;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-12);
}
.meldex-dropbox-folder-picker-empty {
  padding: var(--ui-space-4);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-13);
}
.meldex-dropbox-folder-picker-row {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 40px;
  gap: var(--ui-space-2);
  padding: var(--ui-space-3) var(--ui-space-4);
  color: var(--ui-fg-default);
  text-align: left;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--ui-border);
  cursor: pointer;
}
.meldex-dropbox-folder-picker-row:hover,
.meldex-dropbox-folder-picker-row:focus-visible {
  background: var(--ui-bg-control-hover);
}
.meldex-dropbox-folder-picker-badge {
  flex: 0 0 auto;
  margin-left: auto;
  padding: 1px var(--ui-space-3);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  border: 1px solid var(--ui-border);
  border-radius: 999px;
}
.meldex-dropbox-folder-picker-footer {
  gap: var(--ui-space-2);
}
@media (max-width: 640px), (pointer: coarse) {
  .meldex-dropbox-folder-picker-modal {
    width: min(620px, calc(100vw - 16px));
    max-height: calc(100dvh - 16px);
  }
  .meldex-dropbox-folder-picker-body {
    grid-template-rows: auto auto minmax(160px, 1fr) auto;
  }
  .meldex-dropbox-folder-picker-list {
    min-height: 160px;
  }
  .meldex-dropbox-folder-picker-footer {
    display: grid;
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .meldex-dropbox-folder-picker-footer .gb-btn {
    width: 100%;
    min-width: 0;
  }
  .meldex-dropbox-folder-picker-modal[data-dropbox-picker-mode="source"]
    .meldex-dropbox-folder-picker-footer .gb-btn-primary {
    grid-column: 1 / -1;
  }
  .meldex-dropbox-folder-picker-modal[data-dropbox-picker-mode="workspace"]
    .meldex-dropbox-folder-picker-footer {
    grid-template-columns: minmax(0, 1fr);
  }
  .meldex-dropbox-folder-picker-modal .gb-modal-body {
    overflow-x: hidden !important;
  }
  .meldex-dropbox-folder-picker-row,
  .meldex-dropbox-folder-picker-modal .gb-btn {
    min-height: 44px;
  }
}


/* カスタムラジオ (形状のみ円形) */
.gb-check input[type=radio],
input[type=radio].gb-radio {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  margin: 0;
  padding: 0;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-pill);
  background: var(--ui-bg-app);
  cursor: pointer;
  position: relative;
  flex-shrink: 0;
  box-sizing: border-box;
  vertical-align: middle;
}
.gb-check input[type=radio]:checked,
input[type=radio].gb-radio:checked {
  border-color: var(--ui-accent);
}
.gb-check input[type=radio]:checked::after,
input[type=radio].gb-radio:checked::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 6px;
  height: 6px;
  border-radius: var(--ui-radius-pill);
  background: var(--ui-accent);
  transform: translate(-50%, -50%);
}
.gb-check input[type=radio]:focus-visible,
input[type=radio].gb-radio:focus-visible {
  outline: 1px solid var(--ui-accent);
  outline-offset: 1px;
}

/* レンジスライダー (設定ダイアログ等で使用) */
.gb-range {
  flex: 1 1 auto;
  cursor: pointer;
  accent-color: var(--ui-range-fill-bg);
}

/* アクセント色リンク (セクション内の「→」などのリンク) */
.gb-link {
  font-size: var(--ui-font-11);
  color: var(--ui-accent);
  text-decoration: none;
  cursor: pointer;
}
.gb-link:hover { text-decoration: underline; }

/* ============================================================
   Range Slider
   ============================================================ */
input[type="range"] {
  --gb-range-fill-pct: 0%;
  --gb-range-track-height: 4px;
  --gb-range-thumb-size: 14px;
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  accent-color: var(--ui-range-fill-bg);
}

input[type="range"]::-webkit-slider-runnable-track {
  height: var(--gb-range-track-height);
  border-radius: 999px;
  background: linear-gradient(
    to right,
    var(--ui-range-fill-bg) 0%,
    var(--ui-range-fill-bg) var(--gb-range-fill-pct),
    var(--ui-range-track-bg) var(--gb-range-fill-pct),
    var(--ui-range-track-bg) 100%
  );
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: var(--gb-range-thumb-size);
  height: var(--gb-range-thumb-size);
  margin-top: calc((var(--gb-range-track-height) - var(--gb-range-thumb-size)) / 2);
  border: 0;
  border-radius: 999px;
  background: var(--ui-range-fill-bg);
}

input[type="range"]::-moz-range-track {
  height: var(--gb-range-track-height);
  border: 0;
  border-radius: 999px;
  background: var(--ui-range-track-bg);
}

input[type="range"]::-moz-range-progress {
  height: var(--gb-range-track-height);
  border-radius: 999px;
  background: var(--ui-range-fill-bg);
}

input[type="range"]::-moz-range-thumb {
  width: var(--gb-range-thumb-size);
  height: var(--gb-range-thumb-size);
  border: 0;
  border-radius: 999px;
  background: var(--ui-range-fill-bg);
}

/* ============================================================
   Phase 2: Format Button (書式トグル)
   ============================================================ */
.gb-fmt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--ui-h-xs);
  height: var(--ui-h-xs);
  padding: 0;
  font-size: var(--ui-font-11);
  font-family: inherit;
  color: var(--ui-fg-muted);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--ui-radius-xs);
  cursor: pointer;
  flex-shrink: 0;
  box-sizing: border-box;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.gb-fmt-btn:hover {
  background: var(--ui-hover-bg);
  color: var(--ui-hover-fg);
  border-color: var(--ui-border);
}
.gb-fmt-btn.active,
.gb-fmt-btn.is-active {
  background: var(--ui-bg-control-active);
  border-color: var(--ui-accent);
  color: var(--ui-fg-default);
}
.gb-fmt-btn:focus-visible {
  outline: none;
  border-color: var(--ui-accent);
}
.gb-fmt-btn:disabled,
.gb-fmt-btn[disabled] { opacity: 0.45; pointer-events: none; }

/* ============================================================
   Phase 2: Reset Button (オーバーライドリセット)
   ============================================================ */
.gb-reset-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  background: transparent;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  color: var(--ui-fg-muted);
  cursor: pointer;
  flex-shrink: 0;
  font-size: var(--ui-font-11);
  line-height: 1;
  box-sizing: border-box;
}
.gb-reset-btn:hover {
  background: var(--ui-hover-bg);
  color: var(--ui-hover-fg);
}

/* ============================================================
   Phase 2: Inline Actions
   ============================================================ */
.gb-inline-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: var(--ui-space-1);
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* ============================================================
   Phase 2: Style Trigger (選択中スタイル表示ボタン)
   ============================================================ */
.gb-style-trigger {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-3);
  min-height: 56px;
  padding: var(--ui-space-2) var(--ui-space-3);
  background: var(--ui-bg-control);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  cursor: pointer;
  font-family: inherit;
  color: var(--ui-fg-default);
  text-align: left;
  box-sizing: border-box;
}
.gb-style-trigger:hover { border-color: var(--ui-accent); }
.gb-style-trigger-preview {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 140px;
  height: 44px;
  background: var(--ui-bg-app);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  flex-shrink: 0;
}
.gb-card-preview {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 28px;
  font-size: var(--ui-font-13);
  background: var(--ui-bg-panel);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
}
.gb-style-trigger-label {
  display: inline-flex;
  flex-direction: column;
  gap: var(--ui-space-1);
  min-width: 0;
  flex: 1 1 auto;
}
.gb-style-trigger-label > .name {
  font-size: var(--ui-font-12);
  font-weight: var(--ui-weight-semibold);
  color: var(--ui-fg-default);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-style-trigger-label > .meta {
  font-size: var(--ui-font-10);
  color: var(--ui-fg-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-style-trigger > .caret {
  margin-left: auto;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-12);
  flex-shrink: 0;
}

/* ============================================================
   Phase 2: Data Table
   ============================================================ */
.gb-data-table-wrap {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}
.gb-data-table-scroll {
  flex: 1 1 auto;
  overflow: auto;
  min-height: 0;
}
.gb-data-table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--ui-font-12);
  table-layout: fixed;
  color: var(--ui-fg-default);
}
.gb-data-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--ui-header-bg);
  border-bottom: 1px solid var(--ui-border);
  padding: var(--ui-space-2) var(--ui-space-3);
  font-size: var(--ui-font-11);
  font-weight: var(--ui-weight-semibold);
  color: var(--ui-header-fg);
  text-align: left;
}
.gb-data-table tbody td {
  padding: var(--ui-space-1) var(--ui-space-3);
  border-bottom: 1px solid var(--ui-border);
  vertical-align: middle;
}
.gb-data-table tbody tr:hover { background: var(--ui-hover-bg); color: var(--ui-hover-fg); }
.gb-data-table tbody tr.selected,
.gb-data-table tbody tr.is-selected {
  background: var(--ui-selection-bg);
  color: var(--ui-selection-fg);
}
.gb-data-cell-preview {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 60px;
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-2);
  background: var(--ui-bg-app);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  box-sizing: border-box;
}
.gb-data-inline-input {
  width: 100%;
  height: var(--ui-h-xs);
  padding: 0 var(--ui-space-2);
  font-size: var(--ui-font-11);
  font-family: inherit;
  color: var(--ui-fg-default);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--ui-radius-xs);
  outline: none;
  box-sizing: border-box;
}
.gb-data-inline-input:hover,
.gb-data-inline-input:focus {
  background: var(--ui-bg-app);
  border-color: var(--ui-border);
}
.gb-data-inline-input:focus { border-color: var(--ui-accent); }
.gb-data-table-actions {
  display: flex;
  align-items: center;
  gap: var(--ui-space-2);
  min-height: var(--ui-h-sm);
  padding: var(--ui-space-2) var(--ui-space-4);
  background: var(--ui-bg-panel);
  border-top: 1px solid var(--ui-border);
  flex-shrink: 0;
  flex-wrap: wrap;
  box-sizing: border-box;
}
.gb-data-table-actions > .sep {
  width: 1px;
  height: 16px;
  background: var(--ui-border);
  margin: 0 var(--ui-space-1);
}

/* ============================================================
   Phase 2: Modal / Dialog
   ============================================================ */
.gb-modal-overlay {
  position: fixed;
  inset: 0;
  background: var(--ui-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: var(--ui-z-modal);
}
.gb-modal {
  display: flex;
  flex-direction: column;
  background: var(--ui-bg-surface);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-md);
  box-shadow: var(--ui-shadow-lg);
  max-width: 90vw;
  max-height: 90vh;
  min-width: 320px;
  overflow: hidden;
}
.gb-modal-header {
  display: flex;
  align-items: center;
  height: 48px;
  padding: 0 var(--ui-space-6);
  background: var(--ui-header-bg);
  border-bottom: 1px solid var(--ui-border);
  flex-shrink: 0;
  box-sizing: border-box;
}
.gb-modal-title {
  font-size: var(--ui-font-16);
  font-weight: var(--ui-weight-semibold);
  color: var(--ui-header-fg);
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-modal-header .gb-modal-close,
.gb-modal-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
  border: none;
  color: var(--ui-fg-muted);
  cursor: pointer;
  border-radius: var(--ui-radius-xs);
  flex-shrink: 0;
  font-size: 24px;
  font-weight: 400;
  line-height: 1;
}
.gb-modal-close svg {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px;
  min-height: 20px;
  stroke-width: 2.25;
}
.gb-modal-close .ico {
  width: 20px;
  height: 20px;
}
.gb-modal-close:hover {
  background: var(--ui-hover-bg);
  color: var(--ui-hover-fg);
}
.gb-modal-body {
  flex: 1 1 auto;
  min-height: 120px;
  padding: var(--ui-space-6);
  background: var(--ui-bg-surface);
  overflow: auto;
}
.gb-modal-variant-full-bleed > .gb-modal-body,
.gb-modal-variant-full-bleed > .gb-modal-shell-body {
  padding: 0;
}
.gb-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--ui-space-4);
  height: 52px;
  padding: 0 var(--ui-space-6);
  background: var(--ui-bg-panel);
  border-top: 1px solid var(--ui-border);
  flex-shrink: 0;
  box-sizing: border-box;
}
.gb-modal-footer .gb-btn { min-width: 88px; }
.gb-modal-footer .gb-btn-icon { min-width: 0; }
.gb-modal-footer .gb-modal-footer-left {
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: var(--ui-space-4);
}

/* ------------------------------------------------------------
   シンプル確認ダイアログ (cfConfirm / cfAlert / cfPrompt 共通)
   短い問いかけ向けの幅と本文密度を保ち、共通 .gb-modal の
   ヘッダー／本文／フッター構造でも二重余白を作らない。
   ------------------------------------------------------------ */
.gb-confirm {
  background: var(--ui-bg-surface);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-md);
  box-shadow: var(--ui-shadow-lg);
  min-width: 320px;
  max-width: 450px;
  padding: var(--ui-space-6);
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-5);
  box-sizing: border-box;
}
.gb-modal.gb-confirm {
  padding: 0;
  gap: 0;
  overflow: hidden;
}
.gb-modal.gb-confirm > .gb-modal-body {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-5);
  overflow-x: hidden;
  overflow-y: auto;
}
/* 連続するメッセージ (2 行メッセージのタイトル + 本文) は近接配置 */
.gb-confirm-message + .gb-confirm-message { margin-top: calc(-1 * var(--ui-space-3)); }
.gb-confirm-message {
  font-size: var(--ui-font-14);
  line-height: 1.6;
  color: var(--ui-fg-default);
  white-space: pre-wrap;
  word-break: break-word;
}
/* 削除確認ダイアログの被参照警告
   （ファイル参照整合性計画 Phase 4: app/docs/file-reference-integrity-and-backlinks-plan-2026-07-31.md §2.2）
   通常の削除確認と見た目を明確に区別するため、警告色の枠付きボックスにする。
   警告は削除を止めない（cfConfirm自体の確認は従来どおり必要）。 */
.gb-delete-impact-warning {
  border: 1px solid color-mix(in srgb, var(--ui-warning) 45%, var(--ui-border));
  background: color-mix(in srgb, var(--ui-warning) 10%, transparent);
  border-radius: var(--ui-radius-xs);
  padding: var(--ui-space-3) var(--ui-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-1);
  white-space: normal;
}
.gb-delete-impact-warning-headline {
  font-weight: 600;
  color: var(--ui-warning);
  font-size: var(--ui-font-13);
}
.gb-delete-impact-warning-list {
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-13);
  word-break: break-word;
}
.gb-delete-impact-warning-incomplete {
  color: var(--ui-warning);
  font-size: var(--ui-font-13);
}
/* インポート・機能生成ファイル保護計画 Phase 2: 機能保存先の削除警告
   （app/docs/import-and-feature-file-protection-plan-2026-08-12.md §5 Phase 2）。 */
.gb-delete-impact-warning-feature-save-dir {
  font-weight: 600;
  color: var(--ui-warning);
  font-size: var(--ui-font-13);
}
/* 削除影響の照会中プレースホルダー（フェーズB徹底チェック 修正3(b)）。
   まだ警告と確定していないため、警告色ではなく中立色の枠にする。 */
.gb-delete-impact-warning-loading {
  border-color: var(--ui-border);
  background: transparent;
}
.gb-delete-impact-warning-loading-text {
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-13);
}

.gb-confirm-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--ui-space-4);
}
.gb-confirm-actions .gb-btn { min-width: 72px; }
.gb-confirm-input {
  width: 100%;
  padding: var(--ui-space-2) var(--ui-space-4);
  background: var(--ui-bg-app);
  color: var(--ui-fg-default);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-xs);
  font-size: var(--ui-font-14);
  font-family: inherit;
  box-sizing: border-box;
}

@media (max-width: 640px) {
  .gb-confirm {
    width: min(100% - 24px, 450px);
    min-width: 0;
    max-height: calc(100dvh - 24px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
    overflow: auto;
    padding: var(--ui-space-5);
  }
  .gb-modal.gb-confirm {
    padding: 0;
    overflow: hidden;
  }
  .gb-confirm-actions { gap: var(--ui-space-3); }
  .gb-confirm-actions .gb-btn {
    min-width: 96px;
    min-height: 44px;
  }
  .gb-confirm-input { min-height: 44px; }
}

/* ------------------------------------------------------------
   Context Menu / Badge / Empty State / Loading は Phase 2 範囲外
   理由:
   - 仕様書 Phase 2 リストに含まれない (Menu/Badge/Empty/Loading)
   - .gb-context-menu, .gb-context-menu-item, .gb-context-menu-sep は
     gb-tools.css に既存定義があり、100箇所超で使用中
   - .gb-empty-state, .gb-empty-icon は gb-tools.css に既存定義あり、
     gb-app.js / gb-history.js / gb-pane-bridge.js で使用中
   - .gb-spinner / @keyframes gb-spin は gb-tools.css に既存定義あり
   これらは Phase 5 (ダイアログ・メニュー移行) 以降で扱う
   ------------------------------------------------------------ */

/* ============================================================
   ユーティリティ (狭い修飾)
   ============================================================ */
.gb-visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
/* 数値入力欄のスピンボタンは hover/focus 時のみ表示する */
input[type="number"] {
  -moz-appearance: auto !important;
  appearance: auto !important;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: auto !important;
  opacity: 0;
  margin: 0;
  transition: opacity 0.12s ease;
}

input[type="number"]:hover::-webkit-outer-spin-button,
input[type="number"]:hover::-webkit-inner-spin-button,
input[type="number"]:focus::-webkit-outer-spin-button,
input[type="number"]:focus::-webkit-inner-spin-button,
input[type="number"]:focus-visible::-webkit-outer-spin-button,
input[type="number"]:focus-visible::-webkit-inner-spin-button {
  opacity: 1;
}



.dup-monitor-modal {
  width: min(840px, calc(100vw - 32px));
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 32px);
}

.dup-monitor-modal .gb-modal-body {
  overflow: auto;
  scroll-padding-bottom: 72px;
}

.dup-monitor-footer {
  display: contents;
}

.dup-progress {
  display: grid;
  gap: var(--ui-space-2);
  margin-bottom: var(--ui-space-4);
}

.dup-progress-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ui-space-3);
  min-width: 0;
}

/* グリッドの子は既定で min-width:auto のため、長いパスがダイアログ幅を押し広げる。 */
.dup-progress-row [data-dup-status] {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dup-progress-count {
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  white-space: nowrap;
}

/* 確認の対象フォルダ。結果が出たあとも「どこを調べたか」の手がかりとして残す。 */
.dup-progress-target {
  display: flex;
  align-items: center;
  gap: var(--ui-space-2);
  min-width: 0;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
}

.dup-progress-target[hidden] {
  display: none;
}

.dup-progress-target-name {
  color: var(--fg);
  font-weight: var(--ui-weight-medium);
}

.dup-progress-target-name,
.dup-progress-target-parent {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dup-progress-stats {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ui-space-3);
  min-width: 0;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
}

.dup-progress-percent {
  color: var(--fg);
  font-variant-numeric: tabular-nums;
}

.dup-progress-eta {
  white-space: nowrap;
}

.dup-progress-current {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-10);
}

.dup-progress-current[hidden] {
  display: none;
}

.dup-progress progress {
  width: 100%;
  height: 8px;
  accent-color: var(--ui-accent);
}

/* 総数が未確定の間の表示。標準セレクタと ::-webkit- は分けて書く
   （同じルールにまとめると WebKit 以外でルール全体が捨てられる）。 */
.dup-progress progress[data-indeterminate] {
  -webkit-appearance: none;
  appearance: none;
  border: 0;
  border-radius: var(--ui-radius-sm);
  background-color: var(--bg4);
  background-image: linear-gradient(90deg,
    transparent 0%, var(--ui-accent) 45%, var(--ui-accent) 55%, transparent 100%);
  background-size: 44% 100%;
  background-repeat: no-repeat;
  background-position: -44% 0;
  animation: dup-progress-indeterminate 1.4s ease-in-out infinite;
}

.dup-progress progress[data-indeterminate]::-webkit-progress-bar {
  border-radius: var(--ui-radius-sm);
  background-color: var(--bg4);
  background-image: linear-gradient(90deg,
    transparent 0%, var(--ui-accent) 45%, var(--ui-accent) 55%, transparent 100%);
  background-size: 44% 100%;
  background-repeat: no-repeat;
  background-position: -44% 0;
  animation: dup-progress-indeterminate 1.4s ease-in-out infinite;
}

.dup-progress progress[data-indeterminate]::-moz-progress-bar {
  background: transparent;
}

@keyframes dup-progress-indeterminate {
  from { background-position: -44% 0; }
  to { background-position: 144% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .dup-progress progress[data-indeterminate],
  .dup-progress progress[data-indeterminate]::-webkit-progress-bar {
    animation: none;
  }

  .dup-progress progress[data-indeterminate] {
    background-position: 28% 0;
  }
}

.dup-progress-complete progress,
.dup-progress-complete .dup-progress-stats,
.dup-progress-complete .dup-progress-current {
  display: none;
}

.dup-results {
  min-height: 160px;
}

.dup-group-spacer {
  flex: 1 1 auto;
}

.dup-item-location {
  overflow: hidden;
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-10);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dup-item-file-icon {
  color: var(--ui-fg-muted);
}

.dup-image-error {
  padding: var(--ui-space-3);
  color: var(--ui-fg-muted);
  font-size: var(--ui-font-11);
  line-height: 1.4;
  text-align: center;
}

.dup-monitor-modal .dup-item {
  width: 180px;
}

.dup-monitor-modal .dup-item-thumb {
  height: 132px;
}

.dup-monitor-modal .dup-item-thumb > img {
  max-height: 132px;
}

@media (max-width: 640px), (pointer: coarse) {
  .dup-monitor-modal {
    width: calc(100vw - 16px);
    max-width: calc(100vw - 16px);
    max-height: calc(100dvh - 16px);
  }

  .dup-monitor-modal .gb-modal-body {
    -webkit-overflow-scrolling: touch;
  }

  .dup-monitor-modal .dup-group-body {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dup-monitor-modal .dup-item {
    width: auto;
    min-width: 0;
  }

  .dup-monitor-modal .gb-modal-footer .gb-btn {
    min-height: 44px;
  }
}

@media (max-width: 390px) {
  .dup-monitor-modal .dup-group-body {
    grid-template-columns: 1fr;
  }
}

.dup-settings-section {
  display: grid;
  gap: var(--ui-space-3);
}

.dup-settings-field {
