  padding-top: 10px;
}

.llm-review-details summary {
  cursor: pointer;
  color: var(--fg2);
  font-size: 12px;
  user-select: none;
}

.llm-review-results {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.llm-review-summary {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg2);
}

.llm-review-summary-title {
  font-size: 13px;
  font-weight: 700;
  line-height: 1.45;
}

.llm-review-summary-chips,
.llm-review-issue-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.llm-review-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  min-height: 24px;
  padding: 3px 7px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg3);
  color: var(--fg);
  font-size: 11px;
  line-height: 1.3;
}

.llm-review-pill-label {
  color: var(--fg2);
}

.llm-review-bulk-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg2);
}

.llm-review-bulk-label {
  color: var(--fg2);
  font-size: 12px;
  margin-right: 2px;
}

.llm-review-issue {
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 6px;
  background: var(--bg2);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.llm-review-issue[data-severity="high"] {
  border-left-color: var(--danger, #d9534f);
}

.llm-review-issue[data-severity="medium"] {
  border-left-color: var(--warning, #d6a300);
}

.llm-review-issue-title {
  font-size: 13px;
  font-weight: 700;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.llm-review-issue-note {
  display: grid;
  gap: 3px;
  color: var(--fg);
  font-size: 12px;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.llm-review-issue-note-label,
.llm-review-source-title {
  color: var(--fg2);
  font-size: 11px;
  font-weight: 700;
}

.llm-review-source-refs {
  display: grid;
  gap: 4px;
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg);
}

.llm-review-source-ref {
  color: var(--fg2);
  font-size: 11px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.llm-review-issue-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.llm-review-state-btn {
  padding: 4px 8px;
  border: 1px solid var(--border);
  background: var(--bg3);
  color: var(--fg);
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
}

.llm-review-state-btn[data-active="1"] {
  border-color: var(--accent);
  color: var(--accent);
}

.llm-review-status {
  flex: 1 1 180px;
  min-width: 0;
  color: var(--fg2);
  font-size: 12px;
  min-height: 18px;
  overflow-wrap: anywhere;
}

.llm-review-progress-log {
  min-height: 240px;
  max-height: 520px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg2);
  padding: 8px;
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-size: 11px;
  line-height: 1.55;
}

.llm-review-progress-row {
  color: var(--fg2);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  padding: 2px 0;
}

.llm-review-progress-row[data-kind="error"] {
  color: var(--danger, #d9534f);
}

@media (max-width: 760px) {
  .llm-review-modal {
    width: calc(100vw - 16px);
    height: calc(100vh - 16px);
  }

  .llm-review-header,
  .llm-review-footer {
    padding: 10px;
  }

  .llm-review-body {
    grid-template-columns: 1fr;
    padding: 10px;
    gap: 10px;
  }

  .llm-review-input,
  .llm-review-select,
  .llm-review-textarea {
    min-height: 44px;
    font-size: 16px;
  }

  .llm-review-check {
    min-height: 44px;
    align-items: center;
    padding: 6px 0;
  }

  .llm-review-check input {
    width: 18px;
    height: 18px;
    margin-top: 0;
  }

  .llm-review-details summary {
    min-height: 44px;
    display: flex;
    align-items: center;
  }

  .llm-review-footer .gb-btn,
  .llm-review-state-btn {
    min-height: 44px;
  }

  .llm-review-close.gb-btn-icon {
    width: 44px;
    min-width: 44px;
  }
}

/* ==============================
   gb-format-popup.css
   書式設定ポップアップ共通スタイル

   仕様: app/docs/format-popup-ui-unification-plan.md §2-2-A（サイズ統一ルール）
   全インタラクティブ要素の高さを 22px に統一する。
   （2026-04-16 フェーズE-2 完了: 旧 .sn2-* エイリアスは全削除済み）
   ============================== */

.gb-fmt-popup {
  position: fixed;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: var(--ui-space-3);
  padding: var(--ui-space-3);
  background: var(--ui-popup-bg, var(--bg2));
  border: 1px solid var(--ui-popup-border, var(--ui-border-strong, var(--border)));
  border-radius: var(--ui-radius-sm);
  box-shadow: 0 4px 16px rgba(0,0,0,0.3);
  font-size: var(--ui-font-12);
  color: var(--fg);
}

/* モディファイア（フェーズE-2 で sn2-* から移行） */
.gb-fmt-popup--colbulk { min-width: 220px; }
.gb-fmt-popup--bulk-edit {
  z-index: 10000;
  min-width: 280px;
  max-height: 80vh;
  overflow-y: auto;
}
.gb-fmt-popup--role-opts {
  z-index: 10000;
  /* 2026-07-17 ユーザー指示: 幅を従来（min-width 340px）の半分にする。説明文は行内折返しで表示 */
  min-width: 160px;
  max-width: 170px;
  max-height: 80vh;
  overflow-y: auto;
}
.gb-text-selection-fmt {
  z-index: 10060;
}

.gb-fmt-popup-row {
  display: flex;
  align-items: center;
  gap: var(--ui-space-4); /* 8px ペア間 */
}

.gb-fmt-popup-row--specific {
  border-top: 1px solid var(--border);
  padding-top: var(--ui-space-3);
}

/* 選択時書式ポップアップのルビ入力行（シナリオのテキストセル選択時のみ表示）。
   ポップアップ最上段に置き、1行目=ラベル+入力+追加 / 2行目=読み取得+ルール追加 */
.gb-text-selection-fmt .gb-fmt-popup-row--count { flex-wrap: wrap; }
.gb-fmt-popup-row--top { flex-wrap: wrap; }
.gb-text-selection-ruby-row {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--ui-space-2);
  flex: 1 1 100%;
  min-width: 0;
}
.gb-text-selection-ruby-line {
  display: flex;
  align-items: center;
  gap: var(--ui-space-3);
  min-width: 0;
}
.gb-text-selection-ruby-row .gb-text-selection-ruby-input {
  flex: 0 1 140px;
  min-width: 60px;
  width: auto;
}
.gb-text-selection-ruby-check {
  white-space: nowrap;
  font-size: var(--ui-font-11);
}

.gb-fmt-popup-row--wrap {
  flex-wrap: wrap;
  row-gap: var(--ui-space-3); /* 6px 縦方向 */
}

.gb-fmt-popup-row--bordered {
  border-bottom: 1px solid var(--border);
  padding-bottom: var(--ui-space-3);
}

/* ペア（ラベル+入力欄）グループ */
.gb-fmt-popup-group {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-1); /* 2px ペア内（密着） */
}

/* スウォッチ（背景色・文字色・枠線色・フチ色） */
.gb-fmt-swatch,
.gb-fmt-swatch-bg,
.gb-fmt-swatch-fg {
  width: 22px;
  height: 22px;
  min-width: 22px;
  min-height: 22px;
  padding: 0;
  box-sizing: border-box;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  cursor: pointer;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
}
/* 文字色系スウォッチは対象要素の背景色を JS で反映する。透明時は共通背景色に戻す。 */
.gb-fmt-swatch-fg {
  font-weight: bold;
  font-size: var(--ui-font-12);
  background: var(--bg);
}
.gb-fmt-swatch-fg svg {
  pointer-events: none;
}

.gb-fmt-swatch:disabled,
.gb-fmt-swatch[disabled],
.gb-fmt-swatch[aria-disabled="true"],
.gb-fmt-swatch.is-disabled,
.gb-fmt-swatch-bg:disabled,
.gb-fmt-swatch-bg[disabled],
.gb-fmt-swatch-bg[aria-disabled="true"],
.gb-fmt-swatch-bg.is-disabled,
.gb-fmt-swatch-fg:disabled,
.gb-fmt-swatch-fg[disabled],
.gb-fmt-swatch-fg[aria-disabled="true"],
.gb-fmt-swatch-fg.is-disabled {
  background: var(--ui-disabled-bg, #555) !important;
  border-color: transparent !important;
  color: var(--ui-disabled-fg, #888) !important;
  filter: grayscale(1) saturate(0) !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
  pointer-events: none !important;
}

/* スウォッチサイズモディファイア（フェーズE-2 で旧 sn2-*--xs / swatch-sm から移行） */
.gb-fmt-swatch--xs {
  width: 16px !important;
  height: 16px !important;
  min-width: 16px !important;
  min-height: 16px !important;
}
.gb-fmt-swatch--sm {
  width: 18px !important;
  height: 18px !important;
  min-width: 18px !important;
  min-height: 18px !important;
}

/* 書式トグルボタン（B/I/U/S） */
.gb-fmt-btn {
  height: 22px;
  min-width: 22px;
  padding: 0 var(--ui-space-2);
  box-sizing: border-box;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg);
  font-size: var(--ui-font-12);
  cursor: pointer;
  white-space: nowrap;
}
.gb-fmt-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--ui-fg-strong);
}
.gb-fmt-btn:disabled,
.gb-fmt-btn[disabled],
.gb-fmt-btn[aria-disabled="true"],
.gb-fmt-btn.is-disabled {
  background: var(--ui-disabled-bg, #555) !important;
  border-color: transparent !important;
  color: var(--ui-disabled-fg, #888) !important;
  filter: grayscale(1) saturate(0) !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
  pointer-events: none !important;
}

/* 数値入力（フォントサイズ等） */
input.gb-fmt-num {
  height: 22px;
  width: 70px;
  padding: 0 var(--ui-space-2);
  box-sizing: border-box;
  line-height: 1;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg);
  font-size: var(--ui-font-12);
  -moz-appearance: number-input;
}
input.gb-fmt-num.gb-fmt-num--w44 { width: 44px; }
input.gb-fmt-num.gb-fmt-num--w54 { width: 54px; }
input.gb-fmt-num.gb-fmt-num--w58 { width: 58px; }
input.gb-fmt-num.gb-fmt-num--w70 { width: 70px; }
input.gb-fmt-num.gb-fmt-num--w76 { width: 76px; }
/* スピンボックスは hover/focus でのみ表示（テーマは html の color-scheme で追従） */
input.gb-fmt-num::-webkit-outer-spin-button,
input.gb-fmt-num::-webkit-inner-spin-button {
  -webkit-appearance: auto;
  opacity: 0;
  transition: opacity 0.12s;
}
input.gb-fmt-num:hover::-webkit-outer-spin-button,
input.gb-fmt-num:hover::-webkit-inner-spin-button,
input.gb-fmt-num:focus::-webkit-outer-spin-button,
input.gb-fmt-num:focus::-webkit-inner-spin-button {
  opacity: 1;
}

.gb-fs-range-number {
  display: inline-flex;
  align-items: center;
  gap: var(--ui-space-2);
  max-width: 100%;
  min-width: 0;
}
.gb-fs-range-number__slider {
  flex: 1 1 120px;
  min-width: 90px;
  width: 160px;
  max-width: 100%;
  accent-color: var(--ui-range-fill-bg, var(--accent));
}
.gb-fs-range-number__input {
  flex: 0 0 auto;
}

/* テキスト入力（前/後） */
.gb-fmt-text {
  height: 22px;
  width: 36px;
  padding: 0 var(--ui-space-2);
  box-sizing: border-box;
  line-height: 1;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg);
  font-size: var(--ui-font-12);
}
.gb-fmt-text.gb-fmt-text--w36 { width: 36px; }
.gb-fmt-text.gb-fmt-text--w54 { width: 54px; }
.gb-fmt-text.gb-fmt-text--w60 { width: 60px; }
.gb-fmt-text.gb-fmt-text--w120 { width: 120px; }

/* select（配置・折返・形状等） */
.gb-fmt-sel {
  height: 22px;
  padding: 0 var(--ui-space-2);
  box-sizing: border-box;
  line-height: 1;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg);
  font-size: var(--ui-font-12);
}

.gb-fmt-sel--font {
  max-width: 170px;
}

/* ラベル（前/後/水平/垂直/px 等） */
.gb-fmt-label {
  font-family: var(--ui-muted-font, var(--ui-font, inherit));
  font-size: var(--ui-font-12);
  color: var(--fg2);
  line-height: 1;
  white-space: nowrap;
}
/* グループ見出しラベル（行頭の「ボード背景」「選択色」等）。
   UI 共通ルールに合わせて通常ウェイト。min-width で整列、色は fg2（他の項目名と同じ）。 */
.gb-fmt-label--group {
  color: var(--fg2);
  min-width: 5em;
}

/* リセットボタン（末尾に1個） */
.gb-fmt-reset {
  height: 22px;
  padding: 0 var(--ui-space-3);
  box-sizing: border-box;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg2);
  font-size: var(--ui-font-12);
  cursor: pointer;
  margin-left: auto; /* Row 2 の右端に寄せる */
}
.gb-fmt-reset:hover {
  background: var(--bg);
  color: var(--fg);
}

/* 書式コピー/貼り付けボタン（リセットと同じ見た目、右寄せはしない） */
.gb-fmt-style-copy {
  height: 22px;
  padding: 0 var(--ui-space-3);
  box-sizing: border-box;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--ui-radius-sm);
  background: var(--bg3);
  color: var(--fg2);
  font-size: var(--ui-font-12);
  cursor: pointer;
}
.gb-fmt-style-copy:hover:not(:disabled) {
  background: var(--bg);
  color: var(--fg);
}
/* 最初のコピー系ボタンを左端グループとして右寄せリセットから分離 */
.gb-fmt-style-copy + .gb-fmt-style-copy {
  margin-left: var(--ui-space-1);
}

/* 共通フッター行（コピー・切り取り・貼り付け・閉じる）
   計画書2026-08-04版§2.4: 最下段1行へ右寄せ配置し、閉じるを右端にする。 */
.gb-fmt-footer-actions-row {
  justify-content: flex-end;
  border-top: 1px solid var(--border);
  padding-top: var(--ui-space-3);
}
.gb-fmt-footer-close {
  margin-left: var(--ui-space-1);
}

@media (max-width: 640px), (pointer: coarse) {
  .gb-fmt-popup {
    max-width: calc(100vw - 16px);
    max-height: calc(100dvh - 16px);
    overflow-y: auto;
    box-sizing: border-box;
    gap: var(--ui-space-3);
    padding: var(--ui-space-3);
  }

  .gb-fmt-popup-row {
    flex-wrap: wrap;
    gap: var(--ui-space-3);
  }

  .gb-fmt-popup-group {
    min-height: 44px;
  }

  .gb-fmt-swatch,
  .gb-fmt-swatch-bg,
  .gb-fmt-swatch-fg,
  .gb-fmt-swatch--xs,
  .gb-fmt-swatch--sm {
    width: 44px !important;
    height: 44px !important;
    min-width: 44px !important;
    min-height: 44px !important;
  }

  .gb-fmt-btn,
  .gb-fmt-reset,
  .gb-fmt-style-copy,
  .gb-fmt-popup-group > .gb-btn-sm,
  .gb-fmt-popup .meldex-dropdown-close-btn,
  .gb-fmt-popup [data-meldex-dropdown-close] {
    min-width: 44px;
    height: 44px;
    min-height: 44px;
    padding: 0 var(--ui-space-4);
    font-size: var(--ui-font-14);
  }

  input.gb-fmt-num,
  input.gb-fmt-num.gb-fmt-num--w44,
  input.gb-fmt-num.gb-fmt-num--w54,
  input.gb-fmt-num.gb-fmt-num--w58,
  input.gb-fmt-num.gb-fmt-num--w70,
  input.gb-fmt-num.gb-fmt-num--w76,
  .gb-fmt-text,
  .gb-fmt-text.gb-fmt-text--w36,
  .gb-fmt-text.gb-fmt-text--w54,
  .gb-fmt-sel {
    height: 44px;
    min-height: 44px;
    font-size: var(--ui-font-14);
  }

  input.gb-fmt-num,
  input.gb-fmt-num.gb-fmt-num--w44,
  input.gb-fmt-num.gb-fmt-num--w54,
  input.gb-fmt-num.gb-fmt-num--w58,
  input.gb-fmt-num.gb-fmt-num--w70,
  input.gb-fmt-num.gb-fmt-num--w76 {
    width: 76px;
  }

  .gb-fmt-text,
  .gb-fmt-text.gb-fmt-text--w36,
  .gb-fmt-text.gb-fmt-text--w54,
  .gb-fmt-text.gb-fmt-text--w60,
  .gb-fmt-text.gb-fmt-text--w120 {
    width: 64px;
  }

  .gb-fmt-sel--font {
    max-width: min(100%, 220px);
  }
}

/* gb-db-filter-dialog.css — シート統合フィルタダイアログ（gb-db-filter-dialog.js）のスタイル。
   デスクトップ初期高は560px。画面が低い場合はビューポート内へ縮小し、本文だけスクロールする。 */

.gb-unified-filter-overlay .uf-modal {
  display: flex;
  flex-direction: column;
  max-height: min(560px, calc(100vh - 48px));
}

.gb-unified-filter-overlay .uf-modal h3 {
  flex: none;
  margin: 0 0 8px;
}

.gb-unified-filter-overlay .uf-modal-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding-right: 4px;
}

.gb-unified-filter-overlay .uf-modal .btn-row {
  flex: none;
}

@media (max-height: 640px) {
  .gb-unified-filter-overlay .uf-modal {
    max-height: calc(100vh - 24px);
  }
}

.uf-col-filter-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  font-size: 12px;
}

.uf-col-filter-row .uf-col-filter-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--fg);
}

.uf-col-filter-row button {
  font-size: 11px;
  padding: 2px 8px;
}

.uf-col-filter-empty {
  font-size: 11px;
  color: var(--fg2);
  padding: 2px 0 4px;
}

@media (max-width: 600px) {
  .gb-unified-filter-overlay .uf-modal-body,
  .gb-unified-filter-overlay .uf-modal-body > div {
    width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }

  .gb-unified-filter-overlay .uf-modal-body {
    overflow-x: hidden;
    max-width: 100%;
  }

  .gb-unified-filter-overlay .uf-modal > .gb-modal-body {
    overflow-x: hidden !important;
  }

  .gb-unified-filter-overlay .uf-modal-body label {
    min-height: 44px;
    white-space: nowrap;
  }

  .gb-unified-filter-overlay #uf-status-btns {
    flex-wrap: wrap;
  }

  .gb-unified-filter-overlay #uf-status-btns > button,
  .gb-unified-filter-overlay .uf-add-condition,
