/* Meldex共通の分割リング、操作進捗、画像読み込み表示。 */
@property --meldex-ring-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

:root {
  --meldex-progress-accent: var(--accent, #5b8def);
  --meldex-progress-track: color-mix(in srgb, var(--border, #59606b) 72%, transparent);
  --meldex-progress-surface: color-mix(in srgb, var(--bg2, #20242a) 94%, transparent);
  --meldex-progress-shadow: 0 12px 36px rgb(0 0 0 / 28%);
}

@keyframes meldex-segmented-ring-rotate {
  to { --meldex-ring-angle: 360deg; }
}

@keyframes meldex-progress-slide {
  from { transform: translateX(-130%); }
  to { transform: translateX(330%); }
}

.meldex-segmented-ring {
  display: inline-block;
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: repeating-conic-gradient(from var(--meldex-ring-angle), var(--meldex-progress-accent) 0 18deg, transparent 18deg 32deg);
  -webkit-mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  animation: meldex-segmented-ring-rotate .9s linear infinite;
}

.meldex-segmented-ring--small { width: 16px; height: 16px; }
.meldex-segmented-ring--large { width: 34px; height: 34px; }
.meldex-segmented-ring.is-static { animation: none; }
.meldex-segmented-ring.is-succeeded { background: var(--green, #58a66a); }
.meldex-segmented-ring.is-failed,
.meldex-segmented-ring.is-partial { background: var(--red, #e05d67); }
.meldex-segmented-ring.is-cancelled { background: var(--fg2, #9aa0a6); }

/* 既存の起動/全体読込リングも同じ分割リングへ揃える。 */
.gb-spinner,
.sa-spinner,
.bsa-loading-spinner,
.viewer-loading-spinner {
  border: 0 !important;
  border-radius: 50% !important;
  background: repeating-conic-gradient(from var(--meldex-ring-angle), var(--meldex-progress-accent) 0 18deg, transparent 18deg 32deg) !important;
  -webkit-mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  animation: meldex-segmented-ring-rotate .9s linear infinite !important;
}

img.meldex-image-is-loading {
  /* 可視リングは host の疑似要素だけが描く。img は読込状態と
     アクセシビリティ状態の保持に限定し、二重描画を防ぐ。 */
  color: transparent;
}

.meldex-image-load-host {
  position: relative;
}

.meldex-image-load-host.is-loading::before {
  position: absolute;
  z-index: 1;
  inset: 50% auto auto 50%;
  width: clamp(18px, 28%, 34px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: repeating-conic-gradient(from var(--meldex-ring-angle), var(--meldex-progress-accent) 0 18deg, transparent 18deg 32deg);
  content: '';
  pointer-events: none;
  transform: translate(-50%, -50%);
  -webkit-mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  mask: radial-gradient(circle, transparent 0 48%, #000 50% 100%);
  animation: meldex-segmented-ring-rotate .9s linear infinite;
}

.meldex-content-image-host {
  display: inline-block;
  min-inline-size: 32px;
  min-block-size: 32px;
  max-inline-size: 100%;
  vertical-align: middle;
}

.embed-media[data-meldex-image-host] {
  min-inline-size: 32px;
  min-block-size: 32px;
}

.meldex-content-image-host > img { max-inline-size: 100%; }

img.meldex-image-load-error {
  min-width: 96px;
  min-height: 64px;
  cursor: pointer;
  color: var(--fg2, #b8bec7);
  background:
    linear-gradient(135deg, transparent 47%, var(--red, #e05d67) 48% 52%, transparent 53%),
    color-mix(in srgb, var(--red, #e05d67) 8%, var(--bg2, #20242a));
  border: 1px solid color-mix(in srgb, var(--red, #e05d67) 55%, var(--border, #59606b));
}

.meldex-image-load-host.is-error::after {
  position: absolute;
  inset: 50% auto auto 50%;
  max-width: calc(100% - 12px);
  padding: 3px 6px;
  color: var(--fg, #e7e9ec);
  background: color-mix(in srgb, var(--bg2, #20242a) 88%, transparent);
  border-radius: 4px;
  content: attr(data-meldex-image-error-label);
  font-size: 10px;
  line-height: 1.3;
  pointer-events: none;
  text-align: center;
  transform: translate(-50%, -50%);
}

.meldex-operation-tray {
  position: fixed;
  /* 操作中のメニュー・ダイアログを覆わず、通常のアプリ面より手前に置く。 */
  z-index: calc(var(--ui-z-modal, 300) - 1);
  /* 右端レールと、その下寄せクイックメモボタンの左側へ逃がす。 */
  right: calc(14px + var(--gb-rail-width, 38px) + 8px);
  bottom: calc(34px + env(safe-area-inset-bottom, 0px));
  width: min(360px, calc(100vw - 28px - var(--gb-rail-width, 38px) - 8px));
  max-height: min(62vh, 520px);
  overflow: hidden;
  color: var(--fg, #e7e9ec);
  background: var(--meldex-progress-surface);
  border: 1px solid var(--border, #59606b);
  border-radius: 10px;
  box-shadow: var(--meldex-progress-shadow);
