/* オプションパネル内タブの並べ替え */
#detail-tab-bar .detail-tab[draggable="true"] {
  cursor: grab;
}

#detail-tab-bar .detail-tab[draggable="true"]:active {
  cursor: grabbing;
}

#detail-tab-bar .detail-tab.dragging {
  opacity: 0.45;
}

#detail-tab-bar .detail-tab.drag-over-left {
  box-shadow: inset 3px 0 0 var(--ui-accent, var(--accent));
}

#detail-tab-bar .detail-tab.drag-over-right {
  box-shadow: inset -3px 0 0 var(--ui-accent, var(--accent));
}

/* gb-file-lock-badge.css — ツールバータイトル直前の編集ロックバッジ
   gb-file-lock-badge.js が挿入する .tb-lock-badge のスタイル。
   ツールバーの flex 行で潰れないよう flex:0 0 auto を指定する。 */
.tb-lock-badge {
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  margin-right: 4px;
}

.file-embedded-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
  min-width: 0;
}

/* 主要項目・埋め込み情報グループが無いファイルでは、空のスロットぶんの余白を作らない */
.file-embedded-panel > [data-file-embedded-primary]:empty,
.file-embedded-panel > [data-file-embedded-groups]:empty {
  display: none;
}

.file-embedded-row {
  display: grid;
  grid-template-columns: minmax(82px, auto) minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  font-size: 12px;
}

.file-embedded-key {
  color: var(--fg2);
  white-space: nowrap;
}

.file-embedded-value {
  min-width: 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.file-embedded-value a {
  color: var(--accent);
}

.file-rating {
  display: inline-flex;
  gap: 2px;
  align-items: center;
}

.file-rating button {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--fg3);
  cursor: pointer;
  font-size: 19px;
  line-height: 1;
  padding: 1px;
}

.file-rating button.is-active {
  color: #f1b928;
}

.file-rating button:disabled {
  cursor: default;
  opacity: .58;
  border-color: transparent;
}

.file-rating button:focus-visible {
  border-radius: 3px;
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.file-rating--compact {
  gap: 0;
  padding: 0;
  background: transparent;
}

.file-rating--compact button {
  color: var(--fg3);
  font-size: 13px;
  text-shadow: none;
}

.file-rating--compact button.is-active {
  color: #ffd75c;
}

.file-embedded-memo {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 2px;
}

.file-embedded-memo > label,
.file-embedded-heading {
  color: var(--fg2);
  font-size: 12px;
}

.file-embedded-memo textarea {
  box-sizing: border-box;
  min-height: 76px;
  width: 100%;
  resize: vertical;
  border: 1px solid var(--border);
  border-radius: 5px;
  background: var(--bg);
  color: var(--fg);
  padding: 7px 8px;
  font: inherit;
  line-height: 1.45;
}

.file-embedded-memo textarea:focus {
  border-color: var(--accent);
  outline: 1px solid var(--accent);
}

.file-embedded-memo-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  color: var(--fg3);
  font-size: 11px;
  /* 保存状態の文字が出入りしても入力欄の位置が動かないよう高さを固定する */
  min-height: 14px;
}

/* 自動保存の状態表示（未保存 / 保存中... / 保存しました） */
.file-embedded-memo-status {
  color: var(--fg3);
}

.file-embedded-memo-status--error {
  color: var(--danger, #e5534b);
}

/* タグはメモ入力欄の下（埋め込み情報グループの上）。上の主要項目と少しだけ間隔を空ける */
.file-embedded-panel > [data-global-tags-target-path] {
  margin-top: 6px;
}

.file-embedded-heading {
  margin-top: 6px;
  font-weight: 600;
}

.file-embedded-group {
  border: 1px solid var(--border);
  border-radius: 5px;
  overflow: hidden;
}

.file-embedded-group > summary {
  cursor: pointer;
  padding: 6px 8px;
  background: var(--bg2);
  color: var(--fg2);
  font-size: 12px;
  user-select: none;
}

.file-embedded-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 260px;
  overflow: auto;
  padding: 7px 8px;
}

.file-embedded-empty {
  margin-top: 8px;
  color: var(--fg3);
  font-size: 12px;
}

.file-embedded-error {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  color: var(--danger, var(--red, #e36b6b));
}

.fv-thumb--embedded {
  position: relative;
}

.fv-image-dimensions {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.fv-image-rating-host {
  display: flex;
  justify-content: center;
  min-width: 100%;
}

.fv-folder-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 3px;
  min-width: 0;
  width: 100%;
}

.fv-folder-tag {
  min-width: 0;
  max-width: 92px;
}

.fv-folder-tag .gb-tag-chip__label {
  max-width: 90px;
}

.fv-folder-tag--more {
  max-width: none;
}

.list-layout .fv-image-rating-host {
  justify-content: flex-start;
  min-width: auto;
}

.list-layout .fv-folder-tags {
  justify-content: flex-start;
  width: auto;
}

/* gb-shortcut-registry.css
 * ショートカットキー一覧（設定ダイアログとオプションパネルで共用）。
 * 共通UIルールの4階層規則（.gb-section → .gb-section-title → .gb-field-row）に乗せ、
 * 行ごとのインラインstyleを持たせない。
 */

.shortcut-settings-wrap {
  /* 一覧だけを500pxの内側スクロールにすると、「すべて」でも先頭の
     「全体」グループしかないように見える。設定ダイアログ本体の
     スクロールへ統一し、後続のアプリ別グループまで連続して表示する。 */
  max-height: none;
  overflow-y: visible;
}

/* オプションパネル内では枠を付けず、パネルの高さいっぱいまで使う */
.shortcut-settings-wrap.gb-section--detail {
  max-height: none;
  overflow-y: visible;
}

.shortcut-sync-toggle {
  font-size: 12px;
}

/* 「すべて」では複数の分類が表示されていることを最初の画面内でも
   判別できるよう、設定ダイアログだけを2列にする。検索中と分類指定時は
   従来どおり1列で、狭幅時も1列へ戻す。 */
.shortcut-settings-wrap.gb-section--boxed.is-multi-scope {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 16px;
  align-items: start;
}

.shortcut-settings-wrap.gb-section--boxed.is-multi-scope > .gb-section-title,
.shortcut-settings-wrap.gb-section--boxed.is-multi-scope > .shortcut-sync-toggle,
.shortcut-settings-wrap.gb-section--boxed.is-multi-scope > .shortcut-settings-filter,
.shortcut-settings-wrap.gb-section--boxed.is-multi-scope > [data-shortcut-empty] {
  grid-column: 1 / -1;
}

/* 検索・絞り込み・リセットの行。オプションパネルは幅が狭い（既定360px）ので、
   固定の3列グリッドにすると検索欄が潰れる。入りきらない分は折り返す。 */
.shortcut-settings-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin-bottom: 8px;
}

.shortcut-settings-filter .gb-input {
  flex: 1 1 140px;
  min-width: 120px;
}

.shortcut-settings-filter .gb-select {
  flex: 0 1 auto;
  min-width: 110px;
  max-width: 100%;
}

.shortcut-settings-filter .gb-btn {
  white-space: nowrap;
  flex: 0 0 auto;
}

.shortcut-group {
  margin-top: 10px;
}

.shortcut-group-head {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  font-size: 12px;
  padding: 6px 0 4px;
  border-bottom: 1px solid var(--ui-border, var(--border));
  margin-bottom: 2px;
}

.shortcut-group-count {
  margin-left: auto;
  margin-bottom: 0;
}

.shortcut-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
  flex-wrap: nowrap;
}

.shortcut-row .shortcut-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shortcut-status {
  flex: 0 0 auto;
  width: 52px;
  text-align: center;
  font-size: 11px;
  color: var(--ui-fg-muted, var(--fg2));
}

.shortcut-status.is-custom {
  color: var(--ui-accent, var(--accent));
}

.shortcut-key {
  flex: 0 0 auto;
  min-width: 116px;
  text-align: center;
  padding: 2px 8px;
  font-size: 12px;
  background: var(--bg3);
  border: 1px solid var(--ui-border, var(--border));
  border-radius: 3px;
  cursor: pointer;
}

.shortcut-key.is-custom {
  color: var(--ui-accent, var(--accent));
}

/* マウス操作・スペースキーの操作は表示専用（割り当ての変更対象にしない） */
.shortcut-key.is-readonly {
  cursor: default;
  background: transparent;
  border-style: dashed;
  color: var(--fg2);
}

.shortcut-key:focus-visible {
  outline: 2px solid var(--ui-accent, var(--accent));
  outline-offset: 1px;
}

.shortcut-key.is-capturing {
  background: var(--ui-accent, var(--accent));
  color: #fff;
}

.shortcut-row .shortcut-reset,
.shortcut-reset-spacer {
  flex: 0 0 auto;
  width: 26px;
}

.shortcut-row .shortcut-reset {
  padding: 1px 4px;
}

/* 行が狭いときは、キー欄を優先して残しつつ操作名を縮める */
@media (max-width: 480px) {
  .shortcut-settings-wrap.gb-section--boxed.is-multi-scope {
    grid-template-columns: minmax(0, 1fr);
  }

  .shortcut-key {
    min-width: 96px;
  }
}

.folder-multi-info {
  padding: 12px;
  color: var(--fg);
}
.folder-multi-info-title {
  margin: 0 0 4px;
  font-size: 15px;
}
.folder-multi-info-description,
.folder-multi-info-empty,
.folder-multi-info-loading {
  margin: 0;
  color: var(--fg2);
  font-size: 12px;
  line-height: 1.5;
}
.folder-multi-info-warning {
  margin-top: 10px;
  padding: 8px;
  color: var(--ui-warning, var(--orange));
  background: color-mix(in srgb, var(--ui-warning, var(--orange)) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--ui-warning, var(--orange)) 45%, transparent);
  border-radius: var(--ui-radius-sm, 4px);
  font-size: 12px;
  line-height: 1.5;
}
.folder-multi-info-table {
  width: 100%;
  margin-top: 10px;
  border-collapse: collapse;
  font-size: 13px;
}
.folder-multi-info-label {
  width: 1%;
  padding: 4px 8px 4px 0;
  color: var(--fg2);
  white-space: nowrap;
  vertical-align: top;
}
.folder-multi-info-value {
  padding: 4px 0;
  overflow-wrap: anywhere;
}
.folder-multi-info-link {
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  cursor: pointer;
}
.folder-multi-info-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.folder-multi-info-tags {
  margin-top: 12px;
}
.folder-multi-info-tags h3 {
  margin: 0 0 6px;
  color: var(--fg2);
  font-size: 12px;
}
.folder-multi-info-tag-list {
  display: flex;
  flex-wrap: wrap;
