  border-radius: 4px;
  background: transparent;
  color: var(--fg2);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.at-segment:hover {
  color: var(--fg);
  background: var(--hover);
}

.at-segment.is-active {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, transparent);
  color: var(--accent);
}

.at-help {
  margin: 7px 0 0;
  color: var(--fg2);
  font-size: 11px;
  line-height: 1.5;
}

.at-model-layout {
  gap: 18px;
  margin-top: 18px;
  align-items: stretch;
}

.at-model-layout > div {
  flex: 1.2 1 0;
  min-width: 0;
}

.at-model-list {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.at-model-card {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  width: 100%;
  min-height: 68px;
  padding: 10px 12px;
  border: 0;
  border-bottom: 1px solid var(--border);
  background: transparent;
  color: var(--fg);
  text-align: left;
  cursor: pointer;
}

.at-model-card:last-child {
  border-bottom: 0;
}

.at-model-card:hover {
  background: var(--hover);
}

.at-model-card.is-selected {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  box-shadow: inset 2px 0 var(--accent);
}

.at-model-check {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 50%;
  color: white;
}

.at-model-card.is-selected .at-model-check {
  border-color: var(--accent);
  background: var(--accent);
}

.at-model-main,
.at-model-meta {
  display: flex;
  flex-direction: column;
}

.at-model-main {
  min-width: 0;
  gap: 4px;
}

.at-model-name {
  font-size: 13px;
  font-weight: 600;
}

.at-model-sub {
  overflow: hidden;
  color: var(--fg2);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.at-model-meta {
  align-items: flex-end;
  gap: 6px;
}

.at-model-badges {
  display: flex;
  gap: 4px;
}

.at-model-badges span {
  padding: 2px 5px;
  border: 1px solid var(--border);
  border-radius: 3px;
  color: var(--fg2);
  font-size: 9px;
}

.at-ready {
  font-size: 10px;
  font-weight: 600;
}

.at-ready--ready { color: var(--green, #56c475); }
.at-ready--warn { color: var(--yellow, #d8a84e); }
.at-ready--error { color: var(--red, #e36b6b); }
.at-ready--neutral { color: var(--fg2); }

.at-model-detail {
  flex: .8 1 0;
  min-width: 240px;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg2) 72%, transparent);
}

.at-detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.at-detail-name {
  margin-bottom: 3px;
  font-size: 14px;
  font-weight: 650;
}

.at-detail-size {
  color: var(--fg2);
  font-size: 10px;
  white-space: nowrap;
}

.at-model-detail h4 {
  margin: 12px 0 4px;
  font-size: 11px;
}

.at-model-detail p,
.at-guide-list,
.at-install-path {
  color: var(--fg2);
  font-size: 11px;
  line-height: 1.55;
}

.at-model-detail p {
  margin: 0;
}

.at-guide-list {
  margin: 0;
  padding-left: 18px;
}

.at-guide-list li + li {
  margin-top: 3px;
}

.at-install-path {
  overflow-wrap: anywhere;
  margin-top: 9px;
}

.at-detail-actions,
.at-dictionary-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

/* Web Clipper待ち行列(Phase 8: 2026-08-14自動タグ付け計画) */
.at-pending-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg2) 82%, transparent);
  font-size: 12px;
}

.at-pending-row + .at-pending-row {
  margin-top: 6px;
}

.at-install-state {
  margin-top: 9px !important;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: color-mix(in srgb, var(--bg3, var(--bg2)) 72%, transparent);
  overflow-wrap: anywhere;
}

.at-install-state--working { color: var(--accent, #5b9cff) !important; }
.at-install-state--ready { color: var(--green, #56c475) !important; }
.at-install-state--warn { color: var(--yellow, #d8a84e) !important; }
.at-install-state--error { color: var(--red, #e36b6b) !important; }

.at-preset-options {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.at-preset-option {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 3px 8px;
  color: var(--fg);
  background: var(--bg3);
  border: 1px solid var(--ui-border, var(--border));
  border-radius: var(--ui-radius-md, 6px);
  font-size: 12px;
  cursor: pointer;
}

.at-preset-option:has(input:checked) {
  color: var(--ui-accent, var(--accent));
  border-color: var(--ui-accent, var(--accent));
  background: color-mix(in srgb, var(--ui-accent, var(--accent)) 10%, var(--bg3));
}

.at-preset-option input {
  margin: 0;
}

.at-run-presets {
  padding: 6px 0;
}

.at-run-presets summary {
  margin-bottom: 6px;
  color: var(--fg2);
  font-size: 12px;
  cursor: pointer;
}

.at-lower-grid {
  gap: 18px;
  margin-top: 18px;
}

.at-device-block,
.at-dictionary-card {
  flex: 1 1 0;
  min-width: 0;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.at-device-block > select {
  width: min(100%, 280px);
}

.at-thresholds {
  margin-top: 12px;
  color: var(--fg2);
  font-size: 11px;
}

.at-thresholds summary {
  cursor: pointer;
}

.at-thresholds label {
  display: grid;
  grid-template-columns: 1fr 92px;
  gap: 8px;
  align-items: center;
  margin-top: 8px;
}

.at-adult-option {
  align-items: flex-start;
  margin-top: 14px;
  font-size: 11px;
}

.at-adult-option span,
.at-run-head > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.at-adult-option small,
.at-run-head small {
  color: var(--fg2);
  font-size: 10px;
  line-height: 1.4;
}

.at-dictionary-title {
  display: flex;
  gap: 7px;
  align-items: center;
  margin-bottom: 6px;
  font-size: 13px;
  font-weight: 650;
}

.at-dictionary-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.at-dictionary-counts span {
  padding: 4px 7px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg2);
  font-size: 10px;
}

.at-dictionary-counts strong {
  color: var(--fg);
}

.at-settings-footer {
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 18px;
}

.at-settings-footer > span {
  color: var(--fg2);
  font-size: 10px;
}

.at-loading,
.at-error {
  padding: 18px;
  color: var(--fg2);
  font-size: 12px;
}

.at-cloud-unavailable {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg2) 82%, transparent);
}

.at-cloud-unavailable-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 9px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

.at-cloud-unavailable h3 {
  margin: 0 0 7px;
  color: var(--fg);
  font-size: 14px;
}

.at-cloud-unavailable p {
  margin: 0;
  color: var(--fg2);
  font-size: 12px;
  line-height: 1.65;
}

.at-cloud-unavailable-note {
  margin-top: 7px !important;
}

.at-error {
  color: var(--red, #e36b6b);
}

.at-run-panel {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg2) 70%, transparent);
}

.at-run-head {
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.at-run-head strong {
  display: flex;
  gap: 6px;
  align-items: center;
  font-size: 12px;
}

.at-run-panel > label {
  display: grid;
  grid-template-columns: 55px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin-top: 7px;
  color: var(--fg2);
  font-size: 11px;
}

.at-run-footer {
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 10px;
}

.at-run-ready {
  font-size: 10px;
}

/* The local/cloud touch UI also runs at tablet widths above the phone layout. */
body[data-cloud-mobile="1"] .gb-tag-management-panel .at-run-panel select,
body[data-cloud-mobile="1"] .gb-tag-management-panel .at-run-panel button,
body[data-cloud-mobile="1"] .gb-tag-management-panel .at-run-presets > summary,
body[data-cloud-mobile="1"] .gb-tag-management-panel .at-run-presets .at-preset-option,
body[data-mobile-ui-local="1"] .gb-tag-management-panel .at-run-panel select,
body[data-mobile-ui-local="1"] .gb-tag-management-panel .at-run-panel button,
body[data-mobile-ui-local="1"] .gb-tag-management-panel .at-run-presets > summary,
body[data-mobile-ui-local="1"] .gb-tag-management-panel .at-run-presets .at-preset-option {
  min-height: 44px !important;
  box-sizing: border-box;
}

body[data-cloud-mobile="1"] .gb-tag-management-panel .at-run-panel button,
body[data-mobile-ui-local="1"] .gb-tag-management-panel .at-run-panel button {
  min-width: 44px;
}

@media (max-width: 820px) {
  .gb-tag-management-panel .at-run-panel select,
  .gb-tag-management-panel .at-run-panel button,
  .gb-tag-management-panel .at-run-presets > summary,
  .gb-tag-management-panel .at-run-presets .at-preset-option {
    min-height: 44px !important;
    box-sizing: border-box;
  }

  .gb-tag-management-panel .at-run-panel button {
    min-width: 44px;
  }

  .gb-tag-management-panel .at-run-presets > summary {
    display: flex;
    align-items: center;
  }

  .at-settings-head,
  .at-model-layout,
  .at-lower-grid {
    flex-direction: column;
  }

  .at-settings-head {
    align-items: stretch;
  }

  .at-switch-row {
    width: fit-content;
  }

  .at-model-detail {
    min-width: 0;
  }

  .at-segments {
    display: flex;
    width: 100%;
  }

  .at-segment {
    flex: 1 1 0;
    padding-inline: 6px;
  }

  .at-model-card {
    grid-template-columns: 22px minmax(0, 1fr);
  }

  .at-model-meta {
    grid-column: 2;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .settings-modal .gb-modal-shell-header {
    min-width: 0;
  }

  .settings-modal #settings-header {
    flex: 1 1 auto !important;
    width: 100%;
    min-width: 0;
  }

  .settings-modal #settings-header-text {
    flex: 1 1 auto;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .settings-modal #settings-back-btn,
  .settings-modal #settings-modal-close {
    flex: 0 0 44px;
  }

  .at-model-sub {
    white-space: normal;
  }
}

.at-job-tray {
  position: fixed;
  right: 16px;
  bottom: 28px;
  z-index: 12000;
  width: min(380px, calc(100vw - 32px));
  max-height: min(70vh, 640px);
  color: var(--fg);
  background: var(--ui-popup-bg, var(--bg2));
  border: 1px solid var(--ui-popup-border, var(--ui-border-strong, var(--border)));
  border-radius: var(--ui-radius-lg, 8px);
  box-shadow: var(--ui-shadow-lg, 0 10px 30px rgba(0, 0, 0, 0.36));
  overflow: hidden;
}

.at-job-tray[hidden] {
  display: none;
}

.at-job-tray-head {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 4px 8px 4px 12px;
  border-bottom: 1px solid var(--ui-border, var(--border));
  background: var(--bg3);
}

.at-job-tray-head strong {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
}

.at-job-tray-head > span {
  color: var(--fg2);
  font-size: 11px;
}

.at-job-list {
  max-height: calc(min(70vh, 640px) - 36px);
  overflow: auto;
}

.at-job-tray--minimized .at-job-list {
  display: none;
}

.at-job {
  padding: 10px 12px;
  border-bottom: 1px solid var(--ui-border, var(--border));
}

.at-job:last-child {
  border-bottom: 0;
}

.at-job-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.at-job-head strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.at-job-head span,
.at-job-stats,
.at-job-current {
  color: var(--fg2);
  font-size: 11px;
}

.at-job-progress {
  height: 4px;
  margin-top: 8px;
  overflow: hidden;
  background: var(--bg4);
  border-radius: 3px;
}

.at-job-progress > span {
  display: block;
  height: 100%;
  background: var(--ui-accent, var(--accent));
  transition: width 180ms ease-out;
}

.at-job--running .at-job-progress > span[style="width:0%"] {
  width: 22% !important;
  animation: at-job-indeterminate 1.4s ease-in-out infinite alternate;
}

.at-job--error .at-job-progress > span,
.at-job--partial .at-job-progress > span {
  background: var(--danger, #e55353);
}

.at-job-message,
.at-job-stats,
.at-job-current {
  margin: 6px 0 0;
  line-height: 1.4;
}

.at-job-message {
  font-size: 12px;
}

.at-job-current {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.at-job-failures {
  margin-top: 8px;
  color: var(--fg2);
  font-size: 11px;
}

.at-job-failures summary {
  cursor: pointer;
  color: var(--danger, #e55353);
}

.at-job-failures ul {
  max-height: 180px;
  margin: 6px 0 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}

.at-job-failures li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 2px 6px;
  padding: 5px 0;
  border-top: 1px solid var(--ui-border, var(--border));
}

.at-job-failures li > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.at-job-failures li > small {
  grid-column: 1 / -1;
  overflow-wrap: anywhere;
}

.at-job-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 8px;
}

@keyframes at-job-indeterminate {
  from { transform: translateX(-20%); }
  to { transform: translateX(360%); }
}

@media (prefers-reduced-motion: reduce) {
  .at-job-progress > span {
    transition: none;
    animation: none !important;
  }
}

@media (max-width: 820px) {
  .at-job-tray {
    right: 8px;
    bottom: calc(8px + env(safe-area-inset-bottom, 0px));
    width: calc(100vw - 16px);
    max-height: 55vh;
  }

  .at-job-tray-head {
    min-height: 44px;
  }

  .at-job-actions .gb-btn {
    min-height: 44px;
  }
}
